/**
 * Refill-ветка стадии base_collect (ENG auto-pipeline Движка вертикалей):
 * ежедневный добор лидов в УЖЕ запущенную кампанию us-проекта.
 *
 * Срабатывает только при payload.refill джобы (такую джобу ставит крон
 * app/worker/heAutoPipelineCron.ts через enqueueHeBaseCollect с refill-полями).
 * Отличия от обычного пути base_collect:
 *   - base_analyze и template НЕ ставятся — собранные строки не идут в мастер,
 *     а мапятся в лиды и доливаются в существующую кампанию Instantly;
 *   - кампания: collect_info.campaign_id (снапшот на постановке), фолбэк —
 *     последний по дате запуска шаблон вертикали с launch_info; маппинг
 *     колонок → переменные — operator_mapping того же шаблона (как при
 *     первичном запуске, mapBaseRowsToLeads из launchHandoff); у market='us'
 *     — с заменами пустых ячеек, как у запуска (heRefillOperatorMapping), и
 *     без строк, которым письмо кампании прочиталось бы неверно
 *     (heRefillUnfilledRows: тот же гейт писем, что у запуска; такие строки
 *     считаются в stats.held_unfilled, а компании, у которых других адресов
 *     нет, у market='us' ждут в очереди переноса с пометкой «ждёт писем» —
 *     блок «ПЕРЕНОС», HE_REFILL_CARRY_HELD_REASON; снята ВСЯ ночь — алерт
 *     команде, alertRefillLettersHeld);
 *   - кампания — ОСНОВНАЯ кампания запуска (segment=null). У market='us' и
 *     запуска, сплитнутого по сегментам, пачка ночи, уже срезанная дневным
 *     капом, раскладывается по сегментным кампаниям того же запуска тем же
 *     классификатором, что у запуска (routeHeRefillSegments, блок «РАСКЛАДКА»):
 *     строка сегмента — в кампанию сегмента, без сегмента, без ответа, без
 *     кампании своего сегмента или с завершённой — в основную; строка
 *     сегмента, чья кампания не отправляет (остановлена рассыльщиком, удалена,
 *     стоит, статус не подтверждён), не уходит никуда — её компания ждёт в
 *     очереди переноса (п. 4 «РАСКЛАДКИ»); сегментная кампания, явно
 *     отказавшая без единого приёма уже при загрузке (удалена или в архиве у
 *     рассыльщика после шага 4c), отдаёт свои строки основной в том же
 *     прогоне (п. 7 «РАСКЛАДКИ»);
 *   - лиды: только строки с email И ДОПУЩЕННЫМ вердиктом валидации. Список
 *     допущенных вердиктов и их ранжирование здесь НЕ дублируются — вердикт
 *     считает heLaunchEmailVerdict (launchHandoff.ts), тот же, что у ручного
 *     запуска: два контура обязаны допускать ровно одно и то же, иначе
 *     ночной долив разойдётся с проверенным руками запуском;
 *   - вердикт ОБЯЗАТЕЛЕН (fail-closed). Строка без вердикта («Email Статус»
 *     пуст или колонки нет вовсе: конструктор упал после split_emails, не
 *     дойдя до validate_emails, и его частичная сетка импортирована) в
 *     кампанию НЕ идёт. Раньше такая строка проходила как проверенная, и
 *     непроверенные адреса уезжали в живую рассылку без человека рядом —
 *     баунсы бьют по доменам ящиков клиента, обратной связи по ним у движка
 *     нет. Сколько строк так снято — stats.unverified, отдельно от
 *     отклонённых;
 *   - кап daily_leads_cap конфига — на ПРОЕКТ в сутки (UTC), и берётся он
 *     БРОНЬЮ, а не разностью двух чтений журнала: he_reserve_refill_daily_budget
 *     (миграция 20260930_0004) под advisory-локом «проект + UTC-день»
 *     замораживает кап дня, считает занятое другими бронями и выдаёт остаток,
 *     после долива бронь закрывается фактическим расходом. Незакрытая бронь
 *     держит весь свой объём до конца суток — упавший воркер поэтому даёт
 *     НЕДОотправку, а не отправку поверх капа. Одна бронь на (базу, сутки):
 *     повторный прогон той же базы второй порции не получает и ничего не
 *     отправляет (stats.capped_reason='repeat_run'). ИСКЛЮЧЕНИЕ — своя же
 *     бронь, открытая дольше ОКНА ПЕРЕХВАТА (два часа): её держатель мёртв,
 *     и наследник забирает бронь себе (stats.budget_outcome='reclaimed'),
 *     иначе смерть воркера посреди долива стоила бы ночи целиком. Чужой
 *     объём возраст не освобождает никогда;
 *   - НОЧЬ, КОТОРОЙ БЮДЖЕТ ПРОЕКТА НЕ ДАЛ НИ СТРОКИ ('cap_exhausted'), НЕ
 *     ВЫЖИГАЕТ СВОИ КОМПАНИИ НИКОГДА: от этой базы провайдер сегодня не получил
 *     ничего, и долив уходит в общий отказ, а такие ночи в серию
 *     (refillFailStreak) не идут вовсе — они говорят о бюджете, а не о срезе.
 *     У market='us' (решение владельца 04.10.2026: подготовленные и не
 *     получившие письма компании не выбрасывать) её компании уходят в ОЧЕРЕДЬ
 *     ПЕРЕНОСА, а база остаётся 'analyzed' и держит их исключёнными, пока они
 *     ждут: следующая ночь отправляет их первыми и сборку под них не покупает.
 *     Раньше они возвращались в пул ('failed'), и следующая сборка покупала их
 *     ЗАНОВО (гейт, краул, SMTP-пробы): при дефолтах (кап 50 лидов, пол 100
 *     компаний, три вертикали за тик) кап покрывает ОДНУ вертикаль за ночь, и
 *     две проигравшие бронь платили так каждую ночь. Очередь не записалась —
 *     прежний возврат в пул. Вне market='us' — прежний возврат. Другой нулевой
 *     исход — 'already_reserved' — компании НЕ возвращает и НЕ переносит: бронь
 *     этой же базы держит её прошлый прогон, который мог уже отдать строки
 *     провайдеру (см. refillLeadsReachedProvider), и любая их повторная
 *     отправка могла бы стать вторым письмом. Тихий 'appended' с нулём здесь
 *     означал бы «компании отработаны», хотя писем не было;
 *   - каждый лид помечен строкой базы, из которой вырос: custom-переменная
 *     source_row_id вида «<база>:<нормализованное имя компании>». Её подхватывает
 *     ОБЩИЙ построчный журнал доставки (client_campaign_contact_ledger, строка
 *     на лида) — своего журнала ветка не заводит;
 *   - кап считает СТРОКИ (после split_emails строка = один адрес = один лид), а
 *     сборка считает КОМПАНИИ, и одна компания даёт до max_emails_per_company
 *     строк. Разные единицы у бюджета и у сборки — это оплаченный краул сайта и
 *     SMTP-проба на каждый адрес, который кап потом выбросит, причём компания
 *     остаётся выжженной (база уходит в 'analyzed' и её компании исключены из
 *     будущих сборок проекта). Поэтому размер сборки обязан считаться ИЗ ОСТАТКА
 *     капа на сегодня (кап минус долитое другими вертикалями этой же ночи):
 *     heRefillCompanyTarget / resolveHeRefillCollectCompanies ниже, разошедшиеся
 *     единицы видны в stats.company_target против stats.company_limit;
 *   - у рассыльщика кончилось место под контакты — это ПАУЗА, а не брак данных:
 *     долив идёт с pauseOnWorkspaceCapacity, грузит столько, сколько влезает,
 *     остаток считается stats.deferred (отдельно от окончательных отказов
 *     skipped_instantly и от нашего кап-отреза capped), а полный отказ получает
 *     машинный error_kind='instantly_capacity' рядом с текстом. Сам факт
 *     переполнения при этом ЗАПИСЫВАЕТСЯ дальше одной ночи: он ставит
 *     durable-паузу ПРОЕКТА (he_auto_pipeline_configs.refill_paused_at,
 *     миграция 20260930_0005), и завтрашний тик крона сборку не покупает, пока
 *     сотрудник не возобновит добор кнопкой staff-инструмента. Это главный
 *     путь записи паузы: предполёт ёмкости в кроне работает только с правом
 *     читать биллинг воркспейса, а отказ провайдера здесь — всегда. В момент
 *     записи паузы команда получает алерт в health-бот
 *     (alertRefillCapacityStop → opsAlert.notifyHeClientStop): кабинет ENG
 *     пишет клиенту «временная проблема, команда уже работает», и вторая
 *     половина фразы держится на этом вызове. Сама пауза ОТЛОЖЕННЫЕ СТРОКИ не
 *     хранит — их хранит ПЕРЕНОС (ниже): компании ночи, ни один адрес которых
 *     до провайдера не дошёл, уходят в очередь he_refill_carryover и после
 *     снятия паузы идут первыми, пока не вышел их срок;
 *   - ПЕРЕНОС НЕОТПРАВЛЕННЫХ КОМПАНИЙ (решение владельца 04.10.2026, только
 *     market='us', миграция 20261004_0001). Компания ночи, которой не досталось
 *     ни одного письма — её срезал дневной кап, её адреса провайдер не взял по
 *     ёмкости, бюджет дня не дал ночи ни строки, ночь упала после частичной
 *     доставки или письмо кампании прочиталось бы неверно у каждого её адреса
 *     (решение владельца 10.10.2026), — больше не выжигается: её допущенные
 *     строки ложатся в he_refill_carryover, а следующая ночь вертикали
 *     предлагает их ПЕРВЫМИ, раньше новых компаний, и не покупает сборку
 *     вовсе, если перенесённых компаний, которые письма не держат, хватает на
 *     остаток дня (resolveHeRefillCollectCompanies → carryOnly). Полный
 *     разбор — блок «ПЕРЕНОС» ниже;
 *   - долив грузит лидов с skipIfInCampaign=true, а этот флаг у Instantly (по
 *     нашему собственному свидетельству, докблок в clientLaunch/appendLeads.ts)
 *     работает НА ВЕСЬ ВОРКСПЕЙС: адрес отсеивается, если он есть в ЛЮБОЙ
 *     кампании аккаунта, в том числе в кампании ДРУГОГО клиента студии. Такой
 *     контакт оплачен сбором и не будет отправлен никогда. Флаг в этой волне
 *     НЕ менялся; появился ЗАМЕР (шаг 4b, HeRefillSkipProbe): по выборке из
 *     пачки видно, сколько адресов лежит в НАШЕЙ кампании (законный отсев),
 *     сколько в ЧУЖОЙ (цена флага) и сколько в воркспейсе нет вовсе. Замер
 *     только считает: он ничего не фильтрует, поэтому ни один его исход,
 *     включая «не знаю», не стоит ни одного контакта. ПО УМОЛЧАНИЮ ОН
 *     ВЫКЛЮЧЕН (HE_REFILL_SKIP_PROBE_REQUESTS): его запросы берут токены
 *     общего с живой RU-рассылкой лимитера воркспейса, и платить ими за
 *     измерение можно только тогда, когда решение по флагу принимается;
 *   - идемпотентность ночного добора держится НЕ на этом флаге: первичный
 *     дедуп — исключение компаний других баз проекта на сборке
 *     (loadOtherBaseExclusionKeys, stages/baseCollect.ts), а окончательность —
 *     терминальная запись базы (persistRefillBase) плюс стартовый гейт стадии
 *     по статусу 'collecting'. Флаг поверх них — только защита от второго
 *     письма уже написанному лиду;
 *   - до брони и до провайдера (шаг 4c) долив спрашивает, берут ли кампании
 *     запуска контакты (S2, checkHeRefillSendTarget в autoPipeline.ts: пауза
 *     клиента, выключенный «Daily top-up», выключенная отправка аккаунта,
 *     основная кампания завершена, а продолжить её нельзя, остановлена, шлёт
 *     не из ящиков пула проекта или её статус не подтверждён — по свежему
 *     статусу). Завершённую основную, которую продолжить можно (желание
 *     клиента «отправлять», блок «ЗАВЕРШЁННАЯ ОСНОВНАЯ» в autoPipeline.ts),
 *     долив, приняв в неё контакты, стартует снова («ПОВТОРНЫЙ СТАРТ» у
 *     runHeRefillAppend; итог — stats.main_restart). Нет — долив
 *     пропущен отказом без единого запроса на загрузку: компании ночи у
 *     market='us' ждут в очереди переноса, как у ночи без бюджета
 *     (stats.sending_skip, в серию отказов не идёт). Строки неотправляющей
 *     СЕГМЕНТНОЙ кампании раскладка держит, завершённой — отдаёт основной
 *     (п. 4 «РАСКЛАДКИ»). Pause клиента, выключенный «Daily top-up» и
 *     выключенная отправка аккаунта, случившиеся уже во время загрузки,
 *     останавливают следующие чанки (проверка владения: 'client_paused',
 *     'top_up_off', 'access_turned_off', 'access_not_enabled');
 *   - blocklist владельца пресета и чанкование — внутри
 *     appendLeadsToClientCampaign (тот же путь, что у RU auto-pipeline), но с
 *     entitlementMode='managed_contract': объём режет серверный daily_leads_cap,
 *     а не self-serve тариф клиента (см. комментарий у вызова);
 *   - терминальный статус базы — 'analyzed' (не 'analyzing': анализа не
 *     будет), итог — в collect_info.refill_result и he_auto_pipeline_runs;
 *     ИСКЛЮЧЕНИЕ: долив упал, не отдав провайдеру ни одной строки — база
 *     уходит в 'failed', иначе её компании выжигаются навсегда (см.
 *     refillLeadsReachedProvider и loadOtherBaseExclusionKeys); явный отказ
 *     Instantly по частоте запросов (429) и явный отказ по ёмкости воркспейса
 *     при нулевом приёме считаются именно таким случаем — провайдер отклонил
 *     строки сам. Возврат даётся только разовому отказу: со второго подряд
 *     (REFILL_RELEASE_FAIL_STREAK_LIMIT, refillFailStreak) база снова
 *     'analyzed' — иначе ночной крон собирал бы один и тот же срез каждую
 *     ночь. Вне серии — ночь, которой бюджет не дал ни строки, и отмена
 *     клиентом: их компании возвращаются всегда (см. runHeRefillAppend), а
 *     у market='us' ночь без бюджета их не возвращает, а ПЕРЕНОСИТ (база
 *     'analyzed', компании в очереди; не записалась очередь — прежний возврат).
 *     Тем же правилом, со строкой прогона 'failed', закрываются и два отказа
 *     ДО долива — таймаут конструктора и ремонт воркера после финального
 *     фейла (closeHeRefillBaseUndelivered);
 *   - пустой harvest — ШТАТНЫЙ исход добора («новых компаний нет»): база
 *     НЕ failed, прогон 'no_new', джоба завершается успешно;
 *   - строки собрались, но НИ У ОДНОЙ нет вердикта валидации — это не пустой
 *     рынок, а недоработавшая валидация: прогон 'failed' с причиной, а не
 *     'no_new'. Иначе оплаченный срез выжигался бы под отчётом «новых
 *     компаний нет», и ночь за ночью было бы не видно, что долив уже неделю
 *     не отправляет ничего. Компании при этом возвращаются в пул по общему
 *     правилу отказа (ниже) — завтрашняя сборка проверит их заново. Так же
 *     решается сетка, где адреса нет НИ У ОДНОЙ строки, а конструктор не
 *     доработал (статус failed/cancelled или пустые данные): find_emails мог не
 *     дойти ни до одного сайта, и ноль адресов — наш сбой, а не рынок;
 *   - ошибка долива (Instantly/пресет/лимиты воркспейса) — НЕ валит джобу:
 *     собранная база сохраняется, прогон 'failed' с текстом ошибки, а
 *     завтрашний тик крона поставит новую refill-сборку. Повторный прогон
 *     ЭТОЙ базы невозможен — стадия работает только из статуса 'collecting'.
 *
 * Отмена и abort сторожа (волна 4b). Все ЧТЕНИЯ ветки идут клиентом стадий и
 * после аборта отвергаются — это правильно, работа прерванного прогона обязана
 * кончаться, и каждое такое чтение имеет безопасный исход (loadRefillConfig →
 * дефолтный кап, refillFailStreak → ноль, то есть компании возвращаются:
 * обратимый исход). Тем же клиентом идут ОБА вызова брони бюджета: взятие —
 * потому что отвергнутая бронь означает «не отправляем» (fail-closed), закрытие
 * — потому что отвергнутое закрытие оставляет объём занятым, то есть тоже
 * безопасно. Но ДВЕ ЗАПИСИ ветки терминальны и фиксируют УЖЕ ПРИНЯТЫХ
 * Instantly лидов — persistRefillBase (оба вызова) и writeRefillRun; они идут
 * клиентом БЕЗ сигнала (paidCheckpointDb из stages/baseCollect.ts), иначе abort
 * посреди долива оставлял бы лидов в живой кампании, а базу — в 'collecting', без
 * воронки, без расхода в дневном капе и без решения о судьбе компаний.
 *
 * Раз эти записи долетают и после abort'а, они обязаны знать, ЧЕЙ это abort.
 * Отмена клиентом (cancel-роут перевёл джобу в 'cancelled', наблюдатель воркера
 * оборвал сигнал без причины) — не сбой среза: база получает тот же текст
 * 'Cancelled by user', что пишет ENG-роут отмены (кабинет показывает отмену, а
 * не «шаг не успел»), её компании возвращаются в пул, если провайдер ничего не
 * получил, а строка прогона помечается stats.cancelled и в серию отказов не
 * идёт. Обрыв сторожем простоя (причина сигнала — прерывание воркера) остаётся
 * обычным отказом. См. refillUserCancelled.
 *
 * ОТМЕНА ВЫИГРЫВАЕТ У ОТПРАВКИ. Наблюдатель воркера опрашивает статус джобы
 * раз в 3 с, а appendLeadsToClientCampaign сигнала не знает вовсе: отмена,
 * записанная за секунды до долива — или во время ожидания лимитера рассыльщика,
 * которое длится минутами, — раньше всё равно уезжала в живую кампанию.
 * Поэтому прямо перед вызовом долива и ещё раз перед КАЖДЫМ HTTP-запросом чанка
 * (хук beforeProviderRequest — после допуска лимитера) прогон перечитывает,
 * вправе ли он отправлять (readHeRefillOwnershipLoss, полный набор состояний —
 * у HeRefillOwnershipLoss). Не вправе — не отправляет и уходит в тот же отказ,
 * что и отмена по сигналу: бронь закрывается нулём, база 'failed' «Cancelled by
 * user», компании в пул, перенесённые — обратно в очередь, stats.cancelled.
 * Чанки, принятые ДО отмены, остаются принятыми (база 'analyzed', как у любой
 * доставки). Остаток окна — миллисекунды между последним чтением и запросом.
 */

