/** Дефолт дневного капа лидов на проект — зеркало DEFAULT миграции 20260804_0005. */
export const HE_AUTO_DEFAULT_DAILY_LEADS_CAP = 50;

/**
 * Сколько ДОПУЩЕННЫХ адресов ждём с одной собранной компании.
 *
 * Единственная оценка в расчёте размера сборки (heRefillCompanyTarget) и
 * единственное место, где её править. Меряется по факту любого прогона долива:
 * stats.valid / stats.companies_total сборки.
 *
 * Почему не max_emails_per_company: потолок «до N адресов на компанию»
 * достижим только у компании с живым сайтом и несколькими рабочими адресами, а
 * в среднем по срезу часть компаний не даёт ни одного допущенного адреса (сайта
 * нет; на страницах адресов нет; единственный найденный — catch_all, который
 * слать нельзя). Ночной долив не запускался в production ни разу, поэтому любое
 * значение здесь — оценка, и выбрана она в сторону НЕДОбора: недобор до капа
 * виден в той же воронке (capped=0 при daily_remaining>0) и лечится этой
 * константой, а лишние компании — это уже оплаченные краул и SMTP-пробы плюс
 * выжженные из будущих сборок компании, назад их не вернуть.
 */
export const HE_REFILL_ACCEPTED_PER_COMPANY = 2;

/**
 * Минимум компаний в refill-сборке.
 *
 * НЕ зеркало MIN_ROWS_LIMIT стадии, как утверждала прежняя редакция этого
 * докблока: стадия меньший limit НЕ поднимает. totalRowsCap (кламп [100,50000])
 * считается ДО присваивания — `let limit = totalRowsCap(job)` и затем
 * `limit = await resolveHeRefillCollectCompanies(...)` (stages/baseCollect.ts,
 * блок «РАЗМЕР REFILL-СБОРКИ»), так что вернуть 25 можно и сборка пойдёт на 25.
 *
 * Пол — осознанная политика, а не техническое ограничение. Держится он на том,
 * что у refill-джобы есть ФИКСИРОВАННАЯ цена, не зависящая от лимита: план
 * сорсинга с пробой среза (LLM, buildPlan/sliceProbe в stages/baseCollect.ts)
 * считается до харвеста и при любом limit. Попросить ноль компаний значило бы
 * заплатить фикс и не получить ни строки, поэтому сборка с маленьким остатком
 * бюджета собирает минимум.
 *
 * ЧТО ДЕЛАЕТ ПЕРЕНОС (с 04.10.2026, market='us'). Компании, которым ночь не
 * отдала НИ ОДНОГО письма — их срезал дневной кап, ночи бюджет не дал ни строки
 * ('cap_exhausted'), провайдер не взял их по ёмкости, ночь упала после
 * частичной доставки, — уходят в очередь he_refill_carryover (блок «ПЕРЕНОС»
 * ниже) и идут первыми в следующие ночи — до HE_REFILL_CARRYOVER_MAX_AGE_DAYS
 * суток (компания с крючком найма — не дольше окна свежести вакансии). Чего
 * перенос НЕ делает: вторые адреса компаний, которые письмо уже получили, не
 * переносятся (компания охвачена; правило «сначала по адресу на компанию» —
 * то же, что у отреза), а настоящий отказ, не дошедший до провайдера (сбой
 * долива, 429, ёмкость при нулевом приёме), по-прежнему возвращает компании в
 * пул по серии отказов. Сборка при НУЛЕВОМ остатке без перенесённых компаний
 * тоже собирает пол: этот расчёт остатка — оценка по журналу (см.
 * resolveHeRefillCollectCompanies), а не бронь.
 *
 * Цена политики названа вслух: при дефолтном daily_leads_cap=50 пол БОЛЬШЕ
 * расчёта из капа (ceil(50/2)=25), поэтому объём сборки определяет именно он.
 * До переноса перебор «собрали 100 компаний под 50 лидов» выжигал половину
 * среза каждую ночь; теперь эта половина ждёт в очереди, а следующая ночь,
 * которой её хватает, сборку не покупает вовсе — то есть пол стал покупкой
 * впрок, а не потерей. Снижение самого пола — по-прежнему решение владельца
 * (см. решения владельца волны 1). Правильное место
 * для «бюджет потрачен — не начинать вовсе» — тик крона (autoPipeline.ts): он
 * ставит все вертикали ночи в 03:20, когда броней ещё нет, но кап и этот пол
 * ему известны, то есть сколько вертикалей кап обслужит, он посчитать может.
 * Сегодня он этого не делает (ставит до verticals_per_run вертикалей), и при
 * дефолтах кап покрывает одну: остальные собирают пол и проигрывают бронь.
 */
const HE_REFILL_MIN_COMPANIES = 100;

/**
 * Сколько КОМПАНИЙ собирать под дневной кап лидов, который считает СТРОКИ.
 *
 * Перевод единиц — через HE_REFILL_ACCEPTED_PER_COMPANY, но не больше
 * contactCap: при «до 1 адреса на компанию» компания даёт максимум один лид, и
 * компаний нужно столько же, сколько лидов.
 *
 * Потолка здесь НЕТ — его ставит вызывающий своим лимитом
 * (resolveHeRefillCollectCompanies берёт min): расчёт может только УМЕНЬШИТЬ
 * сборку против уже запланированной, но никогда не увеличить. Рост сборки —
 * это новые деньги и решение владельца, а не функции.
 */
export function heRefillCompanyTarget(input: { dailyLeadsCap: number; contactCap: number }): number {
  const perCompany = Math.max(1, Math.min(input.contactCap, HE_REFILL_ACCEPTED_PER_COMPANY));
  const cap = Number.isFinite(input.dailyLeadsCap) ? Math.max(0, input.dailyLeadsCap) : 0;
  return Math.max(HE_REFILL_MIN_COMPANIES, Math.ceil(cap / perCompany));
}

/** Размер ночи долива: сколько компаний собирать и нужна ли сборка вообще. */
export interface HeRefillCollectSizing {
  /** Лимит компаний сборки — как раньше: min(лимит постановки, расчёт из остатка). */
  limit: number;
  /**
   * Перенесённых компаний вертикали в очереди (pending, срок не вышел), КРОМЕ
   * помеченных «ждёт писем» (HE_REFILL_CARRY_HELD_REASON). Только
   * market='us'; 0 — очереди нет, она не прочиталась или рынок другой.
   */
  carriedCompanies: number;
  /**
   * Перенесённых компаний хватает на остаток дня — сборку НЕ покупаем, ночь
   * отправляет только очередь (runHeRefillAppend с пустой собственной сеткой).
   */
  carryOnly: boolean;
}

/**
 * Лимит компаний для refill-сборки: min(уже запланированный лимит, расчёт из
 * дневного капа проекта). Вызывать ДО сбора — за краул и SMTP-пробы платит
 * сборка, а не эта ветка (см. шапку файла).
 *
 * ПЕРЕНОС (только market='us'). Компании из очереди he_refill_carryover идут
 * этой ночью первыми, и каждая займёт как минимум одну строку капа (первый
 * адрес — правило отреза по компаниям). Поэтому:
 *  - очереди хватает на остаток дня (компаний ≥ остатка строк) → `carryOnly`:
 *    ни плана, ни гейта, ни конструктора, ночь отправляет только очередь.
 *    Остаток 0 при непустой очереди — тоже `carryOnly`: сборку бюджет всё
 *    равно не обслужит, а очередь без сборки ничего не стоит;
 *  - не хватает → сборка считается от остатка МИНУС компании очереди (пол
 *    HE_REFILL_MIN_COMPANIES остаётся, лишнее уйдёт в очередь, а не в потерю).
 * Очередь не прочиталась — ноль перенесённых, то есть ровно прежний расчёт.
 * Компании с пометкой «ждёт писем» (HE_REFILL_CARRY_HELD_REASON) здесь НЕ
 * считаются: письмо кампании прочиталось бы у них неверно на прошлой ночи, и
 * ночь, рассчитавшая на них остаток дня, не отправила бы ничего. Их ночь всё
 * равно берёт и перепроверяет (захват — вся очередь), а сборка покупается так,
 * будто их нет, — ровно как до того, как они стали попадать в очередь.
 *
 * Best-effort как и сам loadRefillConfig: кап не прочитался или конфига нет —
 * берётся дефолт движка, тот же, по которому долив ниже будет резать объём,
 * поэтому расчёт и кап остаются в одних единицах даже на транзиентной ошибке
 * чтения. Ошибка в меньшую сторону: недобор — не потраченные деньги.
 *
 * Считаем от ОСТАТКА бюджета на сегодня, а не от всего капа: кап — на ПРОЕКТ в
 * сутки, а крон ставит за тик до verticals_per_run вертикалей одного проекта.
 * Пока каждая вертикаль мерила себя полным капом, ночь из трёх вертикалей
 * собирала объём под три капа, а долить могла один: вторая и третья платили за
 * краул и SMTP-пробы строк, которые кап того же вечера выбрасывал, и оставляли
 * свои компании выжженными. Пол HE_REFILL_MIN_COMPANIES остаётся: даже ночь с
 * остатком 0 собирает минимум стадии, а не ноль, и такая сборка — оплаченная
 * впустую (её компании вернутся в пул и будут куплены снова, см. докблок пола).
 *
 * ЭТО ОЦЕНКА, А НЕ РЕШЕНИЕ. Сколько строк реально уедет, решает БРОНЬ дневного
 * бюджета (reserveRefillDailyBudget, шаг 5 долива): она считает занятое под
 * сериализацией по проекту и UTC-дню, то есть видит и открытые брони
 * параллельных прогонов, которых в журнале ещё нет. Здесь же берётся то, что
 * уже ДОЛИТО (refillAppendedToday): это уменьшает сборку под занятый бюджет, но
 * не отменяет её — пол покупает минимум и при нулевом остатке, а у вертикалей,
 * поставленных одним тиком в 03:20, долитого ещё нет вовсе, и каждая считает
 * себе полный кап. Разойтись в опасную сторону оценка и бронь не могут: оценка
 * может только ЗАВЫСИТЬ остаток (открытая чужая бронь ей не видна), а
 * завышенная оценка — это лишние собранные компании, тогда как отправку всё
 * равно режет бронь.
 */
export async function resolveHeRefillCollectCompanies(
  ctx: HeStageContext,
  input: {
    projectId: string;
    verticalId: string;
    /** База этой ночи: её собственный прошлый захват очереди тоже считается. */
    baseId: string;
    payloadLimit: number;
    contactCap: number;
    market: HeMarket;
  },
): Promise<HeRefillCollectSizing> {
  const config = await loadRefillConfig(ctx, input.projectId);
  const dailyLeadsCap = config?.dailyLeadsCap ?? HE_AUTO_DEFAULT_DAILY_LEADS_CAP;
  // Остаток читаем best-effort: это ПРЕДПОЛЁТ, он обязан ошибаться в сторону
  // прежнего поведения. Непрочитанная история → spent=0 → размер как до этой
  // правки (полный кап), а не «бюджет исчерпан» — иначе транзиентная ошибка
  // чтения журнала молча уводила бы каждую ночь на пол.
  //
  // Считаем ВСЕГДА, в том числе без строки конфига: кап при отсутствующем
  // конфиге берётся дефолтный, и расход под него обязан считаться тем же
  // дефолтом — иначе «конфига нет» читалось бы как «сегодня ничего не
  // отправляли», и сборка шла бы по полному капу поверх уже отправленного.
  let appendedToday = 0;
  try {
    appendedToday = await refillAppendedToday(ctx, input.projectId);
  } catch (e) {
    stageLog(
      ctx,
      `[base_collect] refill: остаток дневного капа не прочитан ` +
        `(${e instanceof Error ? e.message : String(e)}) — размер сборки по полному капу`,
    );
  }
  const remainingLeadsCap = Math.max(0, dailyLeadsCap - appendedToday);
  const carriedCompanies =
    input.market === 'us'
      ? await countHeRefillCarryover(ctx, input.verticalId, input.baseId, { sendableOnly: true })
      : 0;
  return {
    limit: Math.min(
      input.payloadLimit,
      heRefillCompanyTarget({
        dailyLeadsCap: Math.max(0, remainingLeadsCap - carriedCompanies),
        contactCap: input.contactCap,
      }),
    ),
    carriedCompanies,
    carryOnly: carriedCompanies > 0 && carriedCompanies >= remainingLeadsCap,
  };
}

/**
 * Сколько подряд упавших доливов вертикали ещё возвращают её компании в пул.
 *
 * Возврат компаний (база 'failed' → HARVEST снова видит их как новые) нужен
 * ровно для разового отказа: собрали, письмо не ушло не по вине компаний,
 * незачем выжигать срез. Но крон ставит refill вертикали КАЖДУЮ НОЧЬ, и при
 * устойчивой причине (пропавший пресет, снятая кампания, исчерпанный лимит
 * воркспейса, сменившийся Instantly-аккаунт) возврат
 * превращается в цикл: те же компании собираются заново, падают на том же
 * месте и снова возвращаются — каждую ночь за деньги сбора. Поэтому возврат
 * даётся только первому отказу; со второго подряд срез остаётся исключённым,
 * и цикл по одному и тому же набору прекращается. Причина решения — в
 * refill_result (companies_released/fail_streak).
 *
 * Серия решает ТОЛЬКО за отказ, про который неизвестно, повторится ли он. Вне
 * её — два исхода, у которых ответ известен (runHeRefillAppend):
 *  - бюджет проекта не дал этой базе ни строки ('cap_exhausted'): провайдер от
 *    неё ничего не получил, причина — чужой расход капа, а не срез. Компании
 *    не выжигаются НИКОГДА: у market='us' они уходят в очередь переноса (база
 *    'analyzed'), иначе — и когда очередь не записалась — возвращаются в пул.
 *    Такая ночь не входит в серию ни как отказ, ни как успех (refillFailStreak
 *    её пропускает) — иначе она выжигала бы следующий настоящий разовый отказ
 *    вертикали;
 *  - отмена клиентом: та же логика, причина — решение человека, а не срез.
 */
const REFILL_RELEASE_FAIL_STREAK_LIMIT = 1;

/**
 * Сколько строк журнала прогонов читает refillFailStreak за раз.
 *
 * Окно шире LIMIT + 1, потому что часть строк в серию не идёт вовсе (ночи без
 * бюджета, отмены — см. refillFailStreak). Двадцать — это почти три недели ночей
 * подряд, где ни одна строка не решает серию; если окно кончилось раньше, чем
 * набралась серия, считается набранное — то есть меньше, и компании
 * возвращаются: из двух ошибок эта обратимая.
 */
const REFILL_FAIL_STREAK_WINDOW = 20;

/**
 * Тексты, которыми cancel-роуты пишут отмену в he_bases.error: ENG-кабинет
 * (api/client/eng/projects/[id]/cancel) и staff-инструмент
 * (api/tools/hypothesis-engine/projects/[id]/cancel). Сверка полным
 * совпадением — как у проекции кабинета (clientEngProjection.ts,
 * STAGE_CANCELLED_MARKERS): слово «cancel» внутри длинного текста — это сбой,
 * а не отмена.
 */
const REFILL_CANCELLED_ERROR = 'Cancelled by user';
const REFILL_CANCEL_MARKERS = new Set(['cancelled by user', 'отменено пользователем']);

/**
 * Начало текста отказа долива, пропущенного шагом 4c (кампании запуска не
 * берут контакты); за ним — машинная причина и подробность. Читается только
 * людьми (refill_result.error, строка прогона, лог); машинный признак —
 * stats.sending_skip.
 */
const REFILL_SENDING_SKIP_NOTE = 'долив пропущен до отправки: кампании запуска не берут контакты';

/**
 * Прогон оборван ОТМЕНОЙ клиентом, а не сторожем простоя.
 *
 * Сигнал стадии обрывают ровно двое (worker/hypothesisEngine.ts, handleJob):
 * наблюдатель отмены — `abort.abort()` БЕЗ причины, когда cancel-роут перевёл
 * джобу в 'cancelled', — и сторож простоя — с причиной HeJobInterruptionError,
 * у которой есть дискриминант `heJobInterruption: true` (класс живёт в воркере,
 * поэтому читаем поле, а не instanceof). Нет обрыва — не отмена; обрыв с
 * дискриминантом — прерывание; иначе — отмена.
 */
function refillUserCancelled(ctx: HeStageContext): boolean {
  const signal = ctx.signal;
  if (!signal?.aborted) return false;
  const reason = signal.reason as { heJobInterruption?: unknown } | null | undefined;
  return reason?.heJobInterruption !== true;
}

/**
 * Почему прогон долива больше НЕ вправе отправлять (проверка владения перед
 * провайдером, см. «ОТМЕНА ВЫИГРЫВАЕТ У ОТПРАВКИ» в шапке). Весь набор — и то,
 * чего в нём нет, тоже решение:
 *  - 'job_cancelled' — he_jobs.status = 'cancelled': отмена клиентом
 *    (api/client/eng/projects/[id]/cancel) или сотрудником
 *    (api/tools/hypothesis-engine/projects/[id]/cancel), которую наблюдатель
 *    воркера ещё не успел превратить в обрыв сигнала;
 *  - 'job_missing' — строки джобы нет (проект удалён каскадом);
 *  - 'base_cancelled' — база 'failed' с текстом отмены одного из двух
 *    cancel-роутов (REFILL_CANCEL_MARKERS);
 *  - 'base_missing' — строки базы нет;
 *  - 'refill_cancelled' — ночной добор проекта на паузе ОТМЕНЫ клиентом
 *    (isHeClientCancelPauseReason). Роут кабинета пишет паузу раньше, чем
 *    отменяет джобы, поэтому эта ветка ловит отмену и в миллисекунды между
 *    его записями, и когда запись отмены джоб у него не легла вовсе;
 *  - 'client_paused' — клиент нажал Pause запуска, в который доливает ночь
 *    (he_eng_launch_sending = 'paused'; роут паузы пишет его ДО паузы кампаний
 *    у рассыльщика). Читается, только когда вызывающий передал шаблон (шаг 4c
 *    его пропустил — market='us'). Это НЕ отмена: прогон перестаёт
 *    отправлять, а итог ночи — пропуск шага 4c, если ничего не дошло, или
 *    обычная доставка того, что ушло до паузы (runHeRefillAppend, «ПАУЗА
 *    КЛИЕНТА ВО ВРЕМЯ ЗАГРУЗКИ»): неотправленные компании ждут в очереди
 *    переноса. Отмена из списка выше выигрывает у паузы;
 *  - 'top_up_off' — клиент выключил «Daily top-up» проекта
 *    (he_auto_pipeline_configs.enabled ≠ true или строки нет);
 *  - 'access_turned_off' / 'access_not_enabled' — отправку аккаунта владельца
 *    проекта выключил сотрудник / она не включена (engSendingAccess);
 *  - 'unavailable' — не прочиталось что-то из проверок us: владелец проекта,
 *    выключатель аккаунта, желание клиента, отдельное чтение «Daily top-up».
 *    Fail-closed, но не сбой ночи: тот же пропуск 'unavailable', что у шага
 *    4c, — иначе блип чтения шёл бы в серию отказов и со второй ночи подряд
 *    выжигал бы оплаченные компании.
 *    Эти — как 'client_paused' (тот же шаблон-условие: только us, после
 *    шага 4c): не отмена, а остановка отправки — следующие чанки не уходят,
 *    неотправленные компании ждут в очереди переноса, бронь их не списывает,
 *    пропуск — та же причина шага 4c (stats.sending_skip).
 * НЕ потеря владения:
 *  - джоба 'running' — наша;
 *  - джоба 'pending' / 'done' / 'failed' — строку переписал двойник при
 *    перекрытии деплоя (resetStuckJobs нового процесса, затем его финал).
 *    Отправителя между двумя живыми прогонами одной базы уже выбрала бронь
 *    дневного бюджета: сюда доходит только 'granted'/'reclaimed', двойник
 *    получит 'already_reserved' и ничего не отправит. Остановиться здесь
 *    значило бы, что не отправит НИКТО, а оплаченная сборка выгорит;
 *  - база 'analyzed' или 'failed' без текста отмены — терминал того же
 *    двойника ('already_reserved' пишет базе 'analyzed' без отправки), довод
 *    тот же; база 'collecting' — наша; 'uploaded'/'analyzing' у refill-базы
 *    не пишет никто;
 *  - пауза по ЁМКОСТИ — её проверяет сам appendLeadsToClientCampaign своим
 *    предполётом ёмкости (pauseOnWorkspaceCapacity) перед отправкой: места нет
 *    — не отправит ничего, место освободилось — отправит строки уже оплаченной
 *    сборки. Остановка по ней могла бы только отнять письма.
 */
type HeRefillOwnershipLoss =
  | 'job_cancelled'
  | 'job_missing'
  | 'base_cancelled'
  | 'base_missing'
  | 'refill_cancelled'
  | 'client_paused'
  | 'top_up_off'
  | 'access_turned_off'
  | 'access_not_enabled'
  | 'unavailable';

/**
 * Остановки отправки по решению клиента или аккаунта — не отмена: прогон
 * перестаёт слать, итог — пропуск шага 4c этой причиной (или доставка того,
 * что ушло раньше); неотправленные компании — в очередь переноса.
 */
type HeRefillSendStop = Extract<
  HeRefillOwnershipLoss,
  'client_paused' | 'top_up_off' | 'access_turned_off' | 'access_not_enabled' | 'unavailable'
>;

const REFILL_SEND_STOP_TEXT: Record<HeRefillSendStop, string> = {
  client_paused: 'клиент нажал Pause',
  top_up_off: 'клиент выключил ежедневный добор',
  access_turned_off: 'сотрудник выключил отправку аккаунта',
  access_not_enabled: 'отправка аккаунта не включена',
  unavailable: 'проверка «вправе ли отправлять» не прочиталась (владелец, выключатель или желание клиента)',
};

function isHeRefillSendStop(loss: HeRefillOwnershipLoss): loss is HeRefillSendStop {
  return (
    loss === 'client_paused' ||
    loss === 'top_up_off' ||
    loss === 'access_turned_off' ||
    loss === 'access_not_enabled' ||
    loss === 'unavailable'
  );
}

/**
 * Прочитать, вправе ли прогон отправлять (HeRefillOwnershipLoss); null —
 * вправе. Три чтения по ключу разом (четыре — с шаблоном: желание клиента),
 * клиентом СТАДИЙ: после обрыва сигнала они отвергаются, и долив уходит в
 * отказ, который refillUserCancelled узнаёт как отмену.
 *
 * FAIL-CLOSED: несостоявшееся чтение БРОСАЕТ, и долив уходит в общий отказ, не
 * отправив ни строки, — та же сторона, что у брони дневного бюджета, которая
 * читается тем же клиентом шагом раньше (бронь закрывается нулём, компании
 * решает серия отказов). Отправка, которую отмена должна была остановить, не
 * отзывается; потерянная ночь — отзывается следующей. Единственное
 * исключение — колонок паузы нет (миграция 20260930_0005, PostgREST 42703): без
 * них паузы отмены не бывает по определению (желание клиента читается и тогда).
 * Проверки us (владелец, выключатель аккаунта, желание клиента, отдельное
 * чтение «Daily top-up») не бросают, а отвечают 'unavailable': отправка так же
 * остановлена, но ночь — пропуск с переносом компаний, а не сбой в серию.
 */
async function readHeRefillOwnershipLoss(
  ctx: HeStageContext,
  ids: { jobId: string; baseId: string; projectId: string; templateId: string | null },
): Promise<HeRefillOwnershipLoss | null> {
  const [jobRes, baseRes, configRes, clientStates, ownerRes] = await Promise.all([
    ctx.supabase.from('he_jobs').select('status').eq('id', ids.jobId).maybeSingle(),
    ctx.supabase.from('he_bases').select('status, error').eq('id', ids.baseId).maybeSingle(),
    ctx.supabase
      .from('he_auto_pipeline_configs')
      // us (шаблон передан) — и переключатель «Daily top-up» тем же чтением.
      .select(ids.templateId ? 'refill_paused_at, refill_pause_reason, enabled' : 'refill_paused_at, refill_pause_reason')
      .eq('project_id', ids.projectId)
      .maybeSingle(),
    // Не бросает: таблица не читается — null (ниже — тот же fail-closed).
    ids.templateId ? readHeEngClientStates(ctx.supabase, [ids.templateId]) : Promise.resolve(null),
    // us: владелец проекта — для выключателя отправки аккаунта.
    ids.templateId
      ? ctx.supabase.from('he_projects').select('created_by').eq('id', ids.projectId).maybeSingle()
      : Promise.resolve(null),
  ]);
  if (jobRes.error) throw new Error(`he_jobs ownership read: ${jobRes.error.message}`);
  const jobRow = jobRes.data as { status?: unknown } | null;
  if (!jobRow) return 'job_missing';
  if (jobRow.status === 'cancelled') return 'job_cancelled';
  if (baseRes.error) throw new Error(`he_bases ownership read: ${baseRes.error.message}`);
  const baseRow = baseRes.data as { status?: unknown; error?: unknown } | null;
  if (!baseRow) return 'base_missing';
  const baseError = typeof baseRow.error === 'string' ? baseRow.error.trim().toLowerCase() : '';
  if (baseRow.status === 'failed' && REFILL_CANCEL_MARKERS.has(baseError)) return 'base_cancelled';
  if (configRes.error && (configRes.error as { code?: string }).code !== '42703') {
    throw new Error(`he_auto_pipeline_configs ownership read: ${configRes.error.message}`);
  }
  const config = (configRes.error ? null : configRes.data) as
    | { refill_paused_at?: unknown; refill_pause_reason?: unknown }
    | null;
  const paused = typeof config?.refill_paused_at === 'string' && config.refill_paused_at !== '';
  const reason = typeof config?.refill_pause_reason === 'string' ? config.refill_pause_reason : null;
  if (paused && isHeClientCancelPauseReason(reason)) return 'refill_cancelled';
  if (!ids.templateId) return null;
  // us — тот же порядок, что у гейта ночи (createHeRefillSendGate): «Daily
  // top-up», выключатель аккаунта, пауза клиента. Всё fail-closed; не
  // прочиталось — 'unavailable' (пропуск с переносом, а не сбой ночи).
  let enabled: unknown;
  if (configRes.error) {
    // 42703 (колонок паузы нет) пропущен выше — переключатель читается отдельно.
    const { data, error } = await ctx.supabase
      .from('he_auto_pipeline_configs')
      .select('enabled')
      .eq('project_id', ids.projectId)
      .maybeSingle();
    if (error) return 'unavailable';
    enabled = (data as { enabled?: unknown } | null)?.enabled;
  } else {
    enabled = (configRes.data as { enabled?: unknown } | null)?.enabled;
  }
  if (enabled !== true) return 'top_up_off';
  if (!ownerRes || ownerRes.error) return 'unavailable';
  const owner = (ownerRes.data as { created_by?: unknown } | null)?.created_by;
  if (typeof owner !== 'string' || !owner) return 'unavailable';
  const access = await readHeEngSendingAccess(ctx.supabase, owner);
  if (access.state === 'revoked') return 'access_turned_off';
  if (access.state === 'not_enabled') return 'access_not_enabled';
  if (access.state === 'unavailable' || access.state === 'error') return 'unavailable';
  if (clientStates === null) return 'unavailable';
  return clientStates.get(ids.templateId)?.state === 'paused' ? 'client_paused' : null;
}

/** Статистика воронки долива (he_auto_pipeline_runs.stats + refill_result). */
/**
 * ЗАМЕР того, что прячет флаг `skipIfInCampaign` (шаг 4b долива).
 *
 * Долив грузит лидов с `skipIfInCampaign: true`, а у Instantly этот флаг, по
 * нашему собственному свидетельству (докблок
 * `AppendLeadsToClientCampaignInput.skipIfInCampaign`, `clientLaunch/appendLeads.ts`),
 * работает НА ВЕСЬ ВОРКСПЕЙС: адрес отсеивается, если он есть в ЛЮБОЙ
 * кампании аккаунта, в том числе в кампании ДРУГОГО клиента студии. Такой
 * контакт мы уже оплатили сбором, но не увидим никогда: строка базы уходит в
 * 'analyzed', компания выжигается из будущих сборок проекта, письма нет.
 *
 * `skipped_instantly` эту потерю не показывает: в нём и законный отсев (адрес
 * уже в НАШЕЙ кампании — второе письмо не нужно), и брак адресов, и чужая
 * кампания, одним числом. Разделить может только отдельное чтение — оно и
 * лежит здесь.
 *
 * Поле — ИЗМЕРЕНИЕ, а не механизм: по нему ничего не отсеивается и не
 * решается, поэтому любой его исход, включая «не знаю», не стоит ни одного
 * контакта. Читателей у девяти его ключей ровно два, и оба существуют: строка
 * лога прогона печатает КАЖДЫЙ из них в ту же ночь (шаг 4b ниже), а владелец
 * читает их пачкой по he_auto_pipeline_runs.stats перед решением «переводить
 * ли флаг в false» (запрос — в отчёте волны 6b). В кабинет ENG поле НЕ уезжает
 * и уехать не может: оно говорит о кампаниях других клиентов того же аккаунта.
 *
 * Все числа — по ВЫБОРКЕ из пачки (`probed` из `of`), а не по всей пачке:
 * каждый запрос замера берёт токен общего для воркспейса лимитера (~10–15 RPM),
 * то есть отнимает минуту у RU-контуров, где идёт ЖИВАЯ оплаченная рассылка.
 * Поэтому по умолчанию замера нет вовсе: HE_REFILL_SKIP_PROBE_REQUESTS пуст =
 * ноль запросов и ни одного ключа в воронке, включает его человек на те ночи,
 * когда решение по флагу действительно принимается.
 */
export interface HeRefillSkipProbe {
  /** Сколько РАЗНЫХ адресов пачки реально спросили у провайдера. */
  probed: number;
  /** Размер пачки, из которой бралась выборка (адреса после blocklist'а). */
  of: number;
  /**
   * Адрес уже лежит в НАШЕЙ кампании: флаг прячет его законно, денег это не
   * стоит, и после перевода флага в false этих лидов придётся отсеивать самим.
   */
  already_in_our_campaign: number;
  /** Адрес лежит в ЧУЖОЙ кампании воркспейса — ВОТ ЧТО флаг отнимает. */
  in_other_campaign: number;
  /**
   * Адрес есть в воркспейсе, но ни в одной кампании (список/импорт). Отдельно
   * от чужой кампании: за списки отвечает другой флаг (`skip_if_in_list`), и
   * складывать их значило бы завысить цену именно `skip_if_in_campaign`.
   */
  in_workspace_no_campaign: number;
  /** Адреса в воркспейсе нет — флаг его не тронет. */
  absent: number;
  /**
   * Вывода нет: страница не дочитана, ответ не разобран или отказал транспорт.
   * Отдельным числом, потому что «не знаю» не равно «в воркспейсе нет»; если
   * undecided почти равен probed — провайдер не уважает фильтр `contacts`, и
   * замер этим способом невозможен (см. докблок leadPresenceProbe).
   */
  undecided: number;
  /** Сколько запросов к провайдеру стоил замер этой ночью. */
  requests: number;
  /**
   * Замер НЕ спросил всю выборку, которую собирался: вышел срок или отказал
   * транспорт (429, таймаут, сорванный ответ). Про бюджет запросов речи нет —
   * выборка режется до бюджета ещё до вызова, поэтому упереться в него замер
   * не может.
   *
   * Отдельным признаком от `probed < of`: и то и другое даёт «спросили меньше
   * пачки», но выборка — это решение, а обрыв — происшествие, и числа
   * прерванного замера читать как выборку нельзя.
   */
  stopped_early: boolean;
}

export interface HeRefillStats {
  /** Строк собрано сборкой (после импорта конструктора). */
  collected: number;
  /** Строк с непустым email. */
  with_email: number;
  /** Строк с email и допущенным вердиктом валидации — кандидаты в лиды. */
  valid: number;
  /**
   * Строк с email, снятых из-за ОТСУТСТВИЯ вердикта. Отдельным счётчиком от
   * отклонённых (with_email - valid - unverified): «адрес не проверен» лечится
   * пересборкой базы, «адрес отклонён» — ничем, и в отчёте это разные строки.
   */
  unverified: number;
  /**
   * Адресов (строк с допущенным вердиктом, своих и перенесённых), которые долив
   * НЕ отдал провайдеру: письмо основной кампании подставило бы в них пустоту
   * или замену не на месте (шаг 3a, heRefillUnfilledRows — тот же гейт, что у
   * запуска). В бронь дня и в попытки не входят. Компания, у которой других
   * лидов нет, ложится в очередь переноса с пометкой «ждёт писем» (своя — от
   * этой ночи, `carryover.queued_held`; перенесённая — обратно,
   * `carryover.returned_held`), и каждая следующая ночь вертикали проверяет
   * её строки тем же отбором по письмам ТЕКУЩЕЙ кампании: прошли — уходят,
   * нет — ждут дальше до срока очереди. Только market='us'; нет ключа — таких
   * не было.
   * Читатели — строки лога прогона (отдельная строка шага 3a и итоговая,
   * успешная и отказная) и лента Command Center
   * (engDashboard.buildEngDashboardEvents: «N skipped…» у ночи 'appended').
   */
  held_unfilled?: number;
  /** Принято Instantly. */
  appended: number;
  /** Отрезано blocklist'ом владельца пресета. */
  skipped_blocklist: number;
  /** Отсеяно Instantly при загрузке (дубли кампании и пр.). */
  skipped_instantly: number;
  /**
   * Сегментные кампании запуска, которые этой ночью ЯВНО отказали, не приняв
   * ни строки (обычно кампания удалена или в архиве у рассыльщика) — запись на
   * кампанию, их число — длина списка (блок «РАСКЛАДКА», п. 7). `leads` —
   * лидов её группы; `pinned` — из них закреплённых журналом доставки за этой
   * же кампанией (она могла писать им в прошлые ночи, п. 7г): в основную они
   * не идут и считаются возможно доставленными — в перенос не идут, как до
   * этой правки (бронь — по общему правилу закрытия: у отказа ночи как
   * попытка, у удачной ночи — только принятое). `fate` — что стало с
   * ОСТАЛЬНЫМИ (leads − pinned):
   *  - 'main' — переотправлены в основную кампанию в этом же прогоне, и та
   *    ответила (принятые — в `appended`, отсеянные — в `skipped_instantly`);
   *  - 'not_sent' — не отправлены: основная кампания не подтверждена, сама
   *    отказала явно или прогон потерял право отправлять. С брони не списаны;
   *    компании — в перенос у ночи с доставкой, по правилу отказа (серия) у
   *    ночи без неё, а при отмене — по правилу отмены: у ночи с доставкой
   *    остаются исключёнными (база 'analyzed', переноса у отмены нет), без
   *    доставки — возвращаются в пул;
   *  - 'unknown' — переотправка оборвалась без явного ответа: строки считаются
   *    возможно доставленными (как любая отправка в основную кампанию);
   *  - 'none' — переотправлять нечего: все лиды группы закреплены (`pinned`).
   * Только market='us'; нет ключа — таких отказов не было. Читатели — строки
   * лога прогона и алерт команде (alertRefillSegmentRefused).
   */
  segment_refusals?: Array<{
    campaign_id: string;
    http_status: number;
    leads: number;
    pinned: number;
    fate: 'main' | 'not_sent' | 'unknown' | 'none';
  }>;
  /**
   * Замер флага skipIfInCampaign по выборке из пачки — см. HeRefillSkipProbe.
   * Ключа нет: замер выключен (так по УМОЛЧАНИЮ — HE_REFILL_SKIP_PROBE_REQUESTS
   * не задан или 0), отправлять было нечего или кампания неизвестна.
   */
  skip_probe?: HeRefillSkipProbe;
  /** Не влезло в дневной кап daily_leads_cap (уйдёт в отчёт, не в кампанию). */
  capped: number;
  /**
   * Строк, которые провайдер НЕ взял из-за нехватки места в воркспейсе, — не
   * брак адресов и не наш бюджет. Отдельно от skipped_instantly (там
   * ОКОНЧАТЕЛЬНЫЕ отказы: дубли кампании, невалидный адрес) и от capped (там
   * дневной бюджет проекта): «не взяли, потому что некуда» лечится местом у
   * провайдера, а не пересборкой и не тарифом. Считается как остаток пачки,
   * отданной провайдеру, за вычетом принятого и окончательно отсеянного:
   * result.deferredIndexes покрывает только явный отказ на чанке, а хвост,
   * который пауза не начала отправлять, в него не попадает.
   */
  deferred?: number;
  /** Причина deferred, когда он есть. Одно значение, но пишется явно. */
  deferred_reason?: 'instantly_capacity';
  /**
   * Машинная причина ОТКАЗА прогона (status='failed') — та же, что в
   * refill_result.error_kind. Дублируется сюда осознанно: журнал прогонов
   * (he_auto_pipeline_runs) и карточка базы (he_bases.collect_info) — разные
   * таблицы с разными читателями, а writeRefillRun переносит в прогон только
   * stats/error. Без этого поля воронка ночей не отличает «у рассыльщика нет
   * места» от «данные плохие», то есть не отвечает, сколько ночей потеряно
   * из-за ёмкости.
   */
  error_kind?: 'instantly_capacity';
  /**
   * Почему строки не ушли, когда capped > 0. Пишется явно: «отрезано» без
   * причины читается как брак адресов, а причин ровно две и лечатся они
   * по-разному — 'daily_leads_cap' это бюджет проекта на сутки (поднимается
   * конфигом), 'repeat_run' это повторный прогон ТОЙ ЖЕ базы в те же сутки, у
   * которой бюджет ещё держит бронь её первого прогона (моложе окна
   * перехвата), и второй отправки быть не должно.
   *
   * Отрез на ВСЮ пачку (capped = valid после blocklist'а) живёт только в
   * строке ОТКАЗА: ночь, не отправившая ни одной строки, завершается
   * 'failed'; при 'daily_leads_cap' её компании возвращаются в пул, при
   * 'repeat_run' — нет (бронь держит прошлый прогон той же базы, который мог
   * уже отправить). В строке 'appended' это поле означает частичный отрез —
   * остальное уехало.
   *
   * Читатель — строка лога прогона (обе: успешная и отказная) рядом с числом
   * отреза.
   */
  capped_reason?: 'daily_leads_cap' | 'repeat_run';
  /**
   * Сколько КОМПАНИЙ при частичном отрезе не получили ни одного письма. Кап
   * считает строки-адреса, а платит сборка за компании; отрез идёт по
   * компаниям (сначала сильнейший адрес КАЖДОЙ компании, потом вторые адреса —
   * selectLeadsWithinLaunchCap, то же правило, что у ручного запуска), и это
   * число — компании, оплаченные сборкой, но не вошедшие в кап. Они остаются
   * исключёнными из будущих сборок (база 'analyzed'), но у market='us' больше
   * не теряются: их строки уходят в очередь переноса (см. `carryover.queued`).
   * Сюда входят и перенесённые с прошлых ночей компании, которым снова не
   * хватило капа (`carryover.returned`). Нет ключа — отреза не было или он был
   * на всю пачку. Читатель — строка лога прогона.
   */
  capped_companies?: number;
  /**
   * Очередь переноса этой ночи (только market='us'; нет ключа — очереди не
   * было и класть в неё нечего). Все числа — КОМПАНИИ:
   *  - `offered` — взято из очереди и предложено первыми;
   *  - `sent` — из них хотя бы один адрес отдан провайдеру;
   *  - `returned` — не дошли до провайдера (кап, ёмкость, отказ ночи, письма)
   *    и вернулись в очередь со своим прежним сроком;
   *  - `returned_held` — из `returned` те, что вернулись с пометкой «ждёт
   *    писем»: письмо текущей кампании прочиталось бы неверно у каждого их
   *    адреса, не снятого чёрным списком. Нет ключа — таких не было;
   *  - `dropped` — сняты навсегда: все адреса в чёрном списке, база-источник
   *    ушла в 'failed', либо судьба неизвестна (бронь держал прошлый прогон);
   *  - `released` — срок вышел, компания вернулась в пул сборки;
   *  - `queued` — собственные компании ЭТОЙ ночи без единого письма, отданные
   *    в очередь: у успешной ночи, у ночи без бюджета ('cap_exhausted') и у
   *    отказа после частичной доставки. Число — то, что ушло в запись; если
   *    запись не легла, строка лога прогона говорит об этом;
   *  - `queued_held` — из `queued` те, что легли с пометкой «ждёт писем» (все
   *    их адреса сняты отбором писем, шаг 3a). Нет ключа — таких не было;
   *  - `released_hiring` — собственные компании ночи без письма, которые НЕ
   *    поставлены в очередь, а сразу возвращены в пул: их крючок найма не
   *    доживёт до отправки свежим или его возраст неизвестен
   *    (heRefillCarryExpiry). Нет ключа — таких не было.
   * Читатель `*_held` — строка лога переноса (успешная и отказная).
   * В кабинет поле не уезжает: «Valid today» и «Collected today» считают
   * только собственные строки ночи (`valid`, `collected`), чтобы адрес,
   * проверенный вчера, не засчитывался сегодня второй раз; `appended` — все
   * принятые лиды, в том числе перенесённые.
   */
  carryover?: {
    offered: number;
    sent: number;
    returned: number;
    returned_held?: number;
    dropped: number;
    released: number;
    queued: number;
    queued_held?: number;
    released_hiring?: number;
  };
  /**
   * Ночь НЕ покупала сборку: перенесённых компаний хватало на остаток дня
   * (resolveHeRefillCollectCompanies → carryOnly). Собственных строк у такой
   * ночи нет, `collected`/`valid` — нули.
   */
  carry_only?: true;
  /**
   * Прогон оборван ОТМЕНОЙ (refillUserCancelled) либо остановлен проверкой
   * владения перед провайдером (HeRefillOwnershipLoss — отмена, замеченная
   * раньше наблюдателя воркера). Пишется только у отказа. Читатели —
   * refillFailStreak (отмена — решение человека, а не свойство среза, и в
   * серию отказов вертикали она не идёт), readCarryoverByVertical тика
   * (такая ночь не решает судьбу очереди) и лента кабинета
   * (engDashboard: «refill cancelled»).
   */
  cancelled?: true;
  /**
   * Долив пропущен до того, как провайдер получил хоть строку: кампании
   * запуска не берут контакты (шаг 4c, checkHeRefillSendTarget — пауза
   * клиента, выключенный «Daily top-up», выключенная отправка аккаунта,
   * кампания завершена, остановлена, шлёт не из ящиков пула проекта или её
   * статус не подтверждён; до брони) либо клиент нажал Pause уже во время
   * загрузки, до первого чанка ('client_paused', проверка владения). Пишется
   * только у отказа, и только когда отказ — это пропуск, а не отмена (у
   * отмены — `cancelled`).
   * Читатели: refillFailStreak (пропуск — не свойство среза, в серию не идёт),
   * readCarryoverByVertical тика (такая ночь не решает судьбу очереди) и лента
   * кабинета (engDashboard: «daily top-up skipped — …»).
   */
  sending_skip?: HeRefillSendSkipReason;
  /**
   * Основная кампания была завершена (3), и ночь её продолжала (шаг 4c:
   * `mainCompleted`): исход повторного старта после долива («ПОВТОРНЫЙ
   * СТАРТ» у runHeRefillAppend, исходы — HeRefillMainRestartOutcome в
   * autoPipeline.ts). Нет ключа — основная отправляла, долив до загрузки не
   * дошёл или это не market='us'. Пишется только в строку прогона: базу
   * долив пишет раньше старта (терминальная запись не ждёт рассыльщика).
   * Читатели: гейт ночи и кабинет ('failed' держит следующие ночи вертикали —
   * readHeRefillRestartHold), лента кабинета (engDashboard.ts) и строка лога
   * долива.
   */
  main_restart?: HeRefillMainRestart;
  /**
   * Исход брони дневного бюджета (he_reserve_refill_daily_budget). Пишется,
   * когда бронь запрашивалась; нет ключа — отправлять было нечего и бронь не
   * бралась. Различает три разные причины нулевой отправки и отделяет
   * перехваченную бронь от свежей, см. HeRefillBudgetOutcome. Читается строкой
   * лога прогона (успешной и отказной) рядом с кап-отрезом и refillFailStreak:
   * ночь с 'cap_exhausted'/'already_reserved' в серию отказов не идёт.
   */
  budget_outcome?: HeRefillBudgetOutcome;
  /**
   * Сколько строк бюджет РАЗРЕШИЛ отправить (выданная бронь). Отличается от
   * appended на то, что отсеял сам провайдер; отличается от daily_remaining на
   * объём, которого у нас не было. Нет ключа — бронь не бралась. Читается там
   * же, где budget_outcome: обе цифры печатает строка лога прогона.
   */
  reserved?: number;
  /** Дневной кап лидов проекта (СТРОК), действовавший в прогоне. */
  daily_cap: number;
  /**
   * Сколько от капа осталось к моменту долива (замороженный кап дня минус
   * занятое другими бронями). Число приходит из той же транзакции, что выдала
   * бронь, то есть измерено, а не оценено. Нет ключа — долив упал до расчёта
   * бюджета либо бронь не выдавалась: остаток не измерен, а нулём его писать
   * нельзя, это прочиталось бы как «бюджет исчерпан». Читатель — обе строки
   * лога прогона (успешная и отказная).
   */
  daily_remaining?: number;
  /**
   * Компаний, под которые кап просит собирать (heRefillCompanyTarget), и лимит
   * компаний, с которым сборка реально шла (collect_info.limit; null — лимита в
   * снапшоте нет). company_limit > company_target — постановка сборки ещё
   * считает объём в строках: разница компаний уже оплачена краулом и пробами, а
   * кап её строки выбросит. Оба числа в воронке затем, чтобы первый ночной счёт
   * объяснялся из журнала, а не из догадок.
   */
  company_target: number;
  company_limit: number | null;
}

/** Итог refill-ветки: он же collect_info.refill_result и (по полям) runs-запись. */
export interface HeRefillResult {
  status: 'appended' | 'no_new' | 'failed';
  campaign_id?: string;
  stats?: HeRefillStats;
  error?: string;
  /**
   * Машинный вид причины отказа рядом с её текстом (только status='failed').
   *
   * Зачем отдельным полем: по тексту провайдера нельзя отличить «у рассыльщика
   * не осталось места под контакты» от «данные плохие», а решения разные —
   * первое лечится местом в воркспейсе и ставит durable-паузу добора проекта
   * (recordRefillCapacityPause, best-effort: без конфига или колонок паузы нет),
   * которую снимает сотрудник, а не таймер; второе требует пересборки базы.
   * Классификация делается ЕДИНСТВЕННЫМ
   * предикатом contact-capacity (isInstantlyContactCapacityError /
   * AppendLeadsResult.capacityBlocked из clientLaunch/appendLeads), своего
   * разбора текстов здесь нет.
   *
   * Значение техническое и в кабинет НЕ уезжает: клиентскую формулировку
   * собирает clientErrors.classifyHeClientError по he_bases.error (кабинет
   * white-label, имя рассыльщика в его payload не попадает).
   */
  error_kind?: 'instantly_capacity';
  /**
   * Только для status='failed': успел ли долив отдать хотя бы одну строку
   * провайдеру. От этого зависит терминальный статус базы (см.
   * runHeRefillAppend), поэтому признак сохраняется в collect_info — иначе
   * решение «выжигать компании или нет» нельзя перепроверить по факту.
   */
  delivery_attempted?: boolean;
  /**
   * Только для status='failed': вернулись ли компании базы в пул сборки
   * (status='failed' у базы) или остались исключёнными ('analyzed'). false при
   * доставленных строках, при брони, которую держит прошлый прогон этой же
   * базы ('already_reserved' — он мог уже отправить), при серии отказов
   * (REFILL_RELEASE_FAIL_STREAK_LIMIT) — по этому полю видно, почему срез
   * больше не поднимается ночными прогонами, — и у ночи без бюджета
   * market='us', перенёсшей компании (`companies_carried`). Всегда true у
   * отмены клиентом без доставки и у ночи без бюджета, чьи компании не
   * перенесены (не 'us' или очередь не записалась).
   */
  companies_released?: boolean;
  /**
   * Только для status='failed', market='us': собственные компании ночи без
   * бюджета ('cap_exhausted') ушли в очередь переноса, база 'analyzed' держит
   * их исключёнными до отправки или срока. Нет ключа — переноса этой ночью
   * не было (компании ночи решены companies_released).
   */
  companies_carried?: true;
  /**
   * Сколько refill-прогонов вертикали упало подряд ДО этого (0 — первый отказ).
   * Считается до предела, нужного решению (REFILL_RELEASE_FAIL_STREAK_LIMIT + 1),
   * а не по всей истории — см. refillFailStreak. Ключа нет — серия решению не
   * понадобилась (доставка, бронь прошлого прогона, ночь без бюджета, отмена).
   */
  fail_streak?: number;
  /**
   * ДОЧИТАЛИ ЛИ каталог этой ночью — см. refillScanComplete. Единственный
   * читатель — правило сухой вертикали (lib/hypothesisEngine/autoPipeline.ts):
   * без этого признака ночь, вставшая по потолку страниц или на оборванном
   * чтении, была бы неотличима от исчерпанного среза, и вертикаль снимали бы с
   * добора за наш собственный предохранитель.
   *
   * Поле НЕ часть воронки (HeRefillStats) — это свойство ЧТЕНИЯ, а не долива, —
   * но в строку прогона уезжает внутрь того же jsonb `stats`: у правила есть
   * только строка he_auto_pipeline_runs, а тащить ради одного флага тяжёлый
   * collect_info каждой ночи (в нём лежат планы и харвесты задач) нельзя.
   * Перенос делает writeRefillRun, см. его докблок.
   */
  scan_complete?: boolean;
  completed_at: string;
}

interface RefillConfigRow {
  id: string;
  dailyLeadsCap: number;
}

/**
 * Дочитан ли каталог этой ночью до конца.
 *
 * `true` — все задачи сборки закончили чтение сами: ни одна не встала по
 * потолку страниц (`hit_ceiling`), ни одна не оборвалась на середине
 * (`partial`), ни одна не упала. Только в этом случае «новых компаний нет»
 * говорит об ИСТОЧНИКЕ. Разбор состояний задачи — хендофф лейна расширения
 * плана: «встал по потолку» и «чтение оборвалось» не означают «сухо» никогда,
 * потому что непрочитанный хвост остался: у pdl повтор продолжает с закладки,
 * а живые фиды (funded, eng_hiring) закладки между сборками не держат и
 * читаются с начала среза, где уже собранные компании отсеиваются на выборке.
 *
 * `false` — читать осталось (потолок, обрыв, упавшая задача) ИЛИ задач не было
 * вовсе: у ночи без единой задачи нулевой результат говорит о плане, а не о
 * рынке. Оба случая одинаково не годятся как показание о сухости.
 *
 * Поле `exhausted` здесь НЕ участвует: оно про ОДИН срез («за закладкой под
 * эти фильтры пусто»), а правило судит ночь целиком, где срезов до четырёх и
 * перемешивает их interleaveTaskHarvests. Сухость источника и сухость среза —
 * разные факты, и путать их нельзя.
 */
function refillScanComplete(info: HeCollectInfo): boolean {
  const tasks = Array.isArray(info.tasks) ? info.tasks : [];
  if (tasks.length === 0) return false;
  return tasks.every(
    (t) => t.status === 'done' && t.hit_ceiling !== true && t.partial !== true && !t.error,
  );
}

/** Начало текущих UTC-суток — дневной бюджет daily_leads_cap считается по ним. */
function utcDayStart(now = new Date()): string {
  return new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate())).toISOString();
}

/**
 * Сколько лидов ПРОЕКТ уже долил за текущие UTC-сутки (все его вертикали).
 *
 * Единственный потребитель — ПРЕДПОЛЁТ размера сборки
 * (resolveHeRefillCollectCompanies). Сам отрез по капу считает не это число, а
 * бронь (reserveRefillDailyBudget): там решение принимается под сериализацией,
 * здесь — оценка «сколько компаний покупать», и ошибаться ей можно только в
 * сторону недобора. Поэтому функция НИКОГДА не бросает: непрочитанная история —
 * ноль, то есть прежний (полный) объём сборки, а не «бюджет исчерпан».
 *
 * Три поправки к прежней арифметике, каждая закрывала свою дыру:
 *  * ключ — ПРОЕКТ, а не config_id. Кап объявлен «на проект в сутки», а
 *    he_auto_pipeline_configs может не быть вовсе (таблица пуста, refill
 *    поставлен руками) — тогда прежний расчёт не считал расход ВООБЩЕ и сборка
 *    шла по полному капу поверх уже отправленного. project_id есть у КАЖДОЙ
 *    строки прогона: её пишет либо крон при постановке, либо writeRefillRun;
 *  * учитываются и прогоны 'failed' с ненулевым `appended`. Долив, упавший
 *    ПОСЛЕ частичного приёма (AppendLeadsPartialError), отправил настоящих
 *    писем настоящим людям — считать такую ночь нулевой значило бы отдать этот
 *    объём следующей вертикали второй раз;
 *  * прогоны без завершения ('collecting') в сумму не идут: у них ещё нет
 *    ни приёма, ни числа. Открытая бронь такого прогона учтена в БРОНЯХ.
 *
 * Перерасход капа это число не сторожит и сторожить не обязано. Прежняя
 * редакция объясняла, что «многочанковый перерасход невозможен», потому что
 * HE_AUTO_REFILL_ROWS_LIMIT=200 меньше чанка отправки в 1000 — неверно дважды:
 * 200 — это КОМПАНИИ, а после split_emails строка — один адрес, и компания
 * даёт до contactCap строк (до 100), а daily_leads_cap сверху не ограничен,
 * так что пачка ночи бывает больше одного чанка. Настоящая граница другая:
 * toSend ≤ выданной брони ≤ остатку замороженного капа дня
 * (reserveRefillDailyBudget), а частичный приём на любом чанке приходит
 * снимком AppendLeadsPartialError и закрывает бронь принятым или попыткой —
 * объём сверх брони не уходит ни при каком числе чанков.
 */
async function refillAppendedToday(ctx: HeStageContext, projectId: string): Promise<number> {
  const { data, error } = await ctx.supabase
    .from('he_auto_pipeline_runs')
    .select('stats')
    .eq('project_id', projectId)
    .in('status', ['appended', 'failed'])
    .gte('completed_at', utcDayStart());
  if (error) throw new Error(`he_auto_pipeline_runs daily spent: ${error.message}`);
  let spent = 0;
  for (const row of data ?? []) {
    const appended = (row as { stats?: { appended?: unknown } }).stats?.appended;
    if (typeof appended === 'number' && Number.isFinite(appended) && appended > 0) {
      spent += appended;
    }
  }
  return spent;
}

/**
 * Конфиг auto-pipeline проекта. Best-effort: таблицы миграции может ещё не
 * быть на окружении (воркер выкатили раньше миграции) — тогда долив идёт с
 * дефолтным капом, а runs-запись пишется без config_id.
 */
async function loadRefillConfig(ctx: HeStageContext, projectId: string): Promise<RefillConfigRow | null> {
  try {
    const { data, error } = await ctx.supabase
      .from('he_auto_pipeline_configs')
      .select('id, daily_leads_cap')
      .eq('project_id', projectId)
      .maybeSingle();
    if (error) throw new Error(error.message);
    if (!data) return null;
    const row = data as { id?: unknown; daily_leads_cap?: unknown };
    const cap =
      typeof row.daily_leads_cap === 'number' && Number.isFinite(row.daily_leads_cap)
        ? row.daily_leads_cap
        : HE_AUTO_DEFAULT_DAILY_LEADS_CAP;
    return { id: String(row.id), dailyLeadsCap: cap };
  } catch (e) {
    stageLog(
      ctx,
      `[base_collect] refill: he_auto_pipeline_configs read: ${e instanceof Error ? e.message : String(e)} — кап по умолчанию`,
    );
    return null;
  }
}

/**
 * Исходы брони дневного бюджета — ВЕСЬ набор, который умеет вернуть
 * he_reserve_refill_daily_budget (миграция 20260930_0004). Перечислен здесь
 * целиком осознанно: ноль выданных строк бывает по трём разным причинам, и
 * воронка обязана их различать, иначе «повтор прогона» читался бы как
 * «исчерпан кап проекта» и лечился бы не тем.
 *
 * Выдали объём: 'granted' (новая бронь либо переоткрытие доказанно пустой) и
 * 'reclaimed' (ПЕРЕХВАТ своей же брони, открытой дольше окна перехвата, —
 * прогон-наследник умершего). Не выдали ничего: 'cap_exhausted' (кап проекта
 * занят другими бронями), 'already_reserved' (бронь этой базы моложе окна:
 * живой двойник) и 'nothing_requested' (спросили ноль — из этой ветки
 * недостижимо, бронь берётся только при kept.length > 0).
 *
 * Все нулевые исходы у долива значат одно: ЭТОТ прогон не отправит НИ ОДНОЙ
 * строки, и ночь кончается отказом (runHeRefillAppend, шаг 5б). Судьба
 * компаний у них РАЗНАЯ, потому что разное знание о доставке:
 *  - 'cap_exhausted' — у этой базы сегодня нет ни брони с расходом, ни
 *    открытой брони (иначе исход был бы 'already_reserved'), то есть провайдер
 *    от неё не получил ничего. Компании не выжигаются ВСЕГДА, вне серии
 *    отказов: у market='us' уходят в очередь переноса, иначе — в пул;
 *  - 'already_reserved' — бронь этой же базы держит её прошлый прогон: открытая
 *    (двойник или умерший предшественник моложе окна) либо закрытая с
 *    расходом. Тот прогон МОГ уже отдать строки провайдеру, поэтому компании
 *    остаются исключёнными ('analyzed'): второе письмо тому же лиду дороже
 *    потерянного лида;
 *  - 'nothing_requested' — недостижим (см. выше).
 */
export type HeRefillBudgetOutcome =
  | 'granted'
  | 'reclaimed'
  | 'cap_exhausted'
  | 'already_reserved'
  | 'nothing_requested';

interface HeRefillBudgetReservation {
  /** null — бронь не выдана (granted = 0). */
  id: string | null;
  granted: number;
  /** Кап, замороженный за проектом на этот UTC-день. */
  dailyCap: number | null;
  /** Занято другими бронями ДО этой. null — не считалось (бронь не выдавалась). */
  spentBefore: number | null;
  outcome: HeRefillBudgetOutcome;
}

/**
 * Занять дневной бюджет проекта ДО первого запроса к рассыльщику.
 *
 * Зачем бронь, а не разность двух чтений журнала. Прежний расчёт («сумма
 * stats.appended за сутки» минус кап) принимался в процессе воркера и ничем не
 * защищён от ВТОРОГО прогона той же джобы. У ENG этот повтор устроен так:
 * `resetStuckJobs()` (worker/hypothesisEngine.ts) на старте воркера закрывает
 * каждую оставшуюся 'running' джобу типизированным
 * HeJobInterruptionError('restart'), а writeJobFailure возвращает её в
 * 'pending' БЕСПЛАТНО — до HE_JOB_FREE_INTERRUPTIONS = 5 прерываний подряд.
 * То есть тот же сбор едет в Instantly ещё раз, и оба прогона видят одинаковый
 * остаток. Бронь решает это в БД: advisory-лок «проект + UTC-день»
 * сериализует решение, а сам кап берётся только с сервера — подменить его
 * вызовом нельзя.
 *
 * ЧЕМ ЭТОТ ПОВТОР НА САМОМ ДЕЛЕ ЯВЛЯЕТСЯ — и почему это меняет цену. Обычно он
 * ПОСЛЕДОВАТЕЛЬНЫЙ: процесс умер, новый его подобрал. Двумя ЖИВЫМИ прогонами
 * они становятся только при перекрытии деплоя (старый контейнер ещё работает,
 * когда стартует новый). Бесусловного bulk-апдейта «все running → pending», от
 * которого оборонялись бы всегда, у ENG нет с волны 3 — он остался у V2
 * (worker/verticalEngineV2.ts). Поэтому чаще всего бронь встречает не двойника,
 * а наследника.
 *
 * ОТЛИЧАЕТ ИХ ВОЗРАСТ ОТКРЫТОЙ БРОНИ, и это единственный доступный признак:
 * lease/heartbeat у ENG нет, а идентификатор джобы у наследника ТОТ ЖЕ (её
 * возвращает в 'pending' resetStuckJobs). Бронь моложе окна перехвата (два
 * часа, миграция 20260930_0004) — считаем, что двойник жив: 'already_reserved',
 * второй порции бюджета нет. Старше — предшественник мёртв: 'reclaimed', та же
 * база забирает свою бронь и досылает хвост, как досылала при прежней
 * арифметике двух чтений журнала (дубли по-прежнему отсекает
 * skipIfInCampaign). Два часа — примерно четырёхкратный запас к самому долгому
 * законному молчанию стадии (сторож простоя ≤ 30 мин + 2 мин на раскрутку,
 * worker/hypothesisEngine.ts), см. «ПОЧЕМУ ДВА ЧАСА» в миграции.
 *
 * ЦЕНА, КОТОРАЯ ОСТАЛАСЬ. Наследник, пришедший РАНЬШЕ окна (перезапуск воркера
 * через минуту — обычный случай), хвост не досылает, а незакрытая бронь до
 * конца UTC-суток держит объём для ОСТАЛЬНЫХ баз проекта: их вертикали в ту же
 * ночь получают 'cap_exhausted'. Освобождать чужой объём по возрасту нельзя —
 * у чужой базы другие адреса, и это была бы настоящая отправка поверх капа.
 * Компаний эти ночи не выжигают: 'cap_exhausted' при любой серии отказов
 * переносит компании своей базы в очередь (market='us'; шаг 5б ниже) либо
 * возвращает их в пул — тогда теряется оплаченная сборка ночи (её срез
 * следующая сборка купит заново), а не сами компании. Сам наследник ('already_reserved') компании своей базы НЕ
 * возвращает: предшественник мог успеть их отправить, а его приём наследнику
 * не виден — ни строкой прогона (её предшественник не дописал), ни бронью
 * (она открыта и держит весь выданный объём). Отсюда же недосчёт: принятое
 * предшественником не попадёт ни в stats.appended наследника, ни в
 * refillAppendedToday; кап это не ломает — открытая бронь держит объём до
 * конца суток, — но воронка ночи покажет ноль там, где письма могли уйти.
 *
 * FAIL-CLOSED, И ОТСЮДА ПОРЯДОК ВЫКАТА: СНАЧАЛА МИГРАЦИЯ 20260930_0004, ПОТОМ
 * ЭТОТ КОД. Любая ошибка вызова (нет миграции, нет прав, сбой БД) БРОСАЕТ, и
 * долив уходит в общий отказ, не отправив ни строки. Значит код, уехавший
 * раньше миграции, останавливает ночной добор ВСЕХ ENG-проектов целиком — это
 * не мягкая деградация, а ноль отправок при оплаченных сборах. Сторона выбрана
 * по цене ошибки: провайдер строк не видел → база 'failed' → её компании
 * возвращаются в пул при ПЕРВОМ отказе подряд (со второго их удерживает серия
 * отказов — сбой брони повторяется сам, пока не применена миграция), а
 * отправленное сверх капа не отзывается.
 */
async function reserveRefillDailyBudget(
  ctx: HeStageContext,
  input: { projectId: string; baseId: string; requested: number },
): Promise<HeRefillBudgetReservation> {
  const { data, error } = await ctx.supabase.rpc('he_reserve_refill_daily_budget', {
    p_project_id: input.projectId,
    p_base_id: input.baseId,
    p_requested: input.requested,
  });
  if (error) throw new Error(`he_refill daily budget reservation: ${error.message}`);
  const rows = Array.isArray(data) ? data : [];
  const row =
    rows.length === 1 && rows[0] && typeof rows[0] === 'object'
      ? (rows[0] as Record<string, unknown>)
      : null;
  const granted = row?.granted;
  const reservationId = row?.reservation_id;
  const raw = row?.outcome;
  const outcome: HeRefillBudgetOutcome | null =
    raw === 'granted' || raw === 'reclaimed' || raw === 'cap_exhausted'
      || raw === 'already_reserved' || raw === 'nothing_requested'
      ? raw
      : null;
  // Снимок проверяется целиком: половина ответа (например granted без брони)
  // означала бы, что мы отправим строки, за которые никто не расписался.
  if (
    outcome === null
    || typeof granted !== 'number'
    || !Number.isSafeInteger(granted)
    || granted < 0
    || granted > input.requested
    || (granted > 0 && (typeof reservationId !== 'string' || !reservationId))
    || (granted === 0 && reservationId !== null && reservationId !== undefined)
    // Объём выдают ровно два исхода, и наоборот: ненулевой granted без одного
    // из них означал бы, что мы отправим строки, за которые никто не расписался.
    || (outcome === 'granted' || outcome === 'reclaimed') !== (granted > 0)
  ) {
    throw new Error('he_refill daily budget reservation returned an invalid snapshot');
  }
  const asCount = (value: unknown): number | null =>
    typeof value === 'number' && Number.isSafeInteger(value) && value >= 0 ? value : null;
  return {
    id: granted > 0 ? (reservationId as string) : null,
    granted,
    dailyCap: asCount(row?.daily_cap),
    spentBefore: asCount(row?.spent_before),
    outcome,
  };
}

/**
 * Записать фактический расход брони и отпустить неиспользованное.
 *
 * НИКОГДА не бросает и никогда не валит долив: незавершённая бронь держит весь
 * свой объём до конца UTC-суток, то есть отказ этой записи даёт НЕДОотправку
 * (видна в воронке следующей ночи), а не отправку поверх капа. Обратная
 * сторона — тоже осознанная: «освободить» мы можем только то, что точно не
 * ушло, поэтому на неопределённом отказе (`AppendLeadsPartialError` с
 * попытками) расходом считается ПОПЫТКА, а не подтверждённый приём. Точно не
 * ушли строки, которые провайдер сам отклонил по ёмкости (deferredIndexes —
 * «безопасно повторить» по контракту appendLeads): их бронь отпускает.
 *
 * Идёт клиентом СТАДИЙ (а не paidCheckpointDb): запись только УМЕНЬШАЕТ
 * занятое, и её отказ после abort'а безопасен — в отличие от терминальной
 * записи базы и строки прогона, которые фиксируют уже потраченные деньги.
 */
async function finalizeRefillDailyBudget(
  ctx: HeStageContext,
  input: { reservationId: string | null; baseId: string; consumed: number },
): Promise<void> {
  if (!input.reservationId) return;
  try {
    const { error } = await ctx.supabase.rpc('he_finalize_refill_daily_budget', {
      p_reservation_id: input.reservationId,
      p_base_id: input.baseId,
      p_consumed: input.consumed,
    });
    if (error) throw new Error(error.message);
  } catch (e) {
    stageLog(
      ctx,
      `[base_collect] refill: бронь дневного бюджета не закрыта ` +
        `(${e instanceof Error ? e.message : String(e)}) — остаток занят до конца UTC-суток`,
    );
  }
}

/**
 * Финал прогона в he_auto_pipeline_runs: крон пишет строку 'collecting' при
 * постановке — обновляем её по base_id; не нашли (refill поставлен вручную) —
 * вставляем финальную строку целиком. Best-effort: журнал — аудит, падение
 * записи не должно валить стадию после уже случившегося долива.
 *
 * Запись — ДЕНЬГИ, а не аудит, и поэтому идёт клиентом БЕЗ сигнала джобы
 * (paidCheckpointDb): в `stats.appended` лежит число лидов, которых Instantly УЖЕ
 * принял. Отправку сверх капа эта строка НЕ сторожит — прежняя редакция
 * утверждала обратное («следующая ночь видит бюджет нетронутым и отправляет
 * поверх капа»), но с брони дневного бюджета (he_refill_daily_reservations,
 * миграция 20260930_0004) кап держит бронь в БД, и потерю этой строки она не
 * замечает; к тому же кап — на UTC-сутки, и «следующая ночь» живёт уже с новым.
 * Что стоит потерянная строка на самом деле:
 *  - ПРЕДПОЛЁТНЫЙ размер сборки (refillAppendedToday) не видит расход этого
 *    прогона и в те же сутки покупает компании, чьи строки бронь потом
 *    выбросит;
 *  - лента кабинета и воронка ночей не видят эту ночь (строка остаётся
 *    'collecting');
 *  - серия отказов вертикали (refillFailStreak) и правило сухой вертикали
 *    читают журнал; зависшую 'collecting' строку серия отказов разбирает по
 *    статусу её базы, а правило сухой вертикали пропускает.
 *
 * ЧТЕНИЯ здесь нет СОЗНАТЕЛЬНО. Раньше строку сначала искали `select('id')`, и
 * это чтение — клиентом стадий, потому что через клиент чекпойнта чтения не идут
 * — после аборта отвергалось, уводя весь вызов в catch: строка не появлялась
 * именно в том прогоне, ради которого запись и освобождали от сигнала. Поэтому
 * апдейт сам адресуется по (base_id, status='collecting') и возвращает
 * затронутые id, а вставка нужна только когда не затронуто ничего. Дублей это не
 * добавляет: барьер `status='collecting'` тот же, что стоял в поиске, — повтор
 * стадии поверх уже завершённой строки не попадает в апдейт и, как и раньше,
 * вставляет отдельную строку прогона.
 */
async function writeRefillRun(
  ctx: HeStageContext,
  write: {
    configId: string | null;
    projectId: string;
    verticalId: string;
    baseId: string;
    result: HeRefillResult;
  },
): Promise<void> {
  const patch = {
    status: write.result.status,
    // `scan_complete` подмешивается в тот же jsonb, что и воронка: у правила
    // сухой вертикали есть только строка прогона, а различать «источник пуст»
    // и «мы не дочитали» оно обязано (см. HeRefillResult.scan_complete).
    // Ключ пишется ТОЛЬКО когда он известен: его отсутствие — это «не знаем»,
    // и правило трактует такую ночь как непригодную для приговора.
    stats: {
      ...((write.result.stats ?? {}) as Record<string, unknown>),
      ...(write.result.scan_complete === undefined
        ? {}
        : { scan_complete: write.result.scan_complete }),
    },
    error: write.result.error ?? null,
    completed_at: write.result.completed_at,
  };
  const db = paidCheckpointDb(ctx);
  try {
    const { data: updated, error: updErr } = await db
      .from('he_auto_pipeline_runs')
      .update(patch)
      .eq('base_id', write.baseId)
      .eq('status', 'collecting')
      .select('id');
    if (updErr) throw new Error(updErr.message);
    if (!updated || updated.length === 0) {
      const { error } = await db.from('he_auto_pipeline_runs').insert({
        config_id: write.configId,
        project_id: write.projectId,
        vertical_id: write.verticalId,
        base_id: write.baseId,
        ...patch,
      });
      if (error) throw new Error(error.message);
    }
  } catch (e) {
    stageLog(
      ctx,
      `[base_collect] refill: запись he_auto_pipeline_runs не удалась: ${e instanceof Error ? e.message : String(e)}`,
    );
  }
}

/**
 * Терминальный апдейт refill-базы: строки как в обычном пути, статус —
 * 'analyzed' при доливе и 'failed' у недоставленного отказа, компании
 * которого возвращаются в пул (см. runHeRefillAppend).
 * Строки сохраняются в любом случае: отчёт и разбор причины идут по ним.
 *
 * he_bases.error пишется ВСЕГДА, а не «когда передали»: у 'failed' — причина, у
 * 'analyzed' — пусто. Пустое у 'analyzed' не формальность: cancel-роут мог
 * успеть записать базе 'Cancelled by user' (он переводит 'collecting' в
 * 'failed' по проекту целиком), а долив, уже отдавший строки провайдеру, всё
 * равно пишет базе 'analyzed' — и отмена на отработанной базе читалась бы
 * кабинетом как остановленный шаг, а у 'analyzed'-базы непустой error — как
 * сломанная база.
 *
 * Идёт клиентом БЕЗ сигнала джобы (paidCheckpointDb) — это запись ДЕНЕГ, и самых
 * дорогих в движке: к обоим её вызовам Instantly мог УЖЕ принять лидов в живую
 * кампанию, а приём не отменяется. Она же несёт решение о судьбе компаний
 * (`companies_released`). Пока запись была привязана к сигналу, abort (отмена
 * клиентом или сторож простоя) отвергал её ОБА раза — сначала в успешной ветке,
 * потом в catch'е, — и стадия падала наружу, оставив базу в 'collecting': лиды в
 * кампании есть, базы, воронки и решения нет. Дальше финальный фейл джобы уводил
 * такую базу в 'failed' (repairBaseAfterCollectFinalFail), а 'failed'-база
 * выпадает из кросс-базового исключения (loadOtherBaseExclusionKeys) — то есть
 * УЖЕ НАПИСАННЫЕ компании объявлялись несобранными, и ночной крон пересобирал их
 * за деньги (второе письмо спасал только skipIfInCampaign, оплаченный краул и
 * SMTP-пробы — нет).
 */
async function persistRefillBase(
  ctx: HeStageContext,
  baseId: string,
  args: {
    columns: string[];
    rows: HeUnifiedRow[];
    info: HeCollectInfo;
    stats: HeCollectInfo['stats'];
    refillResult: HeRefillResult;
  } & (
    | { status: 'analyzed' }
    | {
        status: 'failed';
        /** Текст в he_bases.error (кабинет сворачивает его в машинный код). */
        error: string;
      }
  ),
): Promise<void> {
  const { error } = await paidCheckpointDb(ctx)
    .from('he_bases')
    .update({
      columns: args.columns,
      sample_rows: args.rows.slice(0, SAMPLE_ROWS),
      data: args.rows,
      row_count: args.rows.length,
      status: args.status,
      error: args.status === 'failed' ? args.error : null,
      collect_info: { ...args.info, stats: args.stats, refill_result: args.refillResult },
      updated_at: new Date().toISOString(),
    })
    .eq('id', baseId);
  if (error) throw new Error(`he_bases refill update: ${error.message}`);
}

/**
 * Дошла ли до провайдера хотя бы одна строка упавшего долива.
 *
 * Зачем: loadOtherBaseExclusionKeys (stages/baseCollect.ts) исключает из
 * будущих сборок проекта компании всех баз, КРОМЕ 'failed'. Пока упавший
 * долив сохранялся в 'analyzed', его компании выжигались навсегда: сбор
 * оплачен, письма не ушли, второй раз эти компании не соберутся. Отдавать их
 * обратно в сборку можно только когда Instantly точно ничего не получил —
 * повторное письмо уже написанному лиду хуже потерянного лида.
 *
 * AppendLeadsPartialError несёт снимок результата; attemptedIndexes
 * заполняется в onRequestAttempt ПЕРЕД HTTP-запросом, поэтому непустой
 * список означает «запрос мог долететь, даже если ответ потерян». Остальные
 * отказы долива (нет кампании или пресета, сменившийся воркспейс, blocklist,
 * нулевая ёмкость по ПРЕДПОЛЁТУ appendLeads) бросаются до первого запроса в
 * Instantly. Исчерпанный лимит контактов воркспейса бывает и ОТВЕТОМ на
 * запрос — о нём ниже.
 *
 * Два исключения из «попытка = возможно доставлено» — оба про строки, которые
 * провайдер ЯВНО отклонил сам:
 *  - отказ по частоте запросов (429): запрос «отклонён целиком», и при нулевом
 *    accepted строки гарантированно не приняты (см. refillRateLimitRefusal);
 *  - отказ по ёмкости воркспейса: appendLeads (pauseOnWorkspaceCapacity)
 *    кладёт такие строки в deferredIndexes — по его контракту это «точные
 *    отказы провайдера, которые безопасно повторить», — и в 4xx «лимит
 *    контактов» (весь чанк), и в 200 с leads_uploaded=0 при нуле остатка
 *    (refillAttemptsNotProvenRefused). Попытка, попавшая в deferred, доставкой
 *    не считается.
 * Считать такую ночь доставленной значило бы выжигать оплаченный срез из-за
 * паузы провайдера. Ответ с частичным приёмом (accepted > 0) по-прежнему
 * доставка: он решается ВЫШЕ обоих исключений, даже если следующий чанк получил
 * отказ. Попытка БЕЗ явного ответа (сорванный сокет, истёкший срок) — по-прежнему
 * «возможно, долетел».
 *
 * Отсюда инвариант: доставленная база НИКОГДА не уходит в 'failed' решением
 * ЭТОГО прогона, поэтому в released-базе не может быть компании, которой уже
 * писал он сам (её собственный сбор исключал все не-'failed' базы проекта, а
 * доставленные базы остаются 'analyzed'). Прогон, который сам не отправлял, но
 * чью базу мог отправить ДРУГОЙ прогон той же джобы — живой двойник при
 * перекрытии деплоя или наследник умершего предшественника, — получает от
 * брони 'already_reserved' и компании тоже не возвращает (runHeRefillAppend):
 * доставку предшественника он не видит, а «не знаем» — это 'analyzed'.
 * Путей, где база с доставкой всё же может стать 'failed', два, и оба — когда
 * терминальная запись ЭТОГО прогона (persistRefillBase, оба вызова) не дошла:
 *   - ремонт воркера после ФИНАЛЬНОГО фейла base_collect — на первом отказе
 *     подряд либо когда сам ремонт сорвался до записи базы (тогда прежний
 *     'failed'); со второго подряд база уходит в 'analyzed' со строками среза
 *     (closeHeRefillBaseUndelivered, CAS по 'collecting');
 *   - отмена клиентом, пришедшая во время долива: cancel-роут пишет
 *     'collecting'-базе 'failed', и переписать её 'analyzed' было некому.
 * Второе письмо в обоих случаях не уходит: долив идёт со skipIfInCampaign=true
 * (Instantly отсеет лида, который уже в кампании), а start-guard стадии
 * (`status !== 'collecting'` → throw) не даёт повторно собрать базу с
 * терминальным статусом. Цена — деньги сбора: компании вернутся в пул и будут
 * собраны ещё раз.
 */
function refillLeadsReachedProvider(e: unknown): boolean {
  if (!(e instanceof AppendLeadsPartialError)) return false;
  const partial = e.partialResult;
  if (partial.accepted > 0) return true;
  // Провайдер ОТВЕТИЛ «слишком часто» — это доказательство НЕприёма: запрос
  // отклонён целиком, лидов он не создал. Неопределённость (сорванный сокет,
  // истёкший срок, потерянный ответ) сюда не попадает — только явный HTTP-код.
  if (refillRateLimitRefusal(e)) return false;
  return refillAttemptsNotProvenRefused(partial) > 0;
}

/**
 * Сколько строк ушло в транспорт и НЕ отклонено провайдером явно.
 *
 * attemptedIndexes — «запрос мог долететь», deferredIndexes — строки, которые
 * провайдер сам отказался взять по ёмкости (явный 4xx на чанке либо 200 с
 * нулём остатка, где все пропуски не объяснены окончательными причинами;
 * appendLeads заполняет его только при pauseOnWorkspaceCapacity). Разница —
 * строки, чей приём не подтверждён и не опровергнут: именно они делают ночь
 * «возможно, доставленной» и именно их бронь не вправе отпустить. Строки,
 * окончательно отсеянные провайдером (дубль кампании, невалидный адрес), в
 * deferred не попадают и остаются здесь: провайдер их видел.
 */
function refillAttemptsNotProvenRefused(result: {
  attemptedIndexes: readonly number[];
  deferredIndexes?: readonly number[];
}): number {
  const refused = new Set(result.deferredIndexes ?? []);
  let open = 0;
  for (const index of result.attemptedIndexes) if (!refused.has(index)) open += 1;
  return open;
}

/**
 * Явный отказ Instantly по частоте запросов (HTTP 429).
 *
 * Зачем отдельно: хук beforeProviderRequest (признак жизни для сторожа простоя)
 * в appendLeads.ts связан ОДНОЙ строкой с двумя другими опциями — таймаут 90 с
 * с чтением тела и `retryRateLimits: false`. То есть, взяв видимость для
 * сторожа, ночной долив потерял пересиживание 429 внутри клиента Instantly
 * (4+8+16 с), и 429 на ПЕРВОМ чанке стал прилетать сюда как отказ. А
 * attemptedIndexes заполняются в onRequestAttempt ДО HTTP-запроса — значит без
 * этого предиката разовый 429 читался бы как «провайдер строки получил»: база
 * сохранялась 'analyzed' с нулём доставленных лидов, а её компании исключались
 * из ВСЕХ будущих сборок проекта (loadOtherBaseExclusionKeys). Оплаченный краул
 * и SMTP-пробы сгорали из-за паузы провайдера на минуту.
 *
 * Разбор по тексту здесь — не выбор, а следствие: AppendLeadsPartialError
 * переносит наружу только `message` исходной ошибки (ни `cause`, ни статуса), а
 * appendLeads.ts делит файл с ОПЛАЧИВАЕМЫМ RU-кабинетом и обязан остаться
 * байт-в-байт. Поэтому класс читается напрямую, когда ошибка дошла не
 * завёрнутой, и по стабильному префиксу сообщения клиента Instantly
 * (`Instantly API <код>: …`, lib/instantly/client.ts) — когда завёрнутой.
 * Чистое решение — развязать три опции в appendLeads и дать ошибке `cause`;
 * это правка общего с платящим контуром файла и требует решения владельца.
 */
function refillRateLimitRefusal(e: unknown): boolean {
  if (e instanceof InstantlyApiError) return e.status === 429;
  return e instanceof Error && /^Instantly API 429\b/.test(e.message);
}

/**
 * Код ЯВНОГО отказа провайдера по тексту ошибки: `Instantly API <4xx>: …` —
 * ответ пришёл, и рассыльщик отклонил запрос целиком (лид не создан). 429 —
 * тоже такой отказ. Пятисотые, сорванный сокет, истёкший срок и всё, что не
 * от рассыльщика (журнал доставки, отмена, пресет), — null: приём там не
 * опровергнут. Разбор по префиксу текста — по той же причине, что у
 * refillRateLimitRefusal: AppendLeadsPartialError переносит только `message`.
 * Читают refillGroupFailure, отказ сегментной кампании
 * (refillSegmentCampaignRefusal) и закрепления журнала доставки
 * (readHeRefillLedgerPins: отказанная так партия адрес не закрепляет).
 */
function refillProviderRefusalStatus(message: string): number | null {
  const match = /^Instantly API (\d{3})\b/.exec(message);
  const status = match ? Number(match[1]) : null;
  return status !== null && status >= 400 && status < 500 ? status : null;
}

function refillExplicitRefusalStatus(e: unknown): number | null {
  if (e instanceof InstantlyApiError) return e.status >= 400 && e.status < 500 ? e.status : null;
  return e instanceof Error ? refillProviderRefusalStatus(e.message) : null;
}

/**
 * Позиции вызова, чей запрос провайдер отклонил явно: ушли в транспорт и не
 * получили ответа чанка (ни принятых, ни отсеянных, ни отложенных по ёмкости).
 * Строки чанка, на который провайдер ОТВЕТИЛ раньше отказа, сюда не входят —
 * провайдер их видел. Позиции — в нумерации самого вызова.
 */
function refillRefusedAttempts(partial: AppendLeadsResult): number[] {
  const answered = new Set([
    ...(partial.acceptedIndexes ?? []),
    ...(partial.skippedIndexes ?? []),
    ...(partial.deferredIndexes ?? []),
  ]);
  return partial.attemptedIndexes.filter((index) => !answered.has(index));
}

/**
 * Сегментная кампания отказала ЯВНО и ничего не приняла — код ответа или null
 * (блок «ОТКАЗ СЕГМЕНТНОЙ КАМПАНИИ» ниже). Условия все сразу:
 *  - ошибка долива этой кампании несёт снимок (AppendLeadsPartialError: HTTP-
 *    отказ чанка appendLeads всегда заворачивает в него);
 *  - ответ — 4xx, кроме 429 (частоту запросов следующая кампания того же
 *    воркспейса получила бы так же, и 429 уже откладывается refillGroupFailure)
 *    и кроме ёмкости воркспейса (её отказ решает пауза, а не другая кампания);
 *  - кампания не приняла ни строки, и единственный ушедший запрос — отказанный:
 *    ни один чанк этой кампании до отказа не получил ответа.
 * Типичный случай — кампанию сегмента удалили или заархивировали у
 * рассыльщика (404/400): отказ про КАМПАНИЮ, а не про строки и не про
 * воркспейс, поэтому её строки можно отдать основной кампании.
 */
function refillSegmentCampaignRefusal(e: unknown): number | null {
  if (!(e instanceof AppendLeadsPartialError)) return null;
  const partial = e.partialResult;
  if (partial.accepted > 0 || partial.capacityBlocked === true || refillCapacityRefusal(e)) return null;
  const refused = refillRefusedAttempts(partial);
  if (refused.length === 0 || refused.length !== partial.attemptedIndexes.length) return null;
  const status = refillExplicitRefusalStatus(e);
  return status !== null && status !== 429 ? status : null;
}

/**
 * Текст отказа «у рассыльщика не осталось места под контакты».
 *
 * Пишется в he_bases.error и refill_result.error рядом с машинным
 * error_kind='instantly_capacity'. Формулировка стабильная НАМЕРЕННО: по ней
 * клиентский классификатор (clientErrors.classifyHeClientError) отличает
 * «некуда грузить» от «данные плохие». Менять — только вместе с его правилом.
 */
const REFILL_CAPACITY_NOTE = 'Instantly: лимит контактов воркспейса исчерпан';

/**
 * Отказ долива про ёмкость воркспейса?
 *
 * Своего разбора текстов нет: capacityBlocked ставит внутри
 * appendLeadsToClientCampaign тот самый предикат isInstantlyContactCapacityError
 * (он же проверяется здесь напрямую — отказ мог прилететь и не завёрнутым), а
 * третья ветка узнаёт наш собственный отказ «провайдер не принял ни строки»,
 * который эта стадия бросает сама (см. долив ниже).
 */
function refillCapacityRefusal(e: unknown): boolean {
  if (isInstantlyContactCapacityError(e)) return true;
  if (e instanceof AppendLeadsPartialError && e.partialResult.capacityBlocked === true) return true;
  return e instanceof Error && e.message.includes(REFILL_CAPACITY_NOTE);
}

/**
 * Остановить ночной добор ПРОЕКТА durable-паузой: воркспейс рассыльщика полон,
 * и это знание обязано пережить текущую ночь.
 *
 * ЗАЧЕМ ИМЕННО ОТСЮДА. Предполёт ёмкости в кроне спрашивает
 * /workspace-billing/plan-details, и без scope на биллинг ответ у него —
 * «не знаем» (getWorkspaceContactCapacity отдаёт null на 403). Тогда
 * единственное доказательство переполнения — отказ провайдера на /leads/add,
 * то есть ЭТО МЕСТО. Оно же — требуемая деградация «ответ импорта
 * авторитетен»: предполёт молчит, импорт отвечает, решение принимается по
 * ответу импорта.
 *
 * ЦЕНА НОЧИ, КОТОРУЮ ЭТО ЭКОНОМИТ, УЖЕ ЗАПЛАЧЕНА. Пауза не возвращает деньги
 * текущей ночи и сама stats.deferred не досылает — она отменяет СЛЕДУЮЩУЮ
 * покупку сборки, которую некуда отправить. Отложенные компании успешной ночи
 * хранит перенос (he_refill_carryover): после снятия паузы они идут первыми,
 * если их срок ещё не вышел.
 *
 * Команде об этой паузе сообщает НЕ эта функция, а alertRefillCapacityStop —
 * в момент, когда причина паузы стала известна, то есть ДО терминальных
 * записей: abort посреди них не должен оставить кабинет с фразой «команда уже
 * работает» без алерта.
 *
 * ЗАПИСЬ BEST-EFFORT И ПОСЛЕДНЯЯ В ПОРЯДКЕ. Она идёт ПОСЛЕ терминальной записи
 * базы, закрытия брони и строки прогона: те фиксируют уже потраченные деньги и
 * обязаны состояться в любом случае, а пауза — про завтра. Клиент стадии здесь
 * ОБЫЧНЫЙ (ctx.supabase, с сигналом джобы), а не paidCheckpointDb: критерий
 * того исключения — «запись фиксирует УЖЕ СДЕЛАННУЮ оплату», и пауза под него
 * не подходит. Плата за это названа прямо: прогон, прерванный abort'ом ровно
 * здесь, паузу не запишет, и следующая ночь купит одну сборку, которую
 * отказ провайдера остановит снова — уже с паузой.
 *
 * Конфига у проекта может не быть (таблица пуста, refill поставлен руками) —
 * тогда пауза не ставится, и это верно: ночного тика у такого проекта нет.
 */
async function recordRefillCapacityPause(
  ctx: HeStageContext,
  projectId: string,
  source: string,
): Promise<void> {
  const paused = await pauseHeAutoPipelineRefill(
    ctx.supabase,
    projectId,
    buildHeCapacityPauseReason(source),
  );
  stageLog(
    ctx,
    paused
      ? '[base_collect] refill: ночной добор проекта остановлен по ёмкости воркспейса — '
        + 'вернуть его может только сотрудник (Движок вертикалей → карточка проекта)'
      : '[base_collect] refill: durable-пауза по ёмкости НЕ записана '
        + '(пауза уже стояла, конфига добора нет либо колонок паузы нет) — '
        + 'ночной тик решает как раньше',
  );
}

/**
 * Алерт команде: долив этой ночи упёрся в ёмкость рассыльщика, ночной добор
 * проекта встаёт на паузу. Контракт лейна алертов (opsAlert.ts) — ровно эти
 * поля.
 *
 * ЗАЧЕМ ИМЕННО ЗДЕСЬ. Кабинет ENG показывает клиенту на карточке базы, в ленте
 * («M not sent», «refill stopped») и в Command Center одну и ту же фразу
 * HE_TEAM_ON_IT_EN — «временная проблема на нашей стороне, команда уже
 * работает» (components/client-eng/clientFailureText.ts). Вторая её половина
 * правдива, только пока этот вызов стоит: убрать его можно только вместе с
 * фразой.
 *
 * Зовётся там, где ПРИСВАИВАЕТСЯ capacityPauseSource — и в успешной ветке, и в
 * catch'е, — то есть раньше терминальной записи базы, строки прогона и самой
 * паузы, и независимо от того, ляжет ли пауза потом (нет конфига, нет колонок):
 * карточка базы и лента показывают фразу в любом случае. Повтор того же
 * проекта в течение 6 ч гасит дедупликация opsAlert.
 *
 * `void`: воркер долгоживущий, ждать Telegram ему незачем; функция не бросает
 * никогда и сама ограничена 15 с. Пачку, отложенную в свёртку, воркер шлёт при
 * штатной остановке (flushHeOpsAlerts в worker/hypothesisEngine.ts).
 * Рынок — ctx.market: refill бывает только у market='us', а не-'us' opsAlert
 * отбрасывает сам, в одном месте.
 */
function alertRefillCapacityStop(ctx: HeStageContext, job: HeJob, baseId: string, source: string): void {
  void notifyHeClientStop({
    projectId: job.project_id,
    market: ctx.market ?? null,
    stage: 'base_collect (refill)',
    kind: 'capacity_pause',
    provider: 'sending',
    reason: source,
    jobId: job.id,
    baseId,
  });
}

/**
 * Алерт команде: шаг 3a снял ВСЕ строки ночи — письмо запущенной кампании
 * прочиталось бы у каждой неверно (heRefillUnfilledRows), отправлять нечего.
 * Сборка этой ночи уже куплена (кроме ночи только из переноса, carryOnly —
 * это пишется в причине). Ночь со своими строками запишется 'appended' с
 * нулём и в серию сухих ночей не пойдёт: это проблема писем, а не рынка, и
 * пометкой сухой вертикали её не лечить. Ночь без своих строк, у которой
 * сняты только компании очереди переноса (`noNew`: они ждут писем с прошлых
 * ночей), — 'no_new', как и до их переноса: новых компаний рынок не дал.
 * Без алерта команда видела бы это только в логах воркера, а клиент — строку
 * ленты каждую ночь. Компании без иного адреса ночь кладёт (свои) или
 * возвращает (перенесённые) в очередь переноса с пометкой «ждёт писем», если
 * дойдёт до итога без отказа (блок «ПЕРЕНОС», шаги 1 и 5): переписанный и
 * перезапущенный шаблон отправит их следующей же ночью вертикали, пока не
 * вышел срок очереди.
 * Отказ писем, не зависящий от строк, тик крона ловит ещё до покупки (шаг
 * 3a-- в autoPipeline.ts, тот же вид алерта) — сюда доходят пустые ячейки у
 * всех строк ночи и то, чего тик видеть не мог: колонка, которой у этой базы
 * не оказалось, или шаблон, запущенный между тиком и доливом.
 *
 * Зовётся сразу после отбора (до чёрного списка и брони): исход ночи от
 * дальнейших шагов не зависит — лидов для отправки уже нет. Повтор той же
 * вертикали в течение 6 ч гасит дедупликация opsAlert (вид 'letters_held');
 * следующая ночь пишет снова. `void` — как у alertRefillCapacityStop; рынок —
 * тот, по которому шаг 3a вообще снимает строки (args.market, только 'us').
 */
function alertRefillLettersHeld(
  job: HeJob,
  base: { id: string; vertical_id: string },
  market: HeMarket | undefined,
  campaignId: string,
  held: number,
  details: string,
  carryOnly: boolean,
  noNew: boolean,
): void {
  void notifyHeClientStop({
    projectId: job.project_id,
    market: market ?? null,
    stage: 'base_collect (refill)',
    kind: 'letters_held',
    provider: 'letters',
    // Причина письма — первой: opsAlert режет текст до HE_OPS_REASON_MAX.
    reason:
      `${details} (снято ${held} из ${held} адр. ночи; кампания ${campaignId}` +
      `${carryOnly ? '; ночь только из переноса, сборка не покупалась' : ''})`,
    jobId: job.id,
    baseId: base.id,
    verticalId: base.vertical_id,
    clientSees: noNew
      ? 'строку ленты «refill: nothing new to send»; вертикаль остаётся «live»'
      : `строку ленты «refill: +0 leads, ${held} skipped (the letters would not read right for ` +
        `${held === 1 ? 'this contact' : 'these contacts'})»; вертикаль остаётся «live»`,
  });
}

/**
 * Алерт команде: сегментная кампания запуска явно отказала, не приняв ни
 * строки (блок «РАСКЛАДКА», п. 7) — почти наверняка её удалили или
 * заархивировали у рассыльщика. Проект не остановлен, но текст сегмента не
 * уходит никому, и без алерта команда видела бы это только в логе воркера и в
 * stats.segment_refusals.
 *
 * Зовётся, когда итог переотправки УЖЕ известен (`fate`, как в
 * stats.segment_refusals), и до терминальных записей: текст говорит, что
 * стало с лидами, а не что собирались сделать. Id кампаний идут отдельными
 * полями (`campaignId`, `mainCampaignId` → строки контекста сообщения), а не в
 * причине: причину opsAlert вымарывает (redactSecrets), и UUID кампании стал
 * бы «[redacted]». Повтор той же вертикали в течение 6 ч гасит дедупликация
 * opsAlert (вид 'segment_refused', окно по вертикали): несколько мёртвых
 * сегментов одной ночи — одна новость. Следующие ночи удалённую кампанию
 * видит уже шаг 4c (404 → строки сегмента удерживаются) и пишет свой алерт
 * ('segments_held', notifyHeRefillHold). `void` и рынок — как у
 * alertRefillLettersHeld.
 */
function alertRefillSegmentRefused(
  job: HeJob,
  base: { id: string; vertical_id: string },
  market: HeMarket | undefined,
  refusal: {
    campaignId: string;
    mainCampaignId: string;
    segment: string;
    httpStatus: number;
    leads: number;
    pinned: number;
    fate: NonNullable<HeRefillStats['segment_refusals']>[number]['fate'];
  },
): void {
  const rest = refusal.leads - refusal.pinned;
  const fateText = {
    main: `${rest} лид. переотправлены в основную кампанию с основным текстом`,
    not_sent: `${rest} лид. не отправлены и с брони не списаны (основная кампания не подтверждена, отказала или прогон отменён)`,
    unknown: `переотправка ${rest} лид. в основную кампанию оборвалась без ответа — считаются возможно доставленными`,
    none: 'переотправлять некого',
  }[refusal.fate];
  const clientSees = {
    main: 'обычную ночь в ленте: контакты сегмента отправлены в основную кампанию (с основным текстом)',
    not_sent: 'строку ленты «refill failed» (или «refill cancelled» при отмене): контакты сегмента этой ночью не отправлены',
    unknown: 'строку ленты «refill failed»: исход переотправки контактов сегмента неизвестен',
    none: 'обычную ночь в ленте: контакты сегмента уже получали письма этой кампании раньше',
  }[refusal.fate];
  void notifyHeClientStop({
    projectId: job.project_id,
    market: market ?? null,
    stage: 'base_collect (refill)',
    kind: 'segment_refused',
    provider: 'sending',
    // Итог — первым: opsAlert режет текст до HE_OPS_REASON_MAX.
    reason:
      `кампания сегмента ответила HTTP ${refusal.httpStatus}, не приняв ни строки: ${fateText}` +
      (refusal.pinned > 0
        ? `; ещё ${refusal.pinned} лид. уже получали письма этой кампании — не переотправлены`
        : '') +
      ` (сегмент «${refusal.segment.slice(0, 60)}»)`,
    httpStatus: refusal.httpStatus,
    jobId: job.id,
    baseId: base.id,
    verticalId: base.vertical_id,
    campaignId: refusal.campaignId,
    mainCampaignId: refusal.mainCampaignId,
    clientSees,
  });
}

/**
 * Хвост строки лога переноса: сколько компаний из вернувшихся и из положенных
 * этой ночью ждут писем (пометка HE_REFILL_CARRY_HELD_REASON, блок «ПЕРЕНОС»).
 * Пусто — таких не было.
 */
function refillCarryHeldNote(c: NonNullable<HeRefillStats['carryover']>): string {
  if (!c.returned_held && !c.queued_held) return '';
  return (
    '; ждут писем (письмо кампании прочиталось бы неверно; следующие ночи вертикали ' +
    'перепроверят их до срока очереди): ' +
    `из вернувшихся ${c.returned_held ?? 0}, из положенных этой ночью ${c.queued_held ?? 0}`
  );
}

/** Хвост итоговой строки лога прогона про отказавшие сегментные кампании (п. 7 «РАСКЛАДКИ»); пусто — отказов не было. */
function refillSegmentRefusalsNote(stats: HeRefillStats): string {
  const refusals = stats.segment_refusals ?? [];
  if (refusals.length === 0) return '';
  const fateText = {
    main: 'остальные в основную',
    not_sent: 'остальные не отправлены',
    unknown: 'исход остальных неизвестен',
    none: 'остальных нет',
  } as const;
  return (
    ` [отказали сегментные кампании: ${refusals
      .map(
        (r) =>
          `${r.campaign_id} HTTP ${r.http_status}, ${r.leads} лид. (закреплено ${r.pinned}), ${fateText[r.fate]}`,
      )
      .join('; ')}]`
  );
}

/**
 * Как строка журнала прогонов решает серию отказов (refillFailStreak):
 * 'failure' — отказ среза, 'success' — серию обрывает, 'skip' — серию не
 * решает вовсе (ни отказ, ни успех).
 *
 * ВЕСЬ набор состояний строки he_auto_pipeline_runs с base_id:
 *  - 'appended' / 'no_new' → 'success';
 *  - 'failed':
 *      · stats.cancelled — отмена клиентом → 'skip' (решение человека);
 *      · stats.sending_skip — кампании запуска не брали контакты, долив
 *        пропущен до провайдера (шаг 4c) → 'skip': про срез это не говорит;
 *      · stats.budget_outcome 'cap_exhausted' — бюджет проекта не дал базе ни
 *        строки, её компании вне серии ушли в очередь переноса (market='us')
 *        или вернулись в пул → 'skip';
 *      · stats.budget_outcome 'already_reserved' — бронь держал прошлый прогон
 *        той же базы, который мог отправить; итог ночи неизвестен → 'skip';
 *      · остальное → 'failure';
 *  - 'collecting' ЧУЖОЙ базы — строку никто не закрыл: процесс умер между
 *    записью базы и строки, запись строки упала, ремонт воркера сорвался до
 *    своего терминала и закрыл базу прежним 'failed', либо ночь закрыта кодом
 *    до closeHeRefillBaseUndelivered (тогда таймаут конструктора и ремонт
 *    писали базу сами, без строки прогона). Итог ночи тогда — СТАТУС ЕЁ
 *    БАЗЫ:
 *      · 'failed' с текстом отмены → 'skip';
 *      · 'failed' иначе → 'failure' (компании вернулись в пул — ровно тот
 *        случай, ради которого серия заведена);
 *      · 'analyzed' → 'success': компании базы исключены, повторной покупки
 *        этого среза не будет, то есть звеном цикла возвратов ночь не была;
 *      · базы нет или статус другой ('collecting' чужой базы той же
 *        вертикали невозможен — he_bases_one_collecting_per_vertical) → 'skip';
 *  - любой другой статус → 'skip'.
 */
type RefillStreakVerdict = 'failure' | 'success' | 'skip';

function refillStreakVerdict(
  run: { status?: unknown; stats?: unknown },
  base: { status?: unknown; error?: unknown } | undefined,
): RefillStreakVerdict {
  if (run.status === 'appended' || run.status === 'no_new') return 'success';
  if (run.status === 'failed') {
    const stats = (run.stats && typeof run.stats === 'object' ? run.stats : {}) as {
      cancelled?: unknown;
      budget_outcome?: unknown;
      sending_skip?: unknown;
    };
    if (stats.cancelled === true) return 'skip';
    if (typeof stats.sending_skip === 'string') return 'skip';
    if (stats.budget_outcome === 'cap_exhausted' || stats.budget_outcome === 'already_reserved') {
      return 'skip';
    }
    return 'failure';
  }
  if (run.status === 'collecting') {
    if (!base) return 'skip';
    if (base.status === 'analyzed') return 'success';
    if (base.status !== 'failed') return 'skip';
    const text = typeof base.error === 'string' ? base.error.trim().toLowerCase() : '';
    return REFILL_CANCEL_MARKERS.has(text) ? 'skip' : 'failure';
  }
  return 'skip';
}

/**
 * Сколько refill-прогонов этой вертикали упало ПОДРЯД перед текущим.
 *
 * Журнал he_auto_pipeline_runs: строку 'collecting' пишет крон при постановке,
 * финал — эта стадия по base_id. Считаем строки ДРУГИХ баз вертикали (своя
 * сейчас ещё 'collecting'), от свежей к старой, и каждую разбираем
 * refillStreakVerdict: отказ растит серию, успех обрывает, «не решает»
 * пропускается. Строки без base_id — отказы САМОЙ постановки крона (сбора не
 * было), они про срез ничего не говорят и в окно не попадают.
 *
 * Зависшие 'collecting' строки чужих баз раньше отсекались запросом — и это
 * была дыра: ночь, которую закрыл не долив (таймаут конструктора, ремонт
 * воркера, смерть процесса, упавшая запись строки), в серии не значилась вовсе,
 * и каждая следующая выглядела «первым отказом». Теперь такая строка решается
 * по статусу её базы (одно доп. чтение he_bases по id). Порядок — по created_at:
 * у зависшей строки completed_at нет, а created_at есть у всех (у ночной —
 * момент постановки, у вставленной стадией — момент финала).
 *
 * Никогда не бросает: вызывается из catch-ветки долива, где падать нельзя
 * (см. шапку файла), и из closeHeRefillBaseUndelivered. Непрочитанная
 * история = 0, то есть отказ считается
 * разовым и компании возвращаются в пул — из двух исходов это обратимый:
 * вернуть срез можно ещё раз, а выжженный назад не достать.
 *
 * Возвращаемое число ограничено: решение бинарное («серия достигла лимита или
 * нет»), счёт останавливается на LIMIT + 1, а читается не больше
 * REFILL_FAIL_STREAK_WINDOW строк.
 */
async function refillFailStreak(
  ctx: HeStageContext,
  verticalId: string,
  currentBaseId: string,
): Promise<number> {
  try {
    const { data, error } = await ctx.supabase
      .from('he_auto_pipeline_runs')
      .select('base_id, status, stats')
      .eq('vertical_id', verticalId)
      // base_id IS NULL отсекает и сам neq (SQL: NULL <> id → NULL), условие
      // оставлено явным — оно про смысл строки, а не про трёхзначную логику.
      .not('base_id', 'is', null)
      .neq('base_id', currentBaseId)
      .order('created_at', { ascending: false })
      .limit(REFILL_FAIL_STREAK_WINDOW);
    if (error) throw new Error(error.message);
    const runs = (data ?? []) as Array<{ base_id?: unknown; status?: unknown; stats?: unknown }>;

    const staleBaseIds = [
      ...new Set(
        runs
          .filter((run) => run.status === 'collecting' && typeof run.base_id === 'string')
          .map((run) => run.base_id as string),
      ),
    ];
    const baseById = new Map<string, { status?: unknown; error?: unknown }>();
    if (staleBaseIds.length > 0) {
      const { data: bases, error: bErr } = await ctx.supabase
        .from('he_bases')
        .select('id, status, error')
        .in('id', staleBaseIds);
      if (bErr) throw new Error(`he_bases: ${bErr.message}`);
      for (const b of (bases ?? []) as Array<{ id?: unknown; status?: unknown; error?: unknown }>) {
        if (typeof b.id === 'string') baseById.set(b.id, b);
      }
    }

    let streak = 0;
    for (const run of runs) {
      const verdict = refillStreakVerdict(
        run,
        typeof run.base_id === 'string' ? baseById.get(run.base_id) : undefined,
      );
      if (verdict === 'success') break;
      if (verdict === 'skip') continue;
      streak += 1;
      // LIMIT подряд упавших прогонов уже запрещают возврат, +1 отличает
      // «серия ровно на лимите» от «длиннее» в журнале.
      if (streak > REFILL_RELEASE_FAIL_STREAK_LIMIT) break;
    }
    return streak;
  } catch (e) {
    stageLog(
      ctx,
      `[base_collect] refill: he_auto_pipeline_runs серия отказов не прочитана: ` +
        `${e instanceof Error ? e.message : String(e)} — считаем отказ разовым`,
    );
    return 0;
  }
}

interface RefillTemplatePick {
  /** Основная кампания запуска (segment=null) — цель долива по умолчанию. */
  campaignId: string;
  presetId: string;
  /** Шаблон этого запуска — по нему читается пауза клиента (шаг 4c). */
  templateId: string;
  operatorMapping: HeOperatorMapping[] | undefined;
  /**
   * he_templates.letters как есть — письма, из которых запуск собрал кампанию
   * (после вставки шаблона их не переписывает ни один путь). Читают проверка
   * незаполняемых строк (heRefillUnfilledRows) и раскладка по сегментам
   * (routeHeRefillSegments: условия сегментов — из этих же писем).
   */
  letters: unknown;
  /**
   * Сегментные кампании ТОГО ЖЕ запуска (launch_info.campaigns): условие
   * сегмента (when дословно, как его записал запуск) → id кампании. Пусто —
   * запуск не сплитился по сегментам. Читает раскладка строк ночи по сегментам
   * (только market='us', routeHeRefillSegments).
   */
  segmentCampaigns: ReadonlyMap<string, string>;
}

/**
 * Маппинг, по которому долив и перенос строят лидов (mapBaseRowsToLeads). У
 * market='us' — с заменами пустых ячеек по виду колонки (templateOperatorGate,
 * withHeEmptyCellFallbacks; колонки — той базы, чьи строки уходят). Шаблон,
 * записанный до 09.10.2026, хранит маппинг без замен, а запуск кладёт их в
 * памяти (launchTemplate.ts, шаг 4b″): без той же замены строка долива с
 * пустой ячейкой ушла бы в ту же кампанию пустотой («I looked at  and…»). У
 * шаблона, записанного позже, замены уже лежат в маппинге, и вызов ничего не
 * меняет. Место замены в письмах гейт запуска проверял по пустым ячейкам базы
 * запуска (или стадии template); строки долива по этому маппингу проверяет
 * heRefillUnfilledRows ниже. Иной рынок — маппинг как записан.
 */
function heRefillOperatorMapping(
  operatorMapping: HeOperatorMapping[] | undefined,
  columns: string[],
  market: HeMarket | undefined,
): HeOperatorMapping[] | undefined {
  return market === 'us' ? withHeEmptyCellFallbacks(operatorMapping, columns).mapping : operatorMapping;
}

/**
 * Колонки, по которым тик крона заранее сверяет письма (HE_REFILL_BASE_COLUMNS
 * в autoPipeline.ts — копия ради бандла крона), обязаны совпадать с колонками,
 * которые база долива получает на деле: контракт авто-сборки и колонка
 * описаний конструктора. Разойдутся — здесь ошибка типов. Копия без колонки
 * настоящей базы дала бы тику лишние отказы, то есть ночи, не купленные зря.
 */
const _refillBaseColumnsMatch: readonly [...typeof HE_AUTO_COLLECT_COLUMNS, 'description'] = HE_REFILL_BASE_COLUMNS;

/**
 * Строки долива, которым письмо кампании прочиталось бы неверно (только
 * market='us'; вызывающие скоупят). Замены пустых ячеек (heRefillOperatorMapping)
 * есть не у каждого вида колонки: у vacancy_title, phone, address, employees,
 * revenue их нет, и mapBaseRowsToLeads кладёт в переменную `val || fallback ||
 * ''` — пустоту («hiring a  for…»). А там, где замена есть, она может встать
 * туда, где читается неверно (начало предложения, после артикля): гейт запуска
 * проверял её место только по пустым ячейкам БАЗЫ ЗАПУСКА, строк долива он не
 * видел. Поэтому здесь тот же гейт, что у запуска (checkHeTemplateOperators, шаг
 * 4b″ launchTemplate.ts), но по ОТПРАВЛЯЕМЫМ текстам той кампании, куда строка
 * уходит: тема письма 1, тела писем и их вариантов ровно так, как их собирает
 * buildLaunchSequence — без сегмента для основной кампании (шаг 3a, его
 * проходит КАЖДАЯ строка ночи) и с `segmentWhen` для сегментной (раскладка
 * routeHeRefillSegments: строка, которой текст сегмента прочитался бы неверно,
 * уходит в основную кампанию — основной текст она уже прошла).
 *
 * Строка снимается, если в ней пуста колонка, по которой гейт нашёл пустую
 * ячейку без замены или с заменой не на месте (emptyCells): вывод гейта о
 * такой колонке не зависит от того, какая именно строка пуста, — только от
 * текста письма и маппинга. Списки, не зависящие от строк (оператор темы без
 * колонки, оператор без колонки и fallback или с fallback не к месту, битые
 * скобки), снимают ВСЕ строки: запуск такой шаблон отказал бы целиком. У
 * шаблона, прошедшего нынешний гейт стадии и запуска, такое возможно, только
 * если у базы долива нет колонки, которая была у базы запуска; у шаблона,
 * запущенного до него (гейт с тех пор строже), — и по самим письмам.
 * Писем нет (buildLaunchSequence → null; у запущенного шаблона так не бывает) —
 * сверить нечего, и строки тоже снимаются: незнание здесь = не отправлять.
 * Эти два случая (снято всё при любых строках) тик крона проверяет ДО покупки
 * сборки по всем колонкам, какие бывают у базы долива, и такую ночь не ставит
 * (heRefillLettersHoldEveryRow в autoPipeline.ts — по основным текстам); здесь
 * они остаются страховкой на то, чего тик видеть не мог (см.
 * alertRefillLettersHeld). У вызова с `segmentWhen` «снято всё» значит лишь
 * «в кампанию этого сегмента никого»: строки уходят в основную кампанию.
 *
 * Снятая ОСНОВНЫМ текстом строка (шаг 3a) не теряется: она остаётся в
 * he_bases.data своей базы (долив пишет базу целиком), а её компания, если
 * других лидов у неё нет, у market='us' ложится в очередь переноса с пометкой
 * «ждёт писем» (HE_REFILL_CARRY_HELD_REASON, блок «ПЕРЕНОС»). Каждая ночь
 * вертикали прогоняет строки такой компании через этот же отбор заново — по
 * письмам кампании, в которую доливает ЭТА ночь: шаблон переписали и
 * перезапустили — строки проходят и уходят; не переписали — ждут до срока
 * очереди и потом отпускаются в пул. В бронь дневного бюджета и в попытки
 * снятая строка не входит — отбор идёт до чёрного списка. Чистая функция, без
 * запросов и моделей.
 */
function heRefillUnfilledRows(input: {
  letters: unknown;
  columns: string[];
  operatorMapping: HeOperatorMapping[] | undefined;
  rows: ReadonlyArray<Record<string, unknown>>;
  emailColumn: string | null;
  /** Условие сегмента — проверять тексты его кампании; нет — основной. */
  segmentWhen?: string | null;
}): { held: (row: Record<string, unknown>) => boolean; detail: string } {
  const sequence = buildLaunchSequence(
    Array.isArray(input.letters) ? (input.letters as HeChainLetter[]) : null,
    input.segmentWhen ? { segmentWhen: input.segmentWhen } : undefined,
  );
  if (!sequence) return { held: () => true, detail: HE_REFILL_NO_LETTERS_DETAIL };
  const gate = checkHeTemplateOperators({
    letters: sequence.steps,
    columns: input.columns,
    operatorMapping: input.operatorMapping,
    rows: input.rows,
    emailColumn: input.emailColumn,
  });
  if (gate.ok) return { held: () => false, detail: '' };
  const detail = describeHeTemplateOperatorGate(gate, 4);
  if (heTemplateGateHoldsEveryRow(gate)) return { held: () => true, detail };
  const emptyColumns = [...new Set(gate.emptyCells.map((issue) => issue.column))];
  return {
    held: (row) => emptyColumns.some((column) => String(row[column] ?? '').trim() === ''),
    detail,
  };
}

/**
 * Шаблон для долива: среди шаблонов вертикали с launch_info — точное
 * совпадение по campaign_id из collect_info (снапшот постановки), иначе
 * последний по дате запуска (force-перезапуск создаёт НОВУЮ кампанию и
 * перезаписывает launch_info — доливать надо в неё).
 */
export function pickRefillTemplate(
  templates: Array<Record<string, unknown>>,
  preferredCampaignId: string | null,
): RefillTemplatePick | null {
  const launched = templates
    .map((t) => {
      const launch = parseLaunchInfo(t.launch_info);
      if (!launch) return null;
      const plan = t.personalization_plan as { operator_mapping?: HeOperatorMapping[] } | null;
      const ts =
        Date.parse(launch.created_at) ||
        Date.parse(typeof t.created_at === 'string' ? t.created_at : '') ||
        0;
      return {
        launch,
        templateId: typeof t.id === 'string' ? t.id : '',
        operatorMapping: plan?.operator_mapping,
        letters: t.letters,
        ts,
      };
    })
    .filter((t): t is NonNullable<typeof t> => t !== null);
  if (launched.length === 0) return null;

  const toPick = (t: (typeof launched)[number]): RefillTemplatePick | null => {
    // При сплите запуска по сегментам ЦЕЛЬ долива — основная кампания
    // (segment=null): в неё уходят строки без сегмента, без ответа
    // классификатора и без кампании своего сегмента, а у не-'us' — все строки.
    // Сегментные кампании того же запуска берутся вместе с ней: у market='us'
    // строку с сегментом раскладка кладёт в кампанию её сегмента
    // (routeHeRefillSegments). Сплит без основной кампании (все лиды попали в
    // сегменты) → доливать некуда: null — строкам без сегмента негде лечь, и
    // тик крона такую вертикаль тоже пропускает (autoPipeline.ts).
    if (t.launch.campaigns?.length) {
      const main = t.launch.campaigns.find((c) => c.segment === null);
      if (!main) return null;
      // Одна кампания на условие — первая записанная (так же запуск выбирает
      // запись сегмента, recordedBySegment в launchTemplate.ts).
      const segmentCampaigns = new Map<string, string>();
      for (const c of t.launch.campaigns) {
        const when = (c.segment ?? '').trim();
        if (!when || c.campaign_id === main.campaign_id || segmentCampaigns.has(when)) continue;
        segmentCampaigns.set(when, c.campaign_id);
      }
      return {
        campaignId: main.campaign_id,
        presetId: t.launch.preset_id,
        templateId: t.templateId,
        operatorMapping: t.operatorMapping,
        letters: t.letters,
        segmentCampaigns,
      };
    }
    return {
      campaignId: t.launch.campaign_id,
      presetId: t.launch.preset_id,
      templateId: t.templateId,
      operatorMapping: t.operatorMapping,
      letters: t.letters,
      segmentCampaigns: new Map(),
    };
  };

  if (preferredCampaignId) {
    const exact = launched.find(
      (t) =>
        t.launch.campaign_id === preferredCampaignId ||
        (t.launch.campaigns ?? []).some((c) => c.campaign_id === preferredCampaignId),
    );
    if (exact) {
      const picked = toPick(exact);
      if (picked) return picked;
    }
  }
  for (const t of launched.slice().sort((a, b) => b.ts - a.ts)) {
    const picked = toPick(t);
    if (picked) return picked;
  }
  return null;
}

/**
 * Строки-кандидаты в лиды: непустой email И вердикт валидации 'accepted'.
 *
 * Вердикт считает heLaunchEmailVerdict (launchHandoff.ts) — тот же список
 * допущенных статусов, что у ручного запуска шаблона, и тот же разбор
 * регистра/пробелов. Здесь он НЕ переписан осознанно: два пути допуска
 * адресов, которые можно поправить по отдельности, рано или поздно разойдутся,
 * а расхождение видно только по баунсам, то есть уже по репутации доменов.
 * Почему catch_all не допущен — в докблоке HE_LAUNCH_ACCEPTED_EMAIL_STATUSES.
 *
 * 'missing' (вердикта нет вовсе) отклоняется, как и 'rejected', но считается
 * отдельно: ночной долив идёт без человека рядом, и «валидация не доработала»
 * обязано быть видно в воронке, а не выглядеть как «адреса плохие».
 */
export function selectRefillLeadRows(
  rows: HeUnifiedRow[],
  emailStatuses: Array<string | null> | null,
): {
  leadRows: HeUnifiedRow[];
  /**
   * Позиция каждой отобранной строки в ИСХОДНОМ массиве (он же he_bases.data
   * после persistRefillBase). Нужна пометке доставки: лиду проставляется
   * `source_row_id`, и без этого массива запасной индекс был бы
   * номером внутри отфильтрованного среза, то есть указывал бы не на ту строку.
   */
  leadRowIndexes: number[];
  withEmail: number;
  valid: number;
  unverified: number;
} {
  const leadRows: HeUnifiedRow[] = [];
  const leadRowIndexes: number[] = [];
  let withEmail = 0;
  let unverified = 0;
  for (let i = 0; i < rows.length; i += 1) {
    const row = rows[i];
    if (row.email.trim() === '') continue;
    // Строки вне вертикали (релевант-гейт base_collect) в долив не идут.
    if ((row as { _low_relevance?: boolean })._low_relevance === true) continue;
    withEmail += 1;
    const verdict = heLaunchEmailVerdict(emailStatuses?.[i] ?? null);
    if (verdict === 'missing') unverified += 1;
    if (verdict !== 'accepted') continue;
    leadRows.push(row);
    leadRowIndexes.push(i);
  }
  return { leadRows, leadRowIndexes, withEmail, valid: leadRows.length, unverified };
}

/**
 * Какие лиды пачки уезжают, когда бронь дневного бюджета выдала меньше строк,
 * чем есть: отрез по КОМПАНИЯМ правилом ручного запуска
 * (selectLeadsWithinLaunchCap) — сначала по одному адресу каждой компании,
 * потом вторые и т. д.; порядок компаний — порядок строк базы.
 *
 * `kept` — лиды после blocklist'а: тот же объект лида, что в `leads`
 * (filterBlockedLeads фильтрует, не копируя), поэтому строка базы лида
 * находится по позиции в `leads` → `leadSourceRows` (индекс в `leadRows`).
 * Лид, строку которого найти не удалось, считается отдельной компанией —
 * деградация к поштучному отрезу, а не потеря лида.
 *
 * Вердикт внутри компании роли не играет: в долив доходят только допущенные
 * адреса, и порядок адресов компании — порядок её строк.
 */
function selectRefillLeadsByCompany<L extends object>(input: {
  kept: readonly L[];
  leads: readonly L[];
  leadSourceRows: readonly number[];
  leadRows: HeUnifiedRow[];
  columns: string[];
  granted: number;
}): { toSend: L[]; companiesHeldBack: number } {
  const positionOf = new Map<L, number>();
  input.leads.forEach((lead, position) => positionOf.set(lead, position));
  const keptRowIndices = input.kept.map((lead) => {
    const position = positionOf.get(lead);
    return position === undefined ? -1 : input.leadSourceRows[position] ?? -1;
  });
  const selection = selectLeadsWithinLaunchCap({
    rows: input.leadRows,
    columns: input.columns,
    leadRowIndices: keptRowIndices,
    limit: input.granted,
  });
  return {
    toSend: selection.keptLeadPositions.map((position) => input.kept[position]),
    companiesHeldBack: selection.companiesHeldBack,
  };
}

/* ─── РАСКЛАДКА СТРОК НОЧИ ПО СЕГМЕНТНЫМ КАМПАНИЯМ (только market='us') ─────
 *
 * Запуск с сегментными вариантами писем сплитит базу: строки сегмента уходят в
 * кампанию сегмента с его текстом, остальные — в основную (launchTemplate.ts,
 * шаг 5c). До этой правки ночной долив клал КАЖДУЮ новую строку в основную
 * кампанию, и строка, подходящая под сегмент, получала основной текст.
 *
 *  1. ГДЕ. После брони дневного бюджета и отреза по компаниям (шаг 5
 *     runHeRefillAppend) делится уже срезанная пачка `toSend`. Кап считает
 *     СТРОКИ, а не кампании, поэтому раскладка его не умножает: сумма групп —
 *     ровно `toSend`. Классифицируются только строки, которые уходят этой
 *     ночью, — ответы по строкам, которые кап выбросит, не оплачиваются.
 *  2. КТО ПЛАТИТ. Только запуск с сегментными кампаниями (pick.segmentCampaigns,
 *     хотя бы одна под условие из писем) и только market='us'. Запуск без
 *     сегментов — прежний долив: ни чтений, ни вызовов модели.
 *  3. ЧЕМ. Тот же классификатор, что у запуска us-проекта
 *     (classifyBaseRowsIntoSegmentsDetailed: промпт, модель роли gate, батчи
 *     по 40, до 6 параллельно), по тому же списку условий (все when писем,
 *     heRefillSegmentWhens) и по строке базы, из которой вырос лид. Расход —
 *     в usage стадии (he_jobs.cost_usd); каждый HTTP-запрос к модели внутри
 *     джобы воркера журналирует сам llm.ts (журнал расхода ENG, costTelemetry).
 *     Вызов классификатора — один на прогон, своих повторов поверх его
 *     собственных у раскладки нет.
 *  4. КУДА — по вердикту кампании сегмента из шага 4c (segmentVerdicts).
 *     Условие сегмента, чья кампания этого запуска ОТПРАВЛЯЕТ, — в неё.
 *     «Ни одно не подходит» (null), строка без ответа (батч упал, строка не
 *     размечена, условие не из списка), сегмент без своей кампании (его
 *     кампания не создалась — она в pending запуска) и сегмент, чья кампания
 *     ЗАВЕРШЕНА (3), — в ОСНОВНУЮ: основной текст этой строке читается верно
 *     (его проверил шаг 3a), и ровно его долив слал до правки. Классификатор
 *     отказал целиком — вся ночь в основную, строкой лога, без повторной
 *     платной попытки. Сегмент, чья кампания НЕ ОТПРАВЛЯЕТ иначе —
 *     остановлена рассыльщиком (-99/-1/-2), удалена (404), стоит (0/2) или
 *     статус не подтверждён, — свою строку УДЕРЖИВАЕТ (HeRefillRouting.held):
 *     она не уходит никуда, её компания (если другой её адрес не ушёл) ждёт в
 *     очереди переноса, а бронь дня её не списывает. В основную её не
 *     отдаём: та шлёт из тех же ящиков, и это был бы обход остановки
 *     рассыльщика. Алерт команде — у шага 4c. Сбой раскладки или
 *     непрочитанный журнал доставки при такой кампании удерживают ВСЮ пачку:
 *     какие строки её, не знаем.
 *  5. ПИСЬМА СЕГМЕНТА. Шаг 3a проверил основной текст; строка, уходящая в
 *     сегмент, проверяется тем же гейтом по текстам кампании сегмента
 *     (heRefillUnfilledRows с segmentWhen). Не прошла — в основную.
 *  6. ОДИН АДРЕС — ОДНА КАМПАНИЯ.
 *     (а) Внутри прогона решение принимается на АДРЕС (по первому его лиду), и
 *         все лиды с этим адресом уходят в одну кампанию: группы — разбиение
 *         пачки, а не выборки из неё.
 *     (б) Между прогонами: адрес, который общий журнал доставки
 *         (client_campaign_contact_ledger; строку appendLeadsToClientCampaign
 *         пишет ДО запроса к рассыльщику и без неё запрос не делает) уже видел
 *         в кампании ЭТОГО запуска (журнал читается по ВСЕМ его кампаниям,
 *         отправляющим и нет), идёт в ту же кампанию, а не туда, куда его
 *         разложит модель сегодня. Закреплённый за НЕОТПРАВЛЯЮЩЕЙ кампанией
 *         (п. 4, включая завершённую) удерживается и считается возможно
 *         доставленным: ни в основную, ни в перенос — та кампания могла ему
 *         писать. Повторно отправляют строки два пути:
 *         наследник перехваченной брони ('reclaimed') и компании, вернувшиеся в
 *         пул после частичной доставки (ремонт воркера, отмена посреди долива,
 *         см. refillLeadsReachedProvider). В ту же кампанию дубль отсеет
 *         рассыльщик (skipIfInCampaign). Исключение — строка, которой текст
 *         закреплённого сегмента прочитался бы неверно (п. 5): она уходит в
 *         основную; гейт детерминирован по строке, поэтому так бывает, только
 *         если адрес раньше ушёл из ДРУГОЙ строки (общий адрес двух компаний).
 *         Там, как и при непрочитанном журнале, от второго контакта держит
 *         только skipIfInCampaign, который у Instantly работает на весь
 *         воркспейс (докблок clientLaunch/appendLeads.ts) — та же страховка,
 *         что у долива до правки. Строка журнала из партии, которую рассыльщик
 *         отклонил ЯВНО (4xx), адрес не закрепляет: лида в той кампании нет
 *         (readHeRefillLedgerPins, п. 7г).
 *  7. ОТКАЗ СЕГМЕНТНОЙ КАМПАНИИ (шаг 6b runHeRefillAppend). Статус кампаний
 *     долив читает до раскладки (шаг 4c), и неотправляющие сегменты свои
 *     строки держат (п. 4), но кампанию сегмента могли удалить или
 *     заархивировать и после этого чтения: её группа получает явный отказ (404/400 —
 *     refillSegmentCampaignRefusal: 4xx, не 429 и не ёмкость, ни строки не
 *     принято). До раскладки эти строки уходили в основную кампанию и
 *     отправлялись; без этого пункта они читались бы «возможно, доставлены»:
 *     не отправлены, не в переносе, списаны с брони — и так каждую ночь.
 *     (а) Строки группы в ТОМ ЖЕ прогоне уходят в ОСНОВНУЮ кампанию тем же
 *         вызовом (appendGroup), под теми же оградами, что у основной группы:
 *         основной текст каждой строке ночи проверен шагом 3a (гейт писем и
 *         удержание незаполняемых ячеек), владение перепроверяется перед
 *         вызовом и перед каждым чанком, внутри — предполёт ёмкости, чёрный
 *         список, skipIfInCampaign и строка журнала доставки до HTTP-запроса.
 *         Кроме закреплённых за этой кампанией (п. 7г). Итог переотправки
 *         переводится в позиции группы (refillRemapAppendResult), поэтому
 *         бронь, перенос и судьба компаний читают его как отправку группы.
 *     (б) Только если основная кампания подтверждена: этой ночью ответила 2xx
 *         (её группа всегда первая) либо принимала строки в прошлые ночи
 *         (readHeRefillCampaignAccepted). Не подтверждена — строки не
 *         отправляются и считаются явным отказом (refillGroupFailure): не
 *         дошли, с брони не списаны; их компании — в перенос у ночи с
 *         доставкой, по правилу отказа (серия) у ночи без неё.
 *     (в) Повторная отправка отказала явно (4xx, в том числе 429 и ёмкость) —
 *         строки отложены так же. Оборвалась без ответа (сокет, срок, 5xx) —
 *         «могли дойти», как у любой отправки в основную кампанию: списаны с
 *         брони и в перенос не идут, второе письмо дороже потерянного.
 *     (г) Второй цепочки нет. Отказ 4xx этой ночью не создал лида в
 *         сегментной кампании, а адрес группы живёт только в ней (п. 6а) —
 *         основная кампания этой ночью его не получала. Но адрес, ЗАКРЕПЛЁННЫЙ
 *         журналом за этой же кампанией (п. 6б: её прошлая партия), мог
 *         получить письма сегмента в прошлые ночи; кампанию потом удалили, и её
 *         лиды у рассыльщика могли исчезнуть вместе с ней — skipIfInCampaign
 *         такой адрес в основной уже не отсеет. Поэтому закреплённые лиды
 *         группы (HeRefillCampaignGroup.pinned) в основную НЕ переотправляются
 *         и считаются возможно доставленными, как до этой правки: в перенос не
 *         идут, а бронь закрывается по общему правилу (отказ ночи списывает их
 *         как попытку, удачная ночь — только принятое; этой ночью им ничего не
 *         ушло). Закрепление здесь — любая не отказанная явно партия
 *         (принятая, оборванная без ответа, незакрытая): каждая из них могла
 *         создать лида. Следующие ночи: строка журнала от явно отказанной
 *         партии адрес не закрепляет (п. 6б), переотправленный адрес закреплён
 *         за основной кампанией и туда же уйдёт, где дубль отсеет
 *         skipIfInCampaign.
 *     (д) После удачной переотправки (или когда переотправлять нечего — все
 *         лиды закреплены) долив идёт к следующим сегментным кампаниям: отказ
 *         был про одну кампанию, а не про воркспейс. После неудачной ночь
 *         останавливается, как при любом отказе кампании: её хвост не
 *         начинался и читается как не дошедший (перенос).
 *     (е) Видно: stats.segment_refusals (кампания, код ответа, лидов,
 *         закреплённых, итог), строка лога и алерт команде (opsAlert, вид
 *         'segment_refused', окно 6 ч по вертикали) — оба ПОСЛЕ того, как итог
 *         переотправки известен. Следующей ночью шаг 4c читает удалённую
 *         кампанию как 404 ('stopped'), и её строки уже удерживаются (п. 4), а
 *         не переотправляются; текст сегмента не получает никто, пока команда
 *         не вернёт кампанию или не перезапустит шаблон.
 */

/**
 * Строка базы, из которой вырос лид ночи, и то, чем её читали (колонки,
 * маппинг, колонка адреса), — для классификатора и гейта писем сегмента.
 * `sourceKey` различает наборы колонок: свои строки ночи и каждую компанию
 * переноса (у неё колонки её базы-источника).
 */
interface HeRefillLeadSource {
  row: Record<string, unknown>;
  columns: string[];
  operatorMapping: HeOperatorMapping[] | undefined;
  emailColumn: string | null;
  sourceKey: string;
}

/** Кампания долива и её лиды; segment=null — основная кампания. */
interface HeRefillCampaignGroup<L> {
  campaignId: string;
  segment: string | null;
  leads: L[];
  /**
   * Лиды группы, чей адрес журнал доставки уже закрепил за ЭТОЙ кампанией
   * (п. 6б): кампания могла написать им в прошлые ночи. Отказ кампании их в
   * основную не отдаёт — это была бы вторая цепочка писем тому же человеку, —
   * они считаются возможно доставленными (п. 7г). У основной группы пусто.
   */
  pinned: ReadonlySet<L>;
}

/**
 * Условия сегментных вариантов писем — тот же список, по которому запуск
 * классифицировал свою базу (launchTemplate.ts, шаг 4): when каждого
 * segment_variants без пробелов по краям, без пустых и повторов, в порядке писем.
 */
function heRefillSegmentWhens(letters: unknown): string[] {
  if (!Array.isArray(letters)) return [];
  return [
    ...new Set(
      (letters as Array<HeChainLetter | null>).flatMap((letter) =>
        (letter?.segment_variants ?? []).map((v) => (v?.when ?? '').trim()).filter(Boolean),
      ),
    ),
  ];
}

/** Адресов в одном чтении журнала доставки (длина URL фильтра `in`). */
const HE_REFILL_LEDGER_PIN_CHUNK = 50;

/**
 * Куда адреса ночи УЖЕ уходили среди кампаний этого запуска (п. 6б раскладки):
 * адрес → кампания его самой ранней строки журнала доставки клиента (любой
 * статус: 'submitted' пишется до запроса, значит и упавший запрос мог создать
 * лида). Только кампании `campaignIds`; адреса вне их — не закреплены.
 * ИСКЛЮЧЕНИЕ — строка из партии, которую рассыльщик отклонил ЯВНО
 * (readHeRefillRefusedAppendBatches: партия 'failed' с ответом 4xx): лид в той
 * кампании не создан, и закреплять за ней адрес незачем. Главный случай —
 * сегментная кампания, удалённая у рассыльщика: её строки той же ночью ушли в
 * основную (блок «ОТКАЗ СЕГМЕНТНОЙ КАМПАНИИ»), и без этого исключения адрес,
 * вернувшийся в долив, шёл бы снова в мёртвую кампанию — самая ранняя строка
 * журнала у него именно её (журнал неизменяем, статус строки так и остаётся
 * 'submitted'). Партии не прочитаны — исключений нет, закрепление прежнее.
 * Чтение клиентом стадий (после отмены отвергается) и best-effort: null —
 * журнал не прочитан, закреплений нет (строка лога).
 */
async function readHeRefillLedgerPins(
  ctx: HeStageContext,
  args: { ownerUserId: string; campaignIds: readonly string[]; emails: readonly string[] },
): Promise<Map<string, string> | null> {
  const ours = new Set(args.campaignIds);
  const submissions: Array<{ email: string; campaignId: string; at: number; batchId: string | null }> = [];
  try {
    for (const chunk of chunked(args.emails, HE_REFILL_LEDGER_PIN_CHUNK)) {
      const { data, error } = await ctx.supabase
        .from('client_campaign_contact_ledger')
        .select('email, campaign_id, submitted_at, append_batch_id')
        .eq('client_user_id', args.ownerUserId)
        .in('campaign_id', [...ours])
        .in('email', chunk);
      if (error) throw new Error(error.message);
      for (const raw of (data ?? []) as Array<Record<string, unknown>>) {
        const email = typeof raw.email === 'string' ? raw.email.trim().toLowerCase() : '';
        const campaignId = typeof raw.campaign_id === 'string' ? raw.campaign_id : '';
        if (!email || !ours.has(campaignId)) continue;
        const parsed = typeof raw.submitted_at === 'string' ? Date.parse(raw.submitted_at) : Number.NaN;
        const at = Number.isFinite(parsed) ? parsed : Number.MAX_SAFE_INTEGER;
        const batchId = typeof raw.append_batch_id === 'string' && raw.append_batch_id ? raw.append_batch_id : null;
        submissions.push({ email, campaignId, at, batchId });
      }
    }
  } catch (e) {
    stageLog(
      ctx,
      `[base_collect] refill: журнал доставки не прочитан (${e instanceof Error ? e.message : String(e)}) — ` +
        'адреса ночи раскладываются без закрепления за прежней кампанией',
    );
    return null;
  }
  const refused = await readHeRefillRefusedAppendBatches(ctx, [
    ...new Set(submissions.map((s) => s.batchId).filter((id): id is string => id !== null)),
  ]);
  const earliest = new Map<string, { campaignId: string; at: number }>();
  for (const s of submissions) {
    if (s.batchId !== null && refused.has(s.batchId)) continue;
    const seen = earliest.get(s.email);
    if (!seen || s.at < seen.at) earliest.set(s.email, { campaignId: s.campaignId, at: s.at });
  }
  return new Map([...earliest].map(([email, pin]) => [email, pin.campaignId]));
}

/**
 * Партии журнала доставки (client_campaign_append_batches), которые
 * рассыльщик отклонил ЯВНО: статус 'failed' и текст ответа `Instantly API
 * <4xx>: …` (refillProviderRefusalStatus; текст пишет failAppendLedgerBatch из
 * ошибки createLeads). Такой запрос не создал ни одного лида. Обрыв без ответа
 * (сокет, срок), 5xx и незакрытая партия ('submitted' — процесс умер) сюда не
 * входят: там лид мог появиться. Сбой чтения — пустое множество и строка лога:
 * закрепления остаются прежними (лишнее закрепление стоит одного отказанного
 * запроса, а не второго письма).
 */
async function readHeRefillRefusedAppendBatches(
  ctx: HeStageContext,
  batchIds: readonly string[],
): Promise<Set<string>> {
  const out = new Set<string>();
  try {
    for (const chunk of chunked(batchIds, HE_REFILL_LEDGER_PIN_CHUNK)) {
      const { data, error } = await ctx.supabase
        .from('client_campaign_append_batches')
        .select('id, error_message')
        .eq('status', 'failed')
        .in('id', chunk);
      if (error) throw new Error(error.message);
      for (const raw of (data ?? []) as Array<Record<string, unknown>>) {
        const message = typeof raw.error_message === 'string' ? raw.error_message : '';
        if (typeof raw.id === 'string' && refillProviderRefusalStatus(message) !== null) out.add(raw.id);
      }
    }
  } catch (e) {
    stageLog(
      ctx,
      `[base_collect] refill: партии журнала доставки не прочитаны (${e instanceof Error ? e.message : String(e)}) — ` +
        'явно отказанные отправки тоже закрепляют адрес за своей кампанией',
    );
    return new Set();
  }
  return out;
}

/**
 * Принимала ли кампания лидов в прошлые ночи: в журнале доставки есть
 * закрытая ('completed') партия этого клиента в эту кампанию — то есть
 * /leads/add с этим campaign_id получал ответ 2xx (completeAppendLedgerBatch
 * пишется только после него). Читает отказ сегментной кампании, когда
 * основная этой ночью ещё не ответила: это доказательство, что основная
 * кампания у рассыльщика была и принимала строки. Не доказательство, что
 * она жива сейчас: удалённая с тех пор ответит явным отказом, и строки уйдут
 * в перенос (refillGroupFailure). Сбой чтения — false (не знаем — не шлём).
 */
async function readHeRefillCampaignAccepted(
  ctx: HeStageContext,
  args: { ownerUserId: string; campaignId: string },
): Promise<boolean> {
  try {
    const { data, error } = await ctx.supabase
      .from('client_campaign_append_batches')
      .select('id')
      .eq('client_user_id', args.ownerUserId)
      .eq('campaign_id', args.campaignId)
      .eq('status', 'completed')
      .limit(1);
    if (error) throw new Error(error.message);
    return (data ?? []).length > 0;
  } catch (e) {
    stageLog(
      ctx,
      `[base_collect] refill: журнал доставки основной кампании не прочитан ` +
        `(${e instanceof Error ? e.message : String(e)}) — считаем её неподтверждённой`,
    );
    return false;
  }
}

/** Итог раскладки (routeHeRefillSegments): группы на отправку и удержанное (п. 4). */
interface HeRefillRouting<L> {
  groups: Array<HeRefillCampaignGroup<L>>;
  /** Раскладка читала журнал или звала модель — владение перепроверить до отправки. */
  worked: boolean;
  /**
   * Строки, которые этой ночью не уходят НИКУДА: их сегментная кампания не
   * отправляет (п. 4) или закрепила их за собой (п. 6б). Вместе с группами —
   * разбиение пачки.
   */
  held: L[];
  /**
   * Из `held` — закреплённые журналом доставки за неотправляющей кампанией
   * (п. 6б): она могла им писать, поэтому они «возможно доставлены» — не в
   * основную и не в перенос.
   */
  heldPinned: ReadonlySet<L>;
}

/**
 * Разложить пачку ночи по кампаниям запуска — см. блок «РАСКЛАДКА» выше.
 * Вызывающий скоупит market='us'. Всегда возвращает РАЗБИЕНИЕ `leads`:
 * каждый лид ровно в одной группе или в `held`, группы непустые; основная —
 * первой, затем сегменты в порядке условий писем. `segmentCampaigns` — ВСЕ
 * сегментные кампании запуска, `segmentVerdicts` — их вердикты шага 4c (нет
 * вердикта — как «не подтверждена»). `worked` — раскладка читала журнал или
 * звала модель, то есть прошло время и владение надо перепроверить до первой
 * отправки. Не бросает: любой сбой внутри — вся пачка в основную кампанию,
 * а если у запуска есть неотправляющая сегментная кампания — вся пачка
 * удержана (какие строки её, не знаем, а обходить её через основную нельзя).
 */
async function routeHeRefillSegments<L extends { email: string }>(
  ctx: HeStageContext,
  input: {
    leads: readonly L[];
    sourceOf: ReadonlyMap<object, HeRefillLeadSource>;
    mainCampaignId: string;
    segmentCampaigns: ReadonlyMap<string, string>;
    segmentVerdicts: ReadonlyMap<string, HeRefillCampaignVerdictDetail>;
    letters: unknown;
    ownerUserId: string;
    usage: HeUsage;
  },
): Promise<HeRefillRouting<L>> {
  const allMain: HeRefillRouting<L> = {
    groups: [{ campaignId: input.mainCampaignId, segment: null, leads: [...input.leads], pinned: new Set() }],
    worked: false,
    held: [],
    heldPinned: new Set(),
  };
  // Класс сегментной кампании (п. 4): отправляет / завершена / остальное.
  const classOf = (campaignId: string): 'send' | 'done' | 'hold' => {
    const verdict = input.segmentVerdicts.get(campaignId)?.verdict;
    return verdict === 'sending' ? 'send' : verdict === 'completed' ? 'done' : 'hold';
  };
  // ВСЕ сегментные кампании запуска (не основная): закрепления журнала
  // читаются по каждой, и по каждой неотправляющей адрес удерживается (п. 6б).
  const segmentIds = [...new Set(input.segmentCampaigns.values())].filter(
    (id) => id && id !== input.mainCampaignId,
  );
  const notSending = new Set(segmentIds.filter((id) => classOf(id) !== 'send'));
  if (input.leads.length === 0 || segmentIds.length === 0) return allMain;
  /** Сбой раскладки: неотправляющий сегмент есть — удержать всё, нет — основная. */
  const fallback = (): HeRefillRouting<L> =>
    notSending.size > 0
      ? { groups: [], worked: true, held: [...input.leads], heldPinned: new Set() }
      : { ...allMain, worked: true };
  const whens = heRefillSegmentWhens(input.letters);
  // Условия, у которых есть кампания этого запуска (и это не основная): куда
  // строка уходит (отправляет) и где она держится (не отправляет и не
  // завершена). Условие завершённой кампании — как условие без кампании.
  const withCampaign = whens.filter((when) => {
    const id = input.segmentCampaigns.get(when);
    return id !== undefined && id !== input.mainCampaignId;
  });
  const routable = withCampaign.filter((when) => classOf(input.segmentCampaigns.get(when)!) === 'send');
  const holding = withCampaign.filter((when) => classOf(input.segmentCampaigns.get(when)!) === 'hold');
  const routableSet = new Set(routable);
  const holdingSet = new Set(holding);
  const completedWhens = new Set(withCampaign.filter((when) => classOf(input.segmentCampaigns.get(when)!) === 'done'));
  const whenOfCampaign = new Map<string, string>();
  for (const when of routable) {
    const id = input.segmentCampaigns.get(when)!;
    if (!whenOfCampaign.has(id)) whenOfCampaign.set(id, when);
  }
  // Модель нужна, только если строке есть куда уйти или где держаться.
  const classifyNeeded = routable.length > 0 || holding.length > 0;
  const emailOf = (lead: L) => lead.email.trim().toLowerCase();

  try {
    // Адрес → его первый лид: решение принимается на адрес (п. 6а).
    const firstOf = new Map<string, L>();
    for (const lead of input.leads) {
      const email = emailOf(lead);
      if (!firstOf.has(email)) firstOf.set(email, lead);
    }
    /** Адрес → условие сегмента или null (основная кампания). */
    const decided = new Map<string, string | null>();
    const segmentCandidates: Array<{ lead: L; when: string; pinned: boolean; hold: boolean }> = [];
    const toClassify: L[] = [];
    /** Адреса, ушедшие в сегмент ПО ЗАКРЕПЛЕНИЮ журнала (п. 6б, п. 7г). */
    const pinnedToSegment = new Set<string>();
    /** Адреса, удержанные этой ночью (п. 4), и из них закреплённые (п. 6б). */
    const heldEmails = new Set<string>();
    const heldPinnedEmails = new Set<string>();

    // п. 6б: закрепление за кампанией, куда адрес уже уходил, — по ВСЕМ
    // кампаниям запуска, включая неотправляющие.
    const pins = await readHeRefillLedgerPins(ctx, {
      ownerUserId: input.ownerUserId,
      campaignIds: [input.mainCampaignId, ...segmentIds],
      emails: [...firstOf.keys()],
    });
    if (pins === null && notSending.size > 0) {
      // Журнал не прочитан, а неотправляющая кампания есть: адрес, который она
      // уже получила, отсюда не отличить, и в основную он ушёл бы второй
      // цепочкой. Ночь держит всё — компании ждут в очереди переноса.
      stageLog(
        ctx,
        `[base_collect] refill: журнал доставки не прочитан, а сегментных кампаний не отправляет ${notSending.size} — ` +
          `все ${input.leads.length} лид. этой ночью удержаны (их компании — в очередь переноса)`,
      );
      return fallback();
    }
    let pinnedMain = 0;
    for (const [email, lead] of firstOf) {
      const pinned = pins?.get(email);
      if (pinned === undefined) {
        if (classifyNeeded) toClassify.push(lead);
        else decided.set(email, null);
        continue;
      }
      if (notSending.has(pinned)) {
        heldPinnedEmails.add(email);
        continue;
      }
      const when = whenOfCampaign.get(pinned);
      if (when === undefined) {
        decided.set(email, null);
        pinnedMain += 1;
      } else {
        segmentCandidates.push({ lead, when, pinned: true, hold: false });
      }
    }

    // п. 3–4: классификатор по незакреплённым адресам — один вызов на прогон.
    let classified: HeSegmentClassification | null = null;
    if (toClassify.length > 0) {
      try {
        classified = await classifyBaseRowsIntoSegmentsDetailed({
          rows: toClassify.map((lead) => input.sourceOf.get(lead)?.row ?? {}),
          segments: whens,
          language: detectSegmentLanguage(whens),
          log: (msg) => stageLog(ctx, msg),
          unansweredFate: 'main',
        });
        addUsage(input.usage, classified.usage);
      } catch (e) {
        stageLog(
          ctx,
          `[base_collect] refill: классификатор сегментов отказал (${e instanceof Error ? e.message : String(e)}) — ` +
            `${toClassify.length} адр. уходят в основную кампанию, повторной попытки нет`,
        );
      }
    }
    let answeredNone = 0;
    let unanswered = 0;
    let noCampaign = 0;
    let completedToMain = 0;
    toClassify.forEach((lead, index) => {
      const email = emailOf(lead);
      const answer = classified?.assignments.get(index);
      if (answer === undefined) {
        decided.set(email, null);
        unanswered += 1;
      } else if (answer === null) {
        decided.set(email, null);
        answeredNone += 1;
      } else if (routableSet.has(answer) || holdingSet.has(answer)) {
        segmentCandidates.push({ lead, when: answer, pinned: false, hold: holdingSet.has(answer) });
      } else {
        decided.set(email, null);
        if (completedWhens.has(answer)) completedToMain += 1;
        else noCampaign += 1;
      }
    });

    // п. 5: письма сегмента — по паре «сегмент + набор колонок источника».
    // Строка, которой текст сегмента прочитался бы неверно, уходит в основную
    // и у неотправляющего сегмента: туда её отправил бы и отправляющий.
    const gateSets = new Map<
      string,
      Array<{ lead: L; when: string; pinned: boolean; hold: boolean; source: HeRefillLeadSource }>
    >();
    let heldBySegmentText = 0;
    let noSource = 0;
    for (const candidate of segmentCandidates) {
      const source = input.sourceOf.get(candidate.lead);
      if (!source) {
        // Строка лида неизвестна — текст сегмента сверить не по чему: основная.
        // Источник пишется у КАЖДОГО лида ночи (runHeRefillAppend, шаги 3 и
        // 3b), так что это страховка, а не путь.
        decided.set(emailOf(candidate.lead), null);
        noSource += 1;
        continue;
      }
      const key = `${candidate.when}\u0000${source.sourceKey}`;
      const set = gateSets.get(key);
      if (set) set.push({ ...candidate, source });
      else gateSets.set(key, [{ ...candidate, source }]);
    }
    let pinnedSegment = 0;
    let toSegment = 0;
    for (const set of gateSets.values()) {
      const { when, source } = set[0];
      const gate = heRefillUnfilledRows({
        letters: input.letters,
        columns: source.columns,
        operatorMapping: source.operatorMapping,
        rows: set.map((candidate) => candidate.source.row),
        emailColumn: source.emailColumn,
        segmentWhen: when,
      });
      for (const candidate of set) {
        const email = emailOf(candidate.lead);
        if (gate.held(candidate.source.row)) {
          decided.set(email, null);
          heldBySegmentText += 1;
          continue;
        }
        if (candidate.hold) {
          heldEmails.add(email);
          continue;
        }
        decided.set(email, when);
        if (candidate.pinned) {
          pinnedSegment += 1;
          pinnedToSegment.add(email);
        } else {
          toSegment += 1;
        }
      }
    }

    // Разбиение пачки: каждый лид — туда, куда решён его адрес, или в удержанные.
    const mainLeads: L[] = [];
    const byWhen = new Map<string, L[]>();
    const held: L[] = [];
    const heldPinned = new Set<L>();
    for (const lead of input.leads) {
      const email = emailOf(lead);
      if (heldPinnedEmails.has(email)) {
        held.push(lead);
        heldPinned.add(lead);
        continue;
      }
      if (heldEmails.has(email)) {
        held.push(lead);
        continue;
      }
      const when = decided.get(email) ?? null;
      if (when === null) {
        mainLeads.push(lead);
        continue;
      }
      const list = byWhen.get(when);
      if (list) list.push(lead);
      else byWhen.set(when, [lead]);
    }
    const groups: Array<HeRefillCampaignGroup<L>> = [];
    if (mainLeads.length > 0) {
      groups.push({ campaignId: input.mainCampaignId, segment: null, leads: mainLeads, pinned: new Set() });
    }
    for (const when of routable) {
      const list = byWhen.get(when);
      if (list && list.length > 0) {
        groups.push({
          campaignId: input.segmentCampaigns.get(when)!,
          segment: when,
          leads: list,
          pinned: new Set(list.filter((lead) => pinnedToSegment.has(emailOf(lead)))),
        });
      }
    }
    // Страховка разбиения: группы и удержанные обязаны покрыть пачку ровно
    // (иначе кап и позиции попыток разошлись бы с тем, что ушло).
    const covered = groups.reduce((sum, group) => sum + group.leads.length, 0) + held.length;
    if (covered !== input.leads.length) {
      stageLog(
        ctx,
        `[base_collect] refill: раскладка по сегментам не сошлась (${covered} из ${input.leads.length}) — ` +
          (notSending.size > 0
            ? 'вся пачка удержана: у запуска есть неотправляющая сегментная кампания'
            : 'вся пачка уходит в основную кампанию'),
      );
      return fallback();
    }
    const cost = classified?.usage.costUsd ?? 0;
    stageLog(
      ctx,
      `[base_collect] refill: сегменты запуска — адресов ${firstOf.size}: ` +
        `закреплено журналом доставки ${pinnedMain + pinnedSegment + heldPinnedEmails.size} ` +
        `(основная ${pinnedMain}, сегменты ${pinnedSegment}, неотправляющие сегменты ${heldPinnedEmails.size} — ` +
        'не отправляются, возможно доставлены)' +
        (pins === null ? ' [журнал не прочитан]' : '') +
        `, классифицировано ${toClassify.length}` +
        (classified
          ? ` (пачек ${classified.totalBatches}, упало ${classified.failedBatches}, ` +
            `${classified.usage.tokensUsed} tok, $${cost.toFixed(4)}` +
            // Отказ целиком — не повод платить ещё раз: все эти адреса уходят
            // с основным текстом, как до раскладки.
            (classified.totalBatches > 0 && classified.failedBatches === classified.totalBatches
              ? '; классификатор не ответил ни по одной пачке — все в основную, без повтора'
              : '') +
            ')'
          : toClassify.length > 0
            ? ' (классификатор отказал)'
            : '') +
        `, в сегменты ${toSegment}, удержано неотправляющими сегментами ${heldEmails.size} (в очередь переноса); ` +
        `в основную: «ни один сегмент» ${answeredNone}, без ответа ${unanswered}, ` +
        `сегмент без кампании ${noCampaign}, сегмент завершён ${completedToMain}, ` +
        `текст сегмента прочитался бы неверно ${heldBySegmentText}` +
        (noSource > 0 ? `, строка лида не найдена ${noSource}` : '') +
        '. ' +
        `Лидов по кампаниям: ${groups
          .map((group) => `${group.segment === null ? 'основная' : `«${group.segment.slice(0, 60)}»`} ${group.leads.length}`)
          .join(', ') || 'нет'}` +
        (held.length > 0 ? `; удержано ${held.length}` : ''),
    );
    return { groups, worked: true, held, heldPinned };
  } catch (e) {
    stageLog(
      ctx,
      `[base_collect] refill: раскладка по сегментам не удалась (${e instanceof Error ? e.message : String(e)}) — ` +
        (notSending.size > 0
          ? 'вся пачка удержана: у запуска есть неотправляющая сегментная кампания'
          : 'вся пачка уходит в основную кампанию'),
    );
    return fallback();
  }
}

/** Итог долива по нескольким кампаниям до первой отправки — пустой. */
function emptyRefillAppendResult(): AppendLeadsResult {
  return { accepted: 0, skipped: 0, attemptedIndexes: [], acceptedIndexes: [], skippedIndexes: [], identityComplete: true };
}

/**
 * Свести итог очередной кампании (`part`, позиции — в её группе) с итогом
 * предыдущих (`before`) в ОДИН итог по всей пачке ночи: позиции группы
 * сдвигаются на `offset` — её начало в sentBatch. Так долив по нескольким
 * кампаниям читается ниже ровно как один вызов с несколькими чанками: те же
 * attempted/deferred/accepted, тот же capacityBlocked (по любой кампании).
 */
function mergeRefillAppendResults(before: AppendLeadsResult, part: AppendLeadsResult, offset: number): AppendLeadsResult {
  const shift = (indexes: readonly number[]) => indexes.map((index) => index + offset);
  const withDeferred = before.deferredIndexes !== undefined || part.deferredIndexes !== undefined;
  const withCapacity = before.capacityBlocked !== undefined || part.capacityBlocked !== undefined;
  return {
    accepted: before.accepted + part.accepted,
    skipped: before.skipped + part.skipped,
    attemptedIndexes: [...before.attemptedIndexes, ...shift(part.attemptedIndexes)],
    acceptedIndexes:
      before.acceptedIndexes && part.acceptedIndexes
        ? [...before.acceptedIndexes, ...shift(part.acceptedIndexes)]
        : null,
    skippedIndexes: [...(before.skippedIndexes ?? []), ...shift(part.skippedIndexes ?? [])],
    identityComplete: before.identityComplete && part.identityComplete,
    ...(withDeferred
      ? { deferredIndexes: [...(before.deferredIndexes ?? []), ...shift(part.deferredIndexes ?? [])] }
      : {}),
    ...(withCapacity ? { capacityBlocked: before.capacityBlocked === true || part.capacityBlocked === true } : {}),
  };
}

/**
 * Итог вызова по ПОДМНОЖЕСТВУ группы (`positions[i]` — позиция в группе лида i
 * вызова) → итог в позициях группы. Нужен переотправке отказавшей сегментной
 * кампании (блок «РАСКЛАДКА», п. 7): в основную уходят не все лиды группы, а
 * только незакреплённые, и без перевода позиции вызова указывали бы не на те
 * строки пачки. Счётчики (accepted, skipped, флаги) не меняются.
 */
function refillRemapAppendResult(result: AppendLeadsResult, positions: readonly number[]): AppendLeadsResult {
  const at = (indexes: readonly number[]) => indexes.map((index) => positions[index]);
  return {
    ...result,
    attemptedIndexes: at(result.attemptedIndexes),
    acceptedIndexes: result.acceptedIndexes ? at(result.acceptedIndexes) : null,
    ...(result.skippedIndexes ? { skippedIndexes: at(result.skippedIndexes) } : {}),
    ...(result.deferredIndexes ? { deferredIndexes: at(result.deferredIndexes) } : {}),
  };
}

/**
 * Позиции `reached` — «могли дойти до провайдера»: в attemptedIndexes и не в
 * deferredIndexes (refillReachedPositions). Так читаются закреплённые лиды
 * отказавшей сегментной кампании (п. 7г): кампания могла писать им раньше,
 * поэтому их нельзя ни переотправить, ни отпустить в перенос, а бронь держит
 * их, как держала до этой правки.
 */
function refillAddReachedPositions(result: AppendLeadsResult, reached: readonly number[]): AppendLeadsResult {
  if (reached.length === 0) return result;
  const set = new Set(reached);
  return {
    ...result,
    attemptedIndexes: [...new Set([...result.attemptedIndexes, ...reached])].sort((a, b) => a - b),
    ...(result.deferredIndexes ? { deferredIndexes: result.deferredIndexes.filter((index) => !set.has(index)) } : {}),
  };
}

/**
 * Отказ кампании НЕ первой в пачке: снимок частичного приёма по всей пачке
 * (предыдущие кампании + то, что успела эта), с текстом исходной ошибки — по
 * нему catch долива узнаёт 429 и ёмкость (refillRateLimitRefusal,
 * refillCapacityRefusal). Ровно то, что дал бы один вызов, упавший на
 * очередном чанке: AppendLeadsPartialError с текущим итогом. Отказ первой
 * кампании вызывающий бросает как есть — позиции у неё и так от нуля; одно
 * исключение — сегментная кампания во главе пачки (основной группы этой ночью
 * нет), отказавшая явно, чьи строки отдать основной кампании нельзя (блок
 * «ОТКАЗ СЕГМЕНТНОЙ КАМПАНИИ»): она идёт сюда с `offset` 0, ради правила ниже.
 *
 * Одно отличие от одного вызова — ЯВНЫЙ отказ провайдера (4xx, в том числе
 * 429: refillExplicitRefusalStatus) на кампании, которая сама не приняла НИ
 * строки. Правило HEAD (refillLeadsReachedProvider) «429 при нулевом приёме =
 * провайдер не создал ничего» в одном вызове читается по accepted всего
 * вызова; в сводном итоге accepted несёт приём ПРЕДЫДУЩИХ кампаний, и без этой
 * правки попытки отказавшей кампании читались бы как «могли дойти»: её
 * компании — ни отправлены, ни в переносе, ни возвращены, а их строки списаны
 * с брони дня. Поэтому позиции её ОТКАЗАННОГО запроса (refillRefusedAttempts:
 * ушли в транспорт и ответа чанка не получили; сдвинуты на `offset`, как и все
 * её позиции) кладутся в deferredIndexes — то же «явный отказ провайдера,
 * безопасно повторить», что и отказ по ёмкости: их компании идут в перенос
 * (или в пул), а бронь закрывается только принятым. Строки чанка той же
 * кампании, на который провайдер ответил раньше отказа (всё отсеяно как
 * дубли), остаются дошедшими: провайдер их видел. Те же правила читают
 * повторную отправку строк отказавшей сегментной кампании в основную: её
 * явный отказ — тоже «не создано», её обрыв без ответа — «могли дойти», как у
 * любой отправки в основную кампанию. Кампании ПОСЛЕ отказавшей не начинались
 * — их позиций нет в attemptedIndexes, и они уже читаются как не дошедшие.
 */
function refillGroupFailure(e: unknown, before: AppendLeadsResult, offset: number): AppendLeadsPartialError {
  let merged: AppendLeadsResult;
  if (e instanceof AppendLeadsPartialError) {
    merged = mergeRefillAppendResults(before, e.partialResult, offset);
    if (e.partialResult.accepted === 0 && refillExplicitRefusalStatus(e) !== null) {
      const refused = new Set([
        ...(merged.deferredIndexes ?? []),
        ...refillRefusedAttempts(e.partialResult).map((index) => index + offset),
      ]);
      merged = { ...merged, deferredIndexes: [...refused].sort((a, b) => a - b) };
    }
  } else {
    merged = isInstantlyContactCapacityError(e) ? { ...before, capacityBlocked: true } : before;
  }
  return new AppendLeadsPartialError(e instanceof Error ? e.message : String(e), merged);
}

/**
 * Пустой harvest refill-сборки — штатный «no_new»: база в терминальный
 * 'analyzed' (НЕ failed), прогон 'no_new', джоба завершится успешно.
 *
 * Эта запись базы — РАБОТА, а не деньги, и поэтому остаётся на КЛИЕНТЕ СТАДИЙ (в
 * отличие от persistRefillBase ниже). Провайдер здесь не видел ни строки:
 * доливать было нечего, ни один лид не принят, отменять нечего. Её отказ по
 * abort'у стоит повтора сборки — а повтор ночного добора по пустому сегменту
 * штатно упирается в то же «новых компаний нет» и ничего у провайдера не
 * покупает. Расширять освобождение от сигнала на неё значило бы платить
 * размытием границы за то, чего abort не ломает; критерий — у paidCheckpointDb.
 * Строка прогона ниже под освобождение попадает (writeRefillRun), но до неё
 * отвергнутая запись базы всё равно не доходит — и это правильный порядок:
 * прогон 'no_new' без терминальной базы был бы отчётом о том, чего не случилось.
 */
export async function completeHeRefillNoNew(args: {
  ctx: HeStageContext;
  job: HeJob;
  baseId: string;
  verticalId: string;
  info: HeCollectInfo;
  stats: HeCollectInfo['stats'];
}): Promise<HeRefillResult> {
  const { ctx, job, baseId, verticalId, info, stats } = args;
  const refillResult: HeRefillResult = {
    status: 'no_new',
    // Пустой harvest — ещё не показание о сухости: та же пустота бывает у ночи,
    // вставшей по потолку страниц. Признак пишется ЗДЕСЬ, потому что дальше
    // (в строке прогона) задач уже не видно.
    scan_complete: refillScanComplete(info),
    completed_at: new Date().toISOString(),
  };

  const { error } = await ctx.supabase
    .from('he_bases')
    .update({
      status: 'analyzed',
      collect_info: { ...info, stats, refill_result: refillResult },
      updated_at: new Date().toISOString(),
    })
    .eq('id', baseId);
  if (error) throw new Error(`he_bases refill no_new update: ${error.message}`);

  const config = await loadRefillConfig(ctx, job.project_id);
  await writeRefillRun(ctx, {
    configId: config?.id ?? null,
    projectId: job.project_id,
    verticalId,
    baseId,
    result: refillResult,
  });
  stageLog(ctx, '[base_collect] refill: новых компаний нет — прогон no_new, база analyzed');
  return refillResult;
}

/**
 * ОТКАЗ REFILL-БАЗЫ, ЗАКРЫТЫЙ НЕ ВЕТКОЙ ДОЛИВА. Писателей у него два:
 *  - таймаут ожидания конструктора 6 ч (stages/baseCollect.ts, фаза CONSTRUCT);
 *  - ремонт воркера после ФИНАЛЬНОГО фейла base_collect, пока база ещё
 *    'collecting' (worker/hypothesisEngine.ts: repairBaseAfterCollectFinalFail
 *    → closeHeRefillBaseAfterFinalFail в stages/baseCollect.ts).
 * Раньше оба писали базе 'failed' сами, мимо серии отказов, а строку прогона
 * оставляли 'collecting'. Пока общая очередь конструктора забита, каждая ночь
 * поэтому заново покупала тот же возвращённый срез — гейт релевантности и ещё
 * одну джобу конструктора, — и так без предела.
 *
 * Решение о компаниях — то же, что у отказа долива (runHeRefillAppend, п. 5),
 * плюс один исход, которого у долива не бывает (там срез всегда куплен):
 *  - срез не куплен (`slice` = null: ни суда гейта, ни джобы конструктора) →
 *    компании возвращаются, серия не читается. Повторная сборка купит здесь
 *    только бесплатные чтения каталога, а выжечь некупленное — потерять
 *    компании даром;
 *  - срез куплен → refillFailStreak: первый отказ подряд возвращает компании
 *    (база 'failed', как и раньше), со второго база 'analyzed', а строки среза
 *    ложатся в её `data`. Без строк 'analyzed' не исключила бы ничего:
 *    исключение будущих сборок читает именно `data` не-'failed' баз
 *    (loadOtherBaseExclusionKeys), а у собирающейся базы она пуста;
 *  - строк среза не получить (`slice()` бросил) или их ноль → возврат: из двух
 *    ошибок обратимая, как у непрочитанной серии.
 *
 * Запись базы — КЛИЕНТОМ СТАДИИ и с CAS по 'collecting'. Это работа, а не
 * деньги (провайдер строк не получал), и её потеря оставляет базу
 * 'collecting': повтор доходит до того же решения бесплатно. Отмена клиентом,
 * легшая раньше, выигрывает — CAS не перепишет её 'failed'. Строку прогона
 * пишет writeRefillRun со статусом 'failed', и refillStreakVerdict читает её как
 * обычный отказ.
 *
 * Возвращает итог (он же collect_info.refill_result) или null, если базу уже
 * закрыл кто-то другой и CAS ничего не задел — тогда не пишется ничего.
 */
export async function closeHeRefillBaseUndelivered(args: {
  ctx: HeStageContext;
  projectId: string;
  base: { id: string; vertical_id: string };
  /** Причина: he_bases.error у 'failed', refill_result.error и error строки прогона. */
  reason: string;
  /** collect_info базы уже без рабочего состояния (dropCollectWorkState). */
  info: HeCollectInfo;
  /** Воронка сборки, если вызывающий её посчитал. */
  stats?: HeCollectInfo['stats'];
  /** Строки купленного среза — только если серия велит их оставить; null — срез не куплен. */
  slice: (() => Promise<{ rows: HeUnifiedRow[]; columns: string[] }>) | null;
}): Promise<HeRefillResult | null> {
  const { ctx, projectId, base, reason, info, stats, slice } = args;
  /** null — серия решению не понадобилась и не читалась. */
  let failStreak: number | null = null;
  let kept: { rows: HeUnifiedRow[]; columns: string[] } | null = null;
  if (slice) {
    failStreak = await refillFailStreak(ctx, base.vertical_id, base.id);
    if (failStreak >= REFILL_RELEASE_FAIL_STREAK_LIMIT) {
      try {
        const bought = await slice();
        if (bought.rows.length > 0) kept = bought;
      } catch (e) {
        stageLog(
          ctx,
          `[base_collect] refill: строки купленного среза не получены ` +
            `(${e instanceof Error ? e.message : String(e)}) — компании возвращаются в пул`,
        );
      }
    }
  }
  const message = reason.slice(0, 500);
  const refillResult: HeRefillResult = {
    status: 'failed',
    error: message,
    companies_released: kept === null,
    ...(failStreak === null ? {} : { fail_streak: failStreak }),
    completed_at: new Date().toISOString(),
  };
  const collectInfo: HeCollectInfo = { ...info, ...(stats ? { stats } : {}), refill_result: refillResult };
  const now = new Date().toISOString();
  const patch = kept
    ? {
        columns: kept.columns,
        sample_rows: kept.rows.slice(0, SAMPLE_ROWS),
        data: kept.rows,
        row_count: kept.rows.length,
        status: 'analyzed',
        error: null,
        collect_info: collectInfo,
        updated_at: now,
      }
    : { status: 'failed', error: message, collect_info: collectInfo, updated_at: now };
  const { data: landed, error } = await ctx.supabase
    .from('he_bases')
    .update(patch)
    .eq('id', base.id)
    .eq('status', 'collecting')
    .select('id');
  if (error) throw new Error(`he_bases refill close: ${error.message}`);
  if (!landed || landed.length === 0) {
    stageLog(ctx, `[base_collect] refill: база ${base.id} уже не 'collecting' — её закрыли без нас, решение не пишем`);
    return null;
  }
  const config = await loadRefillConfig(ctx, projectId);
  await writeRefillRun(ctx, {
    configId: config?.id ?? null,
    projectId,
    verticalId: base.vertical_id,
    baseId: base.id,
    result: refillResult,
  });
  stageLog(
    ctx,
    `[base_collect] refill failed до долива: ${message} — ` +
      (kept
        ? `отказ ${(failStreak ?? 0) + 1}-й подряд, компании остаются исключёнными ` +
          `(база analyzed, ${kept.rows.length} строк): иначе ночной прогон собрал бы тот же срез заново`
        : failStreak === null
          ? 'срез не куплен, база failed (компании в пул)'
          : failStreak < REFILL_RELEASE_FAIL_STREAK_LIMIT
            ? 'первый отказ подряд, база failed (компании в пул)'
            : 'строк среза нет, база failed (компании в пул)'),
  );
  return refillResult;
}

/**
 * Потолок замера skipIfInCampaign (шаг 4b) в ЗАПРОСАХ к провайдеру за прогон.
 *
 * ПО УМОЛЧАНИЮ ЗАМЕР ВЫКЛЮЧЕН (0), и это не осторожность, а правило: лимитер
 * Instantly общий на весь воркспейс (~10–15 RPM, lib/instantly/rateLimiter.ts),
 * в котором ЖИВАЯ RU-рассылка отправляет письма за деньги. Измерение не имеет
 * права занимать её минуты само по себе — включать его должен человек, который
 * в этот момент собирается принять решение по флагу. Цена включённого замера
 * названа числом: ≤ 30 запросов на ПРОГОН, то есть ≤ 30 × verticals_per_run за
 * ночь (при дефолтных трёх вертикалях — до 90 запросов, 6–9 минут общего
 * лимитера); выключенного — ноль запросов и ни одного ключа в воронке.
 *
 * Как включить на несколько ночей: HE_REFILL_SKIP_PROBE_REQUESTS=30 в env
 * воркера. Замер выдержит любое число до HE_REFILL_SKIP_PROBE_MAX, но тридцати
 * адресов хватает на решение, ради которого он заводится: «половина пачки
 * занята соседями» и «не занят никто» на такой выборке различаются с запасом;
 * бухгалтерией замер не является и не притворяется. Пустая строка и 0 —
 * выключено.
 */
const HE_REFILL_SKIP_PROBE_DEFAULT = 0;
/** Потолок на случай опечатки в переменной окружения (пачка ночи и так ≤ 200). */
const HE_REFILL_SKIP_PROBE_MAX = 200;

function refillSkipProbeBudget(): number {
  const raw = process.env.HE_REFILL_SKIP_PROBE_REQUESTS;
  if (raw === undefined || raw.trim() === '') return HE_REFILL_SKIP_PROBE_DEFAULT;
  const value = Number(raw);
  if (!Number.isFinite(value) || value <= 0) return 0;
  return Math.min(Math.floor(value), HE_REFILL_SKIP_PROBE_MAX);
}

/**
 * Выборка адресов для замера: РАВНОМЕРНО по пачке, а не первые N.
 *
 * Пачка упорядочена сборкой (компании идут группами, у компании — её адреса),
 * поэтому первые N — это первые компании среза, а не срез. Шаг по всей длине
 * даёт выборку, по которой можно судить о пачке; случайности здесь нет
 * намеренно — прогон должен воспроизводиться по тем же данным.
 */
function refillSkipProbeSample(leads: readonly { email: string }[], budget: number): string[] {
  if (budget <= 0 || leads.length === 0) return [];
  if (leads.length <= budget) return leads.map((lead) => lead.email);
  const step = leads.length / budget;
  const out: string[] = [];
  for (let i = 0; i < budget; i += 1) out.push(leads[Math.floor(i * step)].email);
  return out;
}

/**
 * Шаг 4b: СКОЛЬКО контактов пачки прячет флаг skipIfInCampaign и на каком
 * основании. Подробности значения полей — у HeRefillSkipProbe.
 *
 * Никогда не бросает и ничего не меняет: замер не имеет права уронить ночь,
 * ради которой уже оплачены краул и SMTP-пробы. Любой отказ (нет кампании, нет
 * доступа к провайдеру, сорванный запрос) — это просто отсутствие ключа
 * `skip_probe` или его `undecided`, и долив идёт дальше ровно как без замера.
 *
 * Стоит ПЕРЕД бронью дневного бюджета: замер — чтение, а бронь держит объём
 * проекта до конца UTC-суток, и расширять её окно минутами чтения нельзя.
 * Поэтому мерится `kept` (пачка после blocklist'а), а не `toSend` (после
 * дневного капа): для вопроса «лежат ли эти адреса в чужих кампаниях» это та
 * же популяция, зато бронь остаётся такой же короткой, как была.
 */
async function measureRefillSkipExposure(
  ctx: HeStageContext,
  args: { leads: readonly { email: string }[]; ownerUserId: string; campaignId: string },
): Promise<HeRefillSkipProbe | undefined> {
  const budget = refillSkipProbeBudget();
  if (budget <= 0 || args.leads.length === 0 || !args.campaignId) return undefined;
  try {
    // Тот же резолв аккаунта, что у долива (пресет владельца кампании): читать
    // надо В ТОТ воркспейс, в который грузим, иначе замер расскажет про чужой.
    const requestOptions = await resolveClientInstantlyRequestOptions(args.ownerUserId);
    const probe = await probeLeadPresence({
      emails: refillSkipProbeSample(args.leads, budget),
      ownCampaignId: args.campaignId,
      requestBudget: budget,
      // Срок на весь замер. Число запросов само по себе времени не ограничивает:
      // медленный провайдер растянет тридцать чтений на сколько угодно, а долив
      // ждать не должен. Две минуты — потолок, после которого замер отдаёт ночь.
      budgetMs: 120_000,
      requestOptions: {
        ...requestOptions,
        // Замер виден в почасовых счётчиках отдельной строкой: его цена — это
        // запросы, отнятые у общего лимита воркспейса, и она обязана быть
        // видимой ДО того, как кто-то решит поднять бюджет.
        consumer: 'he_refill_skip_probe',
        timeoutMs: 20_000,
        timeoutIncludesBody: true,
        // Замер УСТУПАЕТ дорогу. Пересиживать 429 внутри клиента (4+8+16 с) он
        // не имеет права: воркспейс общий с RU-контурами, и если провайдер уже
        // говорит «слишком часто», правильный ответ измерения — прекратиться,
        // а не встать в очередь впереди работы. Отказ здесь просто обрывает
        // замер (см. probeLeadPresence), долив идёт дальше.
        retryRateLimits: false,
      },
      // Признак жизни сторожу простоя стадии: замер идёт по HTTP мимо
      // ctx.supabase, и без этого хука десятки запросов выглядели бы молчанием.
      onRequest: () => ctx.onActivity?.(),
      // Отменённая (или прерванная сторожем) джоба замер прекращает сразу:
      // доедать общий лимит воркспейса ради числа, которого никто не прочтёт,
      // нельзя. Сам долив на этом не падает — прерывание он встретит на
      // следующем чтении клиентом стадий, как и до правки.
      shouldStop: () => ctx.signal?.aborted === true,
    });
    if (probe.probed === 0) return undefined;
    return {
      probed: probe.probed,
      of: args.leads.length,
      already_in_our_campaign: probe.counts.own_campaign,
      in_other_campaign: probe.counts.other_campaign,
      in_workspace_no_campaign: probe.counts.no_campaign,
      absent: probe.counts.absent,
      undecided: probe.counts.undecided,
      requests: probe.requests,
      stopped_early: probe.stoppedEarly,
    };
  } catch (e) {
    stageLog(
      ctx,
      `[base_collect] refill: замер skipIfInCampaign не состоялся — ` +
        `${e instanceof Error ? e.message : String(e)} (на долив не влияет)`,
    );
    return undefined;
  }
}

/* ─── ПЕРЕНОС НЕОТПРАВЛЕННЫХ КОМПАНИЙ ─────────────────────────────────────
 *
 * Решение владельца 04.10.2026: компании, которым ночь не отправила ни одного
 * письма, не выбрасываются. Только market='us' — ночной долив и так бывает
 * только у него, но каждое место ниже проверяет рынок само, и RU-инструмент
 * этот код не исполняет ни в одной ветке.
 *
 * ПОЧЕМУ ПЕРЕНОС, А НЕ ВОЗВРАТ В ПУЛ. Возврат (компания перестаёт исключаться,
 * следующая сборка готовит её заново) покупал бы подготовку второй раз: гейт
 * релевантности — платный вызов модели на каждые 50 строк, краул сайта и
 * SMTP-проба — трафик прокси и время воркера, плюс место в общей очереди
 * конструктора. При дефолтах (кап 50 строк, пол сборки 100 компаний, оценка
 * HE_REFILL_ACCEPTED_PER_COMPANY = 2 допущенных адреса на компанию) ночь
 * отправляет первые адреса 50 компаний и оставляет без письма остальные 50:
 * возврат — это 100 подготовленных компаний на 50 охваченных КАЖДУЮ ночь (как
 * и сегодня, только без потери), перенос — 100 подготовленных на 100
 * охваченных за две ночи, потому что вторая ночь отправляет очередь и сборку
 * не покупает. Перенос безопасен: строки очереди хранят адрес, вердикт
 * валидации и всё, что нужно маппингу в лиды, а сама компания всё это время
 * лежит в `data` своей базы и исключена из новых сборок — подготовить её
 * второй раз некому.
 *
 * ЖИЗНЕННЫЙ ЦИКЛ строки he_refill_carryover (миграция 20261004_0001):
 *  1. КЛАДЁТ ночь вертикали собственные компании, у которых ни один лид не
 *     дошёл до провайдера и либо после чёрного списка остался хоть один лид,
 *     либо хоть один лид снят отбором писем (шаг 3a; решение владельца
 *     10.10.2026) — ownUnsentRefillCompanies. Компания, у которой лидов после
 *     чёрного списка нет, а есть только снятые письмами, ложится с пометкой
 *     «ждёт писем» (settle_reason = HE_REFILL_CARRY_HELD_REASON у 'pending').
 *     Помеченная живёт как любая 'pending': тот же срок, тот же отпуск в пул по
 *     сроку, то же исключение из сборок, та же сверка с параллельными базами и
 *     тот же захват — отличается она только тем, что не считается очередью,
 *     закрывающей день (шаг 2). ИСХОДЫ НОЧИ — ВЕСЬ НАБОР:
 *       · 'appended' — кладёт: их срезал кап, провайдер отказал по ёмкости,
 *         отправка до них не дошла. Пишет ПОСЛЕ терминальной записи базы;
 *       · отказ ПОСЛЕ доставки (delivered: принято > 0, попытка без явного
 *         отказа или сбой записи после приёма) — кладёт так же: база и так
 *         'analyzed', а компании, до которых отправка не дошла, иначе остались
 *         бы исключёнными навсегда. Пишет ПОСЛЕ терминальной записи базы.
 *         Отменённый клиентом прогон не кладёт (ни здесь, ни ниже): его
 *         компании решает прежнее правило;
 *       · отказ 'cap_exhausted' (бюджет дня не дал ни строки) — кладёт ВСЕ
 *         свои компании с лидом (и с лидом, снятым письмами), и база
 *         становится 'analyzed', а не 'failed' (решение владельца 04.10.2026).
 *         Пишет ДО терминальной записи базы, одним запросом: не легла очередь
 *         — база 'failed', прежний возврат в пул, то есть хуже, чем до
 *         переноса, не бывает;
 *       · отказ 'already_reserved' — НЕ кладёт и не возвращает: прошлый прогон
 *         этой же базы мог отправить её компании, и любая повторная отправка
 *         могла бы стать вторым письмом;
 *       · отказ, не дошедший до провайдера по другой причине (сбой долива, 429,
 *         ёмкость при нулевом приёме, отмена клиентом), — НЕ кладёт: компании
 *         решает прежнее правило возврата (первый отказ подряд — в пул, со
 *         второго — исключены, отмена — в пул).
 *     Компания, чей крючок найма не доживёт до отправки свежим, не ждёт, а
 *     сразу отпускается в пул ('released', см. heRefillCarryExpiry).
 *  2. СЧИТАЕТ следующая ночь вертикали на тике плана
 *     (resolveHeRefillCollectCompanies): компаний очереди хватает на остаток
 *     дня — сборку не покупает. Тик крона (autoPipeline.ts) той же арифметикой
 *     по проекту не ставит сборку вертикалям без очереди, пока день покрывают
 *     очереди вертикалей, чья ночь этим тиком действительно поставлена
 *     (застрявшая в сборке вертикаль день не закрывает). Помеченные «ждёт
 *     писем» не считает НИ ОДИН из двух (countHeRefillCarryover с
 *     sendableOnly и readCarryoverByVertical — оба по settle_reason IS NULL):
 *     письмо, которое вчера прочиталось бы у них неверно, при тех же письмах
 *     сегодня тоже не уйдёт, и ночь, рассчитавшая на них день, не отправила бы
 *     ничего, а проект не купил бы сборку ни одной вертикали — до 7 суток
 *     подряд. Покупка сборки поэтому ровно та же, что до того, как такие
 *     компании стали попадать в очередь. Пустой харвест — отдельный путь: там
 *     долив идёт, если в очереди есть ХОТЬ ЧТО-ТО, помеченные тоже
 *     (countHeRefillCarryover без флага, stages/baseCollect.ts), иначе у сухой
 *     вертикали их бы никто не перепроверял.
 *  3. БЕРЁТ ночь вертикали в доливе (claimHeRefillCarryover): 'pending' →
 *     'claimed' с id своей базы — до HE_REFILL_CARRYOVER_CLAIM_MAX компаний,
 *     сначала непомеченные (их и считал шаг 2), потом помеченные «ждёт
 *     писем», внутри каждой группы — по дате подготовки. Конкурентов нет:
 *     собирающаяся база у вертикали одна
 *     (he_bases_one_collecting_per_vertical), поэтому чужой 'claimed' —
 *     всегда брошенный (его ночь умерла до записи итога) и уходит в 'dropped':
 *     был ли он отправлен, неизвестно, а второе письмо дороже потерянной
 *     компании. Перед захватом компания сверяется с ПАРАЛЛЕЛЬНЫМИ базами
 *     проекта (heRefillCarryPeerConflicts): сборки разных вертикалей одной ночи
 *     не видят строк друг друга (у собирающейся базы `data` пуст), и одна
 *     компания может оказаться в двух базах. Её копия в чужой базе, которая
 *     могла уйти письмом, снимает нашу ('prepared_elsewhere'); из двух копий в
 *     очереди остаётся одна — базы с меньшим id.
 *  4. ОТПРАВЛЯЕТ тем же путём, что и свои строки: вердикт перепроверяется
 *     (selectRefillLeadRows → heLaunchEmailVerdict, отправляется только
 *     'accepted'), отбор писем (шаг 3a — по письмам кампании, в которую
 *     доливает ЭТА ночь, то есть после перезапуска шаблона — по новым),
 *     чёрный список, бронь дня, отрез по компаниям — перенесённые компании
 *     стоят в пачке ПЕРВЫМИ, поэтому их первые адреса идут раньше первых
 *     адресов новых компаний. Лид, снятый отбором писем, в пачку не идёт,
 *     брони дня не просит и попыткой не считается.
 *  5. ЗАКРЫВАЕТ (settleHeRefillCarryover) по тому, что известно о пачке:
 *     адрес дошёл до провайдера (или мог дойти) → 'sent'; не дошёл → обратно
 *     'pending' со СТАРЫМ сроком — с пометкой «ждёт писем», если после
 *     чёрного списка у компании не осталось лида, а снятый письмами есть, без
 *     пометки, если лид остался (ночь, упавшая до чёрного списка, пометку не
 *     трогает); отправлять нечего (всё в чёрном списке, снятых письмами нет)
 *     или судьба неизвестна (бронь держал прошлый прогон этой же базы) →
 *     'dropped'.
 *  6. СРОК — HE_REFILL_CARRYOVER_MAX_AGE_DAYS от подготовки, а у компании с
 *     крючком найма — не позже момента, когда фид последний раз видел её
 *     вакансию, плюс ENG_HIRING_FEED_FRESH_DAYS (heRefillCarryExpiry). Истёкшая
 *     'pending' не предлагается и считается отпущенной ('released'):
 *     исключение сборок перестаёт её видеть (loadHeRefillReleasedCompanies,
 *     читает stages/baseCollect.ts), и компанию можно подготовить заново. В
 *     'released' уходит только то, что НИ РАЗУ не дошло до провайдера, —
 *     второго письма этот путь не даёт.
 *
 * ПОЧЕМУ КОМПАНИЯ ОЧЕРЕДИ НЕ ЛЕЖИТ В ПУЛЕ. Пул — это то, что может собрать
 * следующая сборка, а исключение сборок (loadOtherBaseExclusionKeys) читает
 * `data` каждой не-'failed' базы проекта. Строка очереди живёт, только пока
 * её база-источник не 'failed' (иначе захват снимает её в 'dropped'), а
 * пропуск исключения (loadHeRefillReleasedCompanies) даётся ровно паре «база +
 * компания» и ровно отпущенной строке ('released' или 'pending' с прошедшим
 * сроком), которую захват уже не предложит: граница срока у обоих одна —
 * `expires_at <= now`. То есть в каждый момент компания либо в очереди, либо
 * в пуле, но не там и там сразу.
 *
 * ЧТЕНИЯ — клиентом стадий и best-effort: не прочиталось — очереди нет, то
 * есть поведение до переноса. ЗАПИСИ итога и очереди — клиентом без сигнала
 * (paidCheckpointDb): итог фиксирует то, что провайдер уже принял, а очередь —
 * оплаченную подготовку, которую повтор джобы не воспроизведёт (база ночи к
 * этому моменту терминальна, и стадия на ней больше не запустится). Потеря
 * любой из них стоит не больше, чем стоило до переноса: незаписанная очередь —
 * компании остаются исключёнными (у ночи без бюджета — возвращаются в пул),
 * незаписанный итог — захват станет брошенным и уйдёт в 'dropped'. Второго
 * письма не даёт ни одна.
 */

/**
 * Сколько суток перенесённая компания ждёт отправки, считая от подготовки.
 *
 * В норме очередь пустеет за одну-две ночи (ночь, которой хватает очереди,
 * отправляет только её), и дольше она живёт, только когда отправка стоит:
 * пауза по ёмкости до снятия сотрудником, снятая кампания, отказы подряд.
 * Неделя покрывает такой простой вместе с выходными. Дольше держать нельзя из-за
 * свежести: вердикт SMTP-пробы стареет медленно, а крючок «hiring X» из ленты
 * найма — быстрее, поэтому у компании с таким крючком срок ещё короче (см.
 * heRefillCarryExpiry). После срока — шаг 6 блока выше.
 */
export const HE_REFILL_CARRYOVER_MAX_AGE_DAYS = 7;

const DAY_MS = 86_400_000;

/**
 * Пометка «ждёт писем» у строки очереди: settle_reason у 'pending' (и у
 * 'claimed', которую из неё взяли — захват колонку не трогает). Компания
 * ждёт не бюджета, а писем: каждый её лид, не снятый чёрным списком, отбор
 * писем кампании (шаг 3a, heRefillUnfilledRows) снял на последней ночи,
 * которая её проверяла. Решение владельца 10.10.2026: такие компании — в
 * очередь переноса, а не в 'analyzed'-базу, куда никто не возвращается.
 *
 * У 'pending'/'claimed' в settle_reason бывает ровно два значения: NULL и эта
 * пометка (обе пишутся только в этом файле — planHeRefillCarryQueue и
 * settleHeRefillCarryover); итоговые статусы пишут свою причину поверх. Поэтому
 * «не помечена» читается как `settle_reason IS NULL` — так её читают оба
 * счёта, закрывающих день (countHeRefillCarryover с sendableOnly и тик крона,
 * readCarryoverByVertical в autoPipeline.ts). Миграция не нужна: колонка без
 * CHECK, а срок, отпуск в пул, исключение из сборок, сверка с параллельными
 * базами и захват у помеченной строки те же, что у любой 'pending'.
 */
const HE_REFILL_CARRY_HELD_REASON = 'letters_unfilled';

/**
 * Срок строки очереди (шаг 6 блока «ПЕРЕНОС») — по ВСЕМУ набору форм строк
 * компании. Чистая функция.
 *
 * Решение владельца 04.10.2026: вакансия в письме не старше окна
 * ENG_HIRING_FEED_FRESH_DAYS (14 суток). Крючок найма — непустая ячейка
 * `vacancy_title`: именно она уезжает в переменную письма, и у market='us' её
 * даёт только фид найма (mapEngHiringRow). Без границы компания, собранная с
 * вакансией, виденной 14 суток назад, ждала бы в очереди ещё до 7 суток, и
 * крючок доезжал бы до письма в возрасте до 21 суток.
 *  - крючка нет ни у одной строки → обычный срок: подготовка + 7 суток;
 *  - у каждой строки с крючком есть `_hiring_seen_at` → срок = минимум из
 *    обычного и `_hiring_seen_at` + окно;
 *  - хоть у одной строки с крючком даты нет (база собрана до этой правки или
 *    дата не пережила сетку конструктора) → возраст крючка неизвестен, и
 *    компания НЕ ПЕРЕНОСИТСЯ, а сразу отпускается в пул
 *    ('hiring_post_age_unknown'). Почему не «снять крючок и перенести»:
 *    переменная письма опустела бы или ушла бы в фолбэк, а текст шаблона
 *    вертикали, собранной по найму, может говорить о найме и без переменной —
 *    письмо утверждало бы то, что мы больше не можем проверить. Почему не
 *    «оставить исключённой»: это и есть выброшенная компания, которую владелец
 *    запретил. В пуле её снова найдёт следующая сборка, и фид пропустит её
 *    только со свежей вакансией;
 *  - граница уже прошла к моменту записи → тоже сразу в пул
 *    ('hiring_post_stale'). Граница в будущем, но раньше обычного срока —
 *    строка ждёт до неё, а дальше её отпускает захват, как любую истёкшую.
 */
export function heRefillCarryExpiry(
  rows: ReadonlyArray<HeUnifiedRow & HeHiringSeenRow>,
  preparedAtMs: number,
): { expiresAtMs: number; release: null | 'hiring_post_age_unknown' | 'hiring_post_stale' } {
  let expiresAtMs = preparedAtMs + HE_REFILL_CARRYOVER_MAX_AGE_DAYS * DAY_MS;
  for (const row of rows) {
    if (String(row.vacancy_title ?? '').trim() === '') continue;
    const seenMs = typeof row._hiring_seen_at === 'string' ? Date.parse(row._hiring_seen_at) : NaN;
    if (!Number.isFinite(seenMs)) return { expiresAtMs: preparedAtMs, release: 'hiring_post_age_unknown' };
    expiresAtMs = Math.min(expiresAtMs, seenMs + ENG_HIRING_FEED_FRESH_DAYS * DAY_MS);
  }
  if (expiresAtMs <= preparedAtMs) return { expiresAtMs, release: 'hiring_post_stale' };
  return { expiresAtMs, release: null };
}

/** Потолок компаний, которые ночь берёт из очереди за раз (предохранитель). */
const HE_REFILL_CARRYOVER_CLAIM_MAX = 500;

/**
 * Сколько id уходит в один фильтр `in(...)`: PATCH адресуется строкой запроса,
 * и 500 uuid в ней — это 18 КБ URL, больше буфера заголовков шлюза.
 */
const HE_REFILL_CARRYOVER_ID_CHUNK = 50;

/**
 * Строк очереди на одну страницу чтения, которому нужен ВЕСЬ набор (отпущенные
 * компании проекта, состояния копий параллельных баз). Один запрос PostgREST
 * отдаёт не больше своего потолка строк (db-max-rows; у Supabase по умолчанию
 * 1000), и хвост сверх него молча пропадал бы. Страница не больше этого потолка,
 * а конец набора — ПУСТАЯ страница, а не короткая: так чтение верно при любом
 * потолке сервера, в том числе ниже этой константы.
 */
const HE_REFILL_CARRYOVER_READ_PAGE = 1000;

/**
 * Предохранитель числа страниц одного такого чтения: миллион строк очереди у
 * одного проекта — это десятки лет ночей, то есть сбой, а не данные.
 */
const HE_REFILL_CARRYOVER_READ_MAX_PAGES = 1000;

/**
 * Прочитать набор строк he_refill_carryover целиком, страницами по `id`
 * (keyset: `id > последний прочитанный`, порядок по `id`). `page` строит
 * запрос одной страницы: фильтры набора + `.gt('id', after)` при `after` +
 * `.order('id').limit(HE_REFILL_CARRYOVER_READ_PAGE)`. Каждая строка обязана
 * нести `id`.
 *
 * Бросает (`label: причина`) на сбое любой страницы, на ключе, который не
 * растёт, и на превышении предохранителя — полнабора не отдаёт. У каждого
 * читателя бросок ведёт в его безопасный исход: сверка копий не берёт очередь
 * этой ночью (компании ждут), отпущенные компании остаются исключёнными до
 * следующей сборки. Полнабора у сверки копий был бы хуже броска: недочитанная
 * копия читается как «могла уйти письмом», и наша терялась бы навсегда.
 */
async function readHeRefillCarryPages(
  label: string,
  page: (afterId: string | null) => PromiseLike<{ data: unknown; error: { message: string } | null }>,
): Promise<Array<Record<string, unknown>>> {
  const out: Array<Record<string, unknown>> = [];
  let after: string | null = null;
  for (let n = 0; n < HE_REFILL_CARRYOVER_READ_MAX_PAGES; n += 1) {
    const { data, error } = await page(after);
    if (error) throw new Error(`${label}: ${error.message}`);
    const rows = (Array.isArray(data) ? data : []) as Array<Record<string, unknown>>;
    if (rows.length === 0) return out;
    out.push(...rows);
    const last = rows[rows.length - 1].id;
    if (typeof last !== 'string' || (after !== null && last <= after)) {
      throw new Error(`${label}: страница не продвинула ключ id`);
    }
    after = last;
  }
  throw new Error(`${label}: больше ${HE_REFILL_CARRYOVER_READ_MAX_PAGES} страниц`);
}

/**
 * Строка очереди — строка базы с вердиктом, пометкой гейта и датой последнего
 * показа вакансии фидом найма, как в he_bases.data.
 */
type HeRefillCarryRow = HeUnifiedRow & HeHiringSeenRow & { _email_status?: string; _low_relevance?: boolean };

/** Перенесённая компания, взятая ночью на отправку. */
interface HeRefillCarryCompany {
  id: string;
  sourceBaseId: string;
  companyKey: string;
  rows: HeRefillCarryRow[];
  columns: string[];
}

function chunked<T>(items: readonly T[], size: number): T[][] {
  const out: T[][] = [];
  for (let i = 0; i < items.length; i += size) out.push(items.slice(i, i + size));
  return out;
}

/**
 * Ключ компании очереди — ТОТ ЖЕ, по которому отрез капа решает «у компании нет
 * письма» (selectLeadsWithinLaunchCap: heLaunchCompanyKey по колонкам компании
 * и сайта). Ключ, расходящийся с отрезом, однажды назвал бы «неохваченной»
 * компанию, которой письмо ушло. Колонки ключа считаются один раз на набор
 * колонок: исключение сборок зовёт ключ на каждой строке каждой базы проекта.
 */
export function heRefillCarryKeyFn(columns: readonly string[]): (row: Record<string, unknown>) => string {
  const cols = findCompanyKeyColumns([...columns]);
  return (row) => heLaunchCompanyKey(row, cols);
}

/**
 * Сколько компаний вертикали ждёт в очереди (pending, срок не вышел) — плюс те,
 * что уже держит ЭТА база (`baseId`): повтор прогона после смерти воркера
 * должен видеть свой прошлый захват, иначе он решил бы, что очереди нет, и
 * купил бы сборку, которую очередь покрывала. Оценка, а не захват. Не бросает:
 * не прочиталось — ноль, то есть поведение как до переноса.
 *
 * Читателей два, и вопрос у них разный:
 *  - размер сборки (resolveHeRefillCollectCompanies) — `sendableOnly`: только
 *    компании, которые могут уйти этой ночью; помеченные «ждёт писем»
 *    (HE_REFILL_CARRY_HELD_REASON) остаток дня не закрывают;
 *  - пустой харвест (stages/baseCollect.ts) — без флага: «есть ли кого
 *    перепроверить», и помеченные считаются — иначе у вертикали без новых
 *    компаний их не перепроверила бы ни одна ночь.
 */
export async function countHeRefillCarryover(
  ctx: HeStageContext,
  verticalId: string,
  baseId: string,
  opts?: { sendableOnly?: boolean },
): Promise<number> {
  try {
    let query = ctx.supabase
      .from('he_refill_carryover')
      .select('status, claimed_base_id')
      .eq('vertical_id', verticalId)
      .in('status', ['pending', 'claimed'])
      .gt('expires_at', new Date().toISOString());
    if (opts?.sendableOnly) query = query.is('settle_reason', null);
    const { data, error } = await query.limit(HE_REFILL_CARRYOVER_CLAIM_MAX);
    if (error) throw new Error(error.message);
    return ((data ?? []) as Array<{ status?: unknown; claimed_base_id?: unknown }>).filter(
      (row) => row.status === 'pending' || row.claimed_base_id === baseId,
    ).length;
  } catch (e) {
    stageLog(
      ctx,
      `[base_collect] refill: очередь переноса не прочитана ` +
        `(${e instanceof Error ? e.message : String(e)}) — размер сборки как без неё`,
    );
    return 0;
  }
}

interface HeRefillCarryClaim {
  companies: HeRefillCarryCompany[];
  /** id, которые ЭТА база держала ещё до этого прогона (повтор той же базы). */
  heldBefore: Set<string>;
  /** Истёкших переведено в 'released' этим захватом. */
  released: number;
  /** Снято в 'dropped' этим захватом: брошенные чужие захваты и компании ушедшей базы. */
  dropped: number;
}

function parseCarryCompany(raw: unknown): (HeRefillCarryCompany & { status: string; claimedBy: string | null }) | null {
  const r = raw as Record<string, unknown> | null;
  if (!r || typeof r.id !== 'string' || typeof r.source_base_id !== 'string') return null;
  if (typeof r.company_key !== 'string' || !r.company_key) return null;
  if (!Array.isArray(r.lead_rows) || !Array.isArray(r.lead_columns)) return null;
  const rows = r.lead_rows.filter(
    (row): row is HeRefillCarryRow => !!row && typeof row === 'object' && !Array.isArray(row),
  );
  const columns = r.lead_columns.filter((c): c is string => typeof c === 'string');
  return {
    id: r.id,
    sourceBaseId: r.source_base_id,
    companyKey: r.company_key,
    rows,
    columns,
    status: typeof r.status === 'string' ? r.status : '',
    claimedBy: typeof r.claimed_base_id === 'string' ? r.claimed_base_id : null,
  };
}

/**
 * Причины 'dropped', при которых строка очереди ТОЧНО не уходила письмом:
 * снята до отправки (всё в чёрном списке, база-источник ушла в 'failed', её
 * компанию держит другая база). Её копия не мешает той же компании в другой
 * базе — heRefillCarryPeerConflicts. Остальные причины ('fate_unknown',
 * 'claim_abandoned') — «могла уйти».
 */
const HE_REFILL_CARRY_NEVER_SENT_DROPS = new Set(['no_sendable_address', 'source_base_released', 'prepared_elsewhere']);

/**
 * Компании очереди, которые ПАРАЛЛЕЛЬНАЯ база того же проекта подготовила ещё
 * раз (шаг 3 блока «ПЕРЕНОС»): ids кандидатов, которых брать нельзя.
 *
 * ОТКУДА ДВОЙНИК. Исключение сборок читает `data` других баз проекта, а у
 * собирающейся базы `data` пуст до её терминальной записи. Тик крона ставит
 * вертикали проекта одновременно, поэтому две сборки одной ночи не видят
 * строк друг друга, и одна компания может оказаться в двух базах. До переноса
 * это не давало второго письма: проигравшая бронь ночь отправляла ноль и
 * возвращала компании в пул, где их исключала база победителя. Перенос
 * проигравшей ночи держит её копию в очереди — и отправил бы её второй раз.
 *
 * ПРАВИЛО (копия той же компании в чужой не-'failed' базе P, сверка — тем же
 * правилом «та же компания», что у исключения сборок):
 *  - копия P могла уйти письмом (строки очереди нет — её решила ночь P: отправка,
 *    чёрный список, серия; 'sent'; 'dropped' с неизвестной судьбой) → нашу
 *    копию не берём;
 *  - копия P живая в очереди ('pending' со сроком или 'claimed') → остаётся
 *    одна: копия базы с меньшим id. Порядок один для обеих сторон, поэтому
 *    отправит ровно одна, кто бы ни пришёл первым;
 *  - копия P точно не уходила ('released', истёкшая 'pending', 'dropped' без
 *    отправки) → не мешает.
 *
 * ОКНО. Двойником может быть только база, жившая одновременно с источником:
 * созданная до его терминальной записи и закрытая после его создания
 * (created_at ≤ updated_at источника, updated_at ≥ created_at источника).
 * Более ранние базы источник сам исключил на сборке, более поздние исключили
 * его. Окно ограничивает чтение `data` неделей очереди, а не всей историей.
 *
 * Бросает на сбое чтения: захват тогда не берёт очередь этой ночью (компании
 * ждут следующей), потому что без сверки «не знаем» означало бы «может уйти
 * второй раз».
 */
async function heRefillCarryPeerConflicts(
  ctx: HeStageContext,
  input: {
    projectId: string;
    candidates: ReadonlyArray<HeRefillCarryCompany>;
    sources: ReadonlyMap<string, { createdAtMs: number; updatedAtMs: number }>;
    nowMs: number;
  },
): Promise<Set<string>> {
  const conflicts = new Set<string>();
  if (input.candidates.length === 0) return conflicts;
  const windows = [...input.sources.values()];
  let query = ctx.supabase
    .from('he_bases')
    .select('id, columns, data')
    .eq('project_id', input.projectId)
    .neq('status', 'failed');
  if (windows.length > 0 && windows.every((w) => Number.isFinite(w.createdAtMs) && Number.isFinite(w.updatedAtMs))) {
    query = query
      .gte('updated_at', new Date(Math.min(...windows.map((w) => w.createdAtMs))).toISOString())
      .lte('created_at', new Date(Math.max(...windows.map((w) => w.updatedAtMs))).toISOString());
  }
  const { data: bases, error } = await query;
  if (error) throw new Error(`he_bases peers: ${error.message}`);
  const peers = ((bases ?? []) as Array<{ id?: unknown; columns?: unknown; data?: unknown }>).filter(
    (b): b is { id: string; columns?: unknown; data?: unknown } =>
      typeof b.id === 'string' && Array.isArray(b.data) && b.data.length > 0,
  );
  if (peers.length === 0) return conflicts;

  const states = new Map<string, { status: string; reason: string | null; expiresAtMs: number }>();
  for (const ids of chunked(peers.map((p) => p.id), HE_REFILL_CARRYOVER_ID_CHUNK)) {
    // Страницами: у полусотни баз строк очереди бывает больше потолка одного
    // запроса, а строка, не дошедшая до этой карты, читается как «копия могла
    // уйти письмом» — и наша копия терялась бы навсегда ('prepared_elsewhere').
    const data = await readHeRefillCarryPages('he_refill_carryover peers', (after) => {
      let q = ctx.supabase
        .from('he_refill_carryover')
        .select('id, source_base_id, company_key, status, settle_reason, expires_at')
        .in('source_base_id', ids);
      if (after !== null) q = q.gt('id', after);
      return q.order('id', { ascending: true }).limit(HE_REFILL_CARRYOVER_READ_PAGE);
    });
    for (const r of data) {
      if (typeof r.source_base_id !== 'string' || typeof r.company_key !== 'string') continue;
      states.set(`${r.source_base_id}\u0000${r.company_key}`, {
        status: typeof r.status === 'string' ? r.status : '',
        reason: typeof r.settle_reason === 'string' ? r.settle_reason : null,
        expiresAtMs: typeof r.expires_at === 'string' ? Date.parse(r.expires_at) : NaN,
      });
    }
  }

  const keyed = peers.map((peer) => {
    const columns = Array.isArray(peer.columns)
      ? peer.columns.filter((c): c is string => typeof c === 'string')
      : [];
    const keyOf = heRefillCarryKeyFn(columns.length > 0 ? columns : [...HE_AUTO_COLLECT_COLUMNS]);
    const blocking: Record<string, unknown>[] = [];
    const queued: Record<string, unknown>[] = [];
    for (const item of peer.data as unknown[]) {
      if (!item || typeof item !== 'object') continue;
      const row = item as Record<string, unknown>;
      const st = states.get(`${peer.id}\u0000${keyOf(row)}`);
      if (!st || st.status === 'sent' || (st.status === 'dropped' && !HE_REFILL_CARRY_NEVER_SENT_DROPS.has(st.reason ?? ''))) {
        blocking.push(row);
      } else if (st.status === 'claimed' || (st.status === 'pending' && st.expiresAtMs > input.nowMs)) {
        queued.push(row);
      }
    }
    return { id: peer.id, blocking: heCarryExclusionKeys(blocking), queued: heCarryExclusionKeys(queued) };
  });

  for (const company of input.candidates) {
    const rows = company.rows as unknown as Array<Record<string, unknown>>;
    const clash = keyed.some(
      (peer) =>
        peer.id !== company.sourceBaseId &&
        rows.some(
          (row) =>
            heCarryRowExcluded(peer.blocking, row) ||
            (peer.id < company.sourceBaseId && heCarryRowExcluded(peer.queued, row)),
        ),
    );
    if (clash) conflicts.add(company.id);
  }
  return conflicts;
}

/**
 * Взять очередь вертикали на отправку этой ночью (шаг 3 блока «ПЕРЕНОС»).
 *
 * Никогда не бросает. Всё, что не удалось, оставляет очередь как была, то есть
 * компании ждут следующей ночи: сбой чтения — пустой захват; сбой посреди
 * захвата — возвращается то, что успели взять (иначе взятое стало бы брошенным
 * и ушло бы в 'dropped' следующей ночью).
 *
 * Работа, а не деньги: все запросы — клиентом стадий.
 */
async function claimHeRefillCarryover(
  ctx: HeStageContext,
  input: { projectId: string; verticalId: string; baseId: string },
): Promise<HeRefillCarryClaim> {
  const nowMs = Date.now();
  const now = new Date(nowMs).toISOString();
  const out: HeRefillCarryClaim = { companies: [], heldBefore: new Set(), released: 0, dropped: 0 };
  const note = (what: string, e: unknown) =>
    stageLog(ctx, `[base_collect] refill: перенос — ${what} (${e instanceof Error ? e.message : String(e)})`);

  // Истёкшие — в 'released'. Только учёт: исключение сборок считает истёкшую
  // 'pending' отпущенной и без этой записи, а захват ниже её не берёт.
  try {
    const { data, error } = await ctx.supabase
      .from('he_refill_carryover')
      .update({ status: 'released', settled_at: now, settle_reason: 'expired', updated_at: now })
      .eq('vertical_id', input.verticalId)
      .eq('status', 'pending')
      .lte('expires_at', now)
      .select('id');
    if (error) throw new Error(error.message);
    out.released = (data ?? []).length;
  } catch (e) {
    note('истёкшие не переведены в released', e);
  }
  // Брошенные чужие захваты — в 'dropped' (почему — шаг 3 блока «ПЕРЕНОС»).
  try {
    const { data, error } = await ctx.supabase
      .from('he_refill_carryover')
      .update({ status: 'dropped', settled_at: now, settle_reason: 'claim_abandoned', updated_at: now })
      .eq('vertical_id', input.verticalId)
      .eq('status', 'claimed')
      .neq('claimed_base_id', input.baseId)
      .select('id');
    if (error) throw new Error(error.message);
    out.dropped += (data ?? []).length;
  } catch (e) {
    note('брошенные захваты не сняты', e);
  }

  let candidates: Array<HeRefillCarryCompany & { status: string; claimedBy: string | null }>;
  const live = new Set<string>();
  /** Компании, которые подготовила ещё и параллельная база проекта. */
  let conflicts = new Set<string>();
  try {
    // Сначала строки без пометки «ждёт писем», потом помеченные — до потолка.
    // Размер сборки и тик крона считают только непомеченные (countHeRefillCarryover
    // с sendableOnly, readCarryoverByVertical), и помеченные, окажись они
    // старше, не должны вытеснять из захвата те, на которые ночь рассчитала
    // день: при одном общем «500 самых старых» сотня помеченных строк
    // забирала бы место сотни отправляемых, а сборка уже не куплена.
    const readCandidates = async (marked: boolean, limit: number): Promise<unknown[]> => {
      let query = ctx.supabase
        .from('he_refill_carryover')
        .select('id, source_base_id, company_key, lead_rows, lead_columns, status, claimed_base_id')
        .eq('vertical_id', input.verticalId)
        .in('status', ['pending', 'claimed'])
        .gt('expires_at', now);
      query = marked ? query.not('settle_reason', 'is', null) : query.is('settle_reason', null);
      const { data, error } = await query.order('prepared_at', { ascending: true }).limit(limit);
      if (error) throw new Error(error.message);
      return data ?? [];
    };
    const unmarked = await readCandidates(false, HE_REFILL_CARRYOVER_CLAIM_MAX);
    const marked =
      unmarked.length < HE_REFILL_CARRYOVER_CLAIM_MAX
        ? await readCandidates(true, HE_REFILL_CARRYOVER_CLAIM_MAX - unmarked.length)
        : [];
    candidates = [...unmarked, ...marked]
      .map(parseCarryCompany)
      .filter((c): c is NonNullable<typeof c> => c !== null)
      // Свой прошлый захват (повтор этой же базы) — берём; чужой сюда попадает,
      // только если его снятие выше не легло, и тогда его не трогаем вовсе.
      .filter((c) => c.status === 'pending' || c.claimedBy === input.baseId);
    // База-источник обязана держать компанию исключённой. Ушла в 'failed' или
    // удалена — компания уже в пуле сборки, и слать её отсюда значило бы
    // готовить её второй раз параллельно с этой очередью.
    const sources = new Map<string, { createdAtMs: number; updatedAtMs: number }>();
    for (const ids of chunked([...new Set(candidates.map((c) => c.sourceBaseId))], HE_REFILL_CARRYOVER_ID_CHUNK)) {
      const { data: bases, error: bErr } = await ctx.supabase
        .from('he_bases')
        .select('id, status, created_at, updated_at')
        .in('id', ids);
      if (bErr) throw new Error(`he_bases: ${bErr.message}`);
      for (const b of (bases ?? []) as Array<Record<string, unknown>>) {
        if (typeof b.id !== 'string' || b.status === 'failed') continue;
        live.add(b.id);
        sources.set(b.id, {
          createdAtMs: typeof b.created_at === 'string' ? Date.parse(b.created_at) : NaN,
          updatedAtMs: typeof b.updated_at === 'string' ? Date.parse(b.updated_at) : NaN,
        });
      }
    }
    // Двойники параллельных баз проекта — до захвата: копию, которая могла
    // уйти письмом из другой базы, брать нельзя (heRefillCarryPeerConflicts).
    conflicts = await heRefillCarryPeerConflicts(ctx, {
      projectId: input.projectId,
      candidates: candidates.filter((c) => live.has(c.sourceBaseId)),
      sources,
      nowMs,
    });
  } catch (e) {
    note('очередь не прочитана, ночь идёт без неё', e);
    return out;
  }

  // Двойник параллельной базы — в 'dropped'. Своя 'pending' копия письмом не
  // уходила ('prepared_elsewhere' — для сверки других баз это «не отправлена»);
  // свой прошлый захват мог уйти у умершего прогона — 'fate_unknown'.
  const clashing = candidates.filter((c) => live.has(c.sourceBaseId) && conflicts.has(c.id));
  for (const [ids, status, reason] of [
    [clashing.filter((c) => c.status === 'pending').map((c) => c.id), 'pending', 'prepared_elsewhere'],
    [clashing.filter((c) => c.status === 'claimed').map((c) => c.id), 'claimed', 'fate_unknown'],
  ] as const) {
    for (const chunk of chunked(ids, HE_REFILL_CARRYOVER_ID_CHUNK)) {
      try {
        const { data, error } = await ctx.supabase
          .from('he_refill_carryover')
          .update({ status: 'dropped', settled_at: now, settle_reason: reason, updated_at: now })
          .in('id', chunk)
          .eq('status', status)
          .select('id');
        if (error) throw new Error(error.message);
        out.dropped += (data ?? []).length;
      } catch (e) {
        note('двойники параллельной базы не сняты (этой ночью не берутся)', e);
      }
    }
  }

  const orphaned = candidates.filter((c) => !live.has(c.sourceBaseId)).map((c) => c.id);
  for (const ids of chunked(orphaned, HE_REFILL_CARRYOVER_ID_CHUNK)) {
    try {
      const { data, error } = await ctx.supabase
        .from('he_refill_carryover')
        .update({ status: 'dropped', settled_at: now, settle_reason: 'source_base_released', updated_at: now })
        .in('id', ids)
        .in('status', ['pending', 'claimed'])
        .select('id');
      if (error) throw new Error(error.message);
      out.dropped += (data ?? []).length;
    } catch (e) {
      note('компании ушедшей базы не сняты', e);
    }
  }

  const usable = candidates.filter((c) => live.has(c.sourceBaseId) && !conflicts.has(c.id));
  const taken = new Set<string>();
  for (const c of usable) {
    if (c.status === 'claimed') {
      taken.add(c.id);
      out.heldBefore.add(c.id);
    }
  }
  for (const ids of chunked(usable.filter((c) => c.status === 'pending').map((c) => c.id), HE_REFILL_CARRYOVER_ID_CHUNK)) {
    try {
      const { data, error } = await ctx.supabase
        .from('he_refill_carryover')
        .update({ status: 'claimed', claimed_base_id: input.baseId, claimed_at: now, updated_at: now })
        .in('id', ids)
        .eq('status', 'pending')
        .select('id');
      if (error) throw new Error(error.message);
      for (const row of (data ?? []) as Array<{ id?: unknown }>) {
        if (typeof row.id === 'string') taken.add(row.id);
      }
    } catch (e) {
      note('захват оборвался — берём то, что успели', e);
      break;
    }
  }
  out.companies = usable
    .filter((c) => taken.has(c.id))
    .map(({ id, sourceBaseId, companyKey, rows, columns }) => ({ id, sourceBaseId, companyKey, rows, columns }));
  return out;
}

/** Позиции пачки, которые могли дойти до провайдера: ушли в транспорт и не отклонены им явно. */
function refillReachedPositions(
  result: { attemptedIndexes: readonly number[]; deferredIndexes?: readonly number[] } | null,
): Set<number> {
  const out = new Set<number>();
  if (!result) return out;
  const refused = new Set(result.deferredIndexes ?? []);
  for (const index of result.attemptedIndexes) if (!refused.has(index)) out.add(index);
  return out;
}

interface HeRefillCarrySettle {
  sent: string[];
  /**
   * Обратно в 'pending'. `held` — пометка «ждёт писем»
   * (HE_REFILL_CARRY_HELD_REASON): true — ставится, false — снимается, null —
   * ночь упала до чёрного списка и не знает, держат ли компанию письма:
   * пометка остаётся, какой была.
   */
  returned: Array<{ id: string; held: boolean | null }>;
  dropped: Array<{ id: string; reason: string }>;
}

/**
 * Итог перенесённых компаний этой ночи (шаг 5 блока «ПЕРЕНОС») — по ВСЕМУ
 * набору исходов, чистая функция:
 *  - хотя бы один лид компании дошёл (или мог дойти) до провайдера → 'sent';
 *  - судьба неизвестна (`unknown`: бронь держал прошлый прогон этой же базы,
 *    а он мог эту компанию уже отправить) → 'dropped';
 *  - до чёрного списка не дошли (`inKept` = null: ночь упала раньше) →
 *    'pending' (обратно в очередь), пометка «ждёт писем» не трогается;
 *  - у компании остался лид после чёрного списка → 'pending' без пометки;
 *  - лида после чёрного списка нет, но хоть один лид снят отбором писем этой
 *    ночи (`held`, шаг 3a) → 'pending' с пометкой «ждёт писем»: снятый
 *    письмами адрес уйдёт, когда письма кампании позволят (решение владельца
 *    10.10.2026), а адрес из чёрного списка не уйдёт никогда;
 *  - лида нет и снятых письмами нет (весь адресный набор в чёрном списке
 *    владельца или ни один адрес не разобрался) → 'dropped'.
 */
function planHeRefillCarrySettle(input: {
  companies: readonly HeRefillCarryCompany[];
  ownerOf: ReadonlyMap<object, string>;
  inKept: ReadonlySet<string> | null;
  /** Компании, у которых шаг 3a этой ночи снял хоть один лид. */
  held: ReadonlySet<string>;
  batch: readonly object[];
  reached: ReadonlySet<number>;
  unknown: ReadonlySet<string> | null;
}): HeRefillCarrySettle {
  const reachedIds = new Set<string>();
  for (const position of input.reached) {
    const lead = input.batch[position];
    const id = lead ? input.ownerOf.get(lead) : undefined;
    if (id) reachedIds.add(id);
  }
  const out: HeRefillCarrySettle = { sent: [], returned: [], dropped: [] };
  for (const company of input.companies) {
    if (reachedIds.has(company.id)) out.sent.push(company.id);
    else if (input.unknown?.has(company.id)) out.dropped.push({ id: company.id, reason: 'fate_unknown' });
    else if (input.inKept === null) out.returned.push({ id: company.id, held: null });
    else if (input.inKept.has(company.id)) out.returned.push({ id: company.id, held: false });
    else if (input.held.has(company.id)) out.returned.push({ id: company.id, held: true });
    else out.dropped.push({ id: company.id, reason: 'no_sendable_address' });
  }
  return out;
}

/**
 * Записать итог перенесённых компаний. Деньги, а не работа: 'sent' фиксирует
 * то, что провайдер уже принял, — поэтому клиентом без сигнала. Каждая запись
 * адресована «своим» захватом (status='claimed', claimed_base_id = эта база):
 * чужой итог она не перепишет. Никогда не бросает; false — что-то не легло, и
 * эти компании следующая ночь снимет как брошенные (без второго письма).
 */
async function settleHeRefillCarryover(
  ctx: HeStageContext,
  baseId: string,
  settle: HeRefillCarrySettle,
): Promise<boolean> {
  const db = paidCheckpointDb(ctx);
  const now = new Date().toISOString();
  let ok = true;
  const apply = async (ids: readonly string[], patch: Record<string, unknown>) => {
    for (const chunk of chunked(ids, HE_REFILL_CARRYOVER_ID_CHUNK)) {
      try {
        const { error } = await db
          .from('he_refill_carryover')
          .update(patch)
          .in('id', chunk)
          .eq('status', 'claimed')
          .eq('claimed_base_id', baseId);
        if (error) throw new Error(error.message);
      } catch (e) {
        ok = false;
        stageLog(
          ctx,
          `[base_collect] refill: итог переноса не записан для ${chunk.length} компаний ` +
            `(${e instanceof Error ? e.message : String(e)}) — следующая ночь снимет их как брошенные`,
        );
      }
    }
  };
  // 'sent' первым: из трёх записей только её потеря могла бы стоить письма,
  // если бы брошенный захват не снимался в 'dropped'.
  await apply(settle.sent, { status: 'sent', settled_at: now, settle_reason: null, updated_at: now });
  const back = { status: 'pending', claimed_base_id: null, claimed_at: null, updated_at: now };
  for (const [held, patch] of [
    [true, { ...back, settle_reason: HE_REFILL_CARRY_HELD_REASON }],
    [false, { ...back, settle_reason: null }],
    [null, back],
  ] as const) {
    await apply(settle.returned.filter((r) => r.held === held).map((r) => r.id), patch);
  }
  const byReason = new Map<string, string[]>();
  for (const { id, reason } of settle.dropped) byReason.set(reason, [...(byReason.get(reason) ?? []), id]);
  for (const [reason, ids] of byReason) {
    await apply(ids, { status: 'dropped', settled_at: now, settle_reason: reason, updated_at: now });
  }
  return ok;
}

/**
 * Собственные компании ЭТОЙ ночи, которым не досталось ни одного письма (шаг 1
 * блока «ПЕРЕНОС»): ни один лид компании не дошёл до провайдера, и либо после
 * чёрного списка у неё остался лид, либо хоть один её лид снят отбором писем
 * (`held` — индексы его строк в `rows`, шаг 3a). Чистая функция. Строки
 * компании — все её допущенные строки (`rows` — leadRows ночи): чёрный список,
 * вердикт и отбор писем следующая ночь применит заново.
 *
 * `held` в ответе — у компании нет лида после чёрного списка, есть только
 * снятые письмами: она ложится с пометкой «ждёт писем»
 * (HE_REFILL_CARRY_HELD_REASON). Компания, у которой лид после чёрного списка
 * есть, ложится без пометки, даже если часть её адресов снята письмами: она
 * может уйти следующей же ночью.
 *
 * Компания без ключа (ни имени, ни сайта) не переносится: отрез считает её
 * отдельной компанией по строке, а исключению сборок отпустить её по истечении
 * срока было бы не по чему.
 */
function ownUnsentRefillCompanies(input: {
  rows: readonly HeRefillCarryRow[];
  rowOf: ReadonlyMap<object, number>;
  kept: readonly object[];
  held: readonly number[];
  batch: readonly object[];
  reached: ReadonlySet<number>;
  columns: readonly string[];
}): Array<{ key: string; rows: HeRefillCarryRow[]; held: boolean }> {
  const keyOf = heRefillCarryKeyFn(input.columns);
  const keyOfLead = (lead: object | undefined): string => {
    const index = lead ? input.rowOf.get(lead) : undefined;
    const row = index === undefined ? undefined : input.rows[index];
    return row ? keyOf(row) : '';
  };
  /** Компании с лидом после чёрного списка. */
  const sendable = new Set<string>();
  for (const lead of input.kept) {
    const key = keyOfLead(lead);
    if (key) sendable.add(key);
  }
  const waiting = new Set(sendable);
  for (const index of input.held) {
    const row = input.rows[index];
    const key = row ? keyOf(row) : '';
    if (key) waiting.add(key);
  }
  for (const position of input.reached) {
    const key = keyOfLead(input.batch[position]);
    if (key) waiting.delete(key);
  }
  if (waiting.size === 0) return [];
  const byKey = new Map<string, HeRefillCarryRow[]>();
  for (const row of input.rows) {
    const key = keyOf(row);
    if (!waiting.has(key)) continue;
    const list = byKey.get(key);
    if (list) list.push(row);
    else byKey.set(key, [row]);
  }
  return [...byKey.entries()].map(([key, rows]) => ({ key, rows, held: !sendable.has(key) }));
}

/** Что ночь кладёт в he_refill_carryover: записи и их счёт для воронки. */
interface HeRefillCarryQueuePlan {
  records: Array<Record<string, unknown>>;
  /** Компаний, которые ждут ('pending'). */
  queued: number;
  /** Из `queued` — с пометкой «ждёт писем» (HE_REFILL_CARRY_HELD_REASON). */
  queuedHeld: number;
  /** Компаний, отпущенных сразу (крючок найма не доживёт свежим, heRefillCarryExpiry). */
  releasedHiring: number;
}

/**
 * Записи очереди для собственных компаний ночи. Чистая функция: счёт нужен
 * воронке ДО терминальных записей, а сама запись — после (или, у ночи без
 * бюджета, до) них. Срок каждой компании — heRefillCarryExpiry: компания, чей
 * крючок найма не доживёт до отправки свежим, пишется сразу 'released' —
 * исключение сборок её больше не держит (loadHeRefillReleasedCompanies), а
 * захват её не предложит. Компания, которую держат только письма (`held`),
 * ждёт с пометкой «ждёт писем» — тот же срок, то же правило крючка найма.
 */
function planHeRefillCarryQueue(input: {
  projectId: string;
  verticalId: string;
  baseId: string;
  columns: string[];
  companies: Array<{ key: string; rows: HeRefillCarryRow[]; held: boolean }>;
  nowMs: number;
}): HeRefillCarryQueuePlan {
  const preparedAt = new Date(input.nowMs).toISOString();
  let queued = 0;
  let queuedHeld = 0;
  let releasedHiring = 0;
  const records = input.companies.map((company) => {
    const expiry = heRefillCarryExpiry(company.rows, input.nowMs);
    if (expiry.release) releasedHiring += 1;
    else {
      queued += 1;
      if (company.held) queuedHeld += 1;
    }
    return {
      project_id: input.projectId,
      vertical_id: input.verticalId,
      source_base_id: input.baseId,
      company_key: company.key,
      lead_rows: company.rows,
      lead_columns: input.columns,
      prepared_at: preparedAt,
      expires_at: new Date(expiry.expiresAtMs).toISOString(),
      // Ключи одинаковые у КАЖДОЙ записи: пакетный upsert заполняет
      // отсутствующий ключ NULL'ом, а не DEFAULT'ом колонки (status NOT NULL).
      status: expiry.release ? 'released' : 'pending',
      settled_at: expiry.release ? preparedAt : null,
      settle_reason: expiry.release ?? (company.held ? HE_REFILL_CARRY_HELD_REASON : null),
    };
  });
  return { records, queued, queuedHeld, releasedHiring };
}

/**
 * Положить собственные компании ночи в очередь. Деньги: подготовка уже
 * оплачена, а повтор джобы эту запись не воспроизведёт. ОДИН запрос на всю
 * ночь (≤ HE_AUTO_REFILL_ROWS_LIMIT компаний): либо легли все, либо ни одной —
 * у ночи без бюджета от этого зависит, переносить или возвращать в пул (см.
 * runHeRefillAppend). Идемпотентна по (source_base_id, company_key). Никогда не
 * бросает; false — не легло: у успешной ночи и отказа после доставки компании
 * остаются исключёнными, как до переноса, у ночи без бюджета — уходят в пул.
 */
async function writeHeRefillCarryQueue(ctx: HeStageContext, plan: HeRefillCarryQueuePlan): Promise<boolean> {
  if (plan.records.length === 0) return true;
  try {
    const { error } = await paidCheckpointDb(ctx)
      .from('he_refill_carryover')
      .upsert(plan.records, { onConflict: 'source_base_id,company_key', ignoreDuplicates: true });
    if (error) throw new Error(error.message);
    return true;
  } catch (e) {
    stageLog(
      ctx,
      `[base_collect] refill: очередь переноса не записана ` +
        `(${e instanceof Error ? e.message : String(e)}) — компании ночи без письма в неё не попали`,
    );
    return false;
  }
}

/**
 * Отпущенные компании очереди проекта — для исключения сборок
 * (loadOtherBaseExclusionKeys в stages/baseCollect.ts, только market='us'):
 * база-источник → ключи компаний, которые больше не исключаются. Отпущена =
 * 'released' либо 'pending' с прошедшим сроком (шаг 6 блока «ПЕРЕНОС»).
 *
 * ЧИТАЕТ ВЕСЬ НАБОР И ТОЛЬКО ЕГО. Страницами (readHeRefillCarryPages), двумя
 * наборами: 'released' и 'pending' с `expires_at <= now` (та же граница, что
 * у захвата, который предлагает только `expires_at > now`). Живая очередь,
 * 'claimed', 'sent' и 'dropped' сюда не приходят: по ним исключение держит, и
 * читать их незачем. Прежде это был один запрос по 'pending' + 'released' без
 * страниц, и после потолка строк одного запроса (около тысячи: при 50
 * отпущенных за ночь — около трёх недель одной вертикали) часть отпущенных
 * компаний не доходила до карты и оставалась исключённой навсегда — ровно та
 * потеря, ради которой перенос заведён.
 *
 * РОСТ И ЦЕНА (решение по чистке — в миграции 20261004_0001). 'released' —
 * терминальная строка, и чистить её нельзя: она и ЕСТЬ пропуск исключения;
 * удалённая строка снова исключила бы компанию, пока жива база-источник
 * (удаление базы уносит строку каскадом). Пишется она только на истечении
 * срока и на крючке найма, который не доживёт свежим, то есть не больше
 * компаний ночи, оставшихся без письма: до ~50 на вертикаль за ночь при
 * дефолтах (кап 50, пол сборки 100), а в обычном цикле переноса — около нуля.
 * Худший год — ~18 тыс. строк на вертикаль: 19 страниц по индексу
 * (project_id, status, id), около 3 МБ трёх коротких полей на чтение. Это
 * всегда меньше чтения, рядом с которым оно идёт: каждая отпущенная компания
 * лежит целыми строками в `data` своей базы, а исключение читает `data` всех
 * баз проекта.
 *
 * Не бросает: не прочиталось — пустая карта, то есть истёкшие компании
 * остаются исключёнными, как до переноса. Это безопасная сторона — потерянная
 * компания, а не вторая подготовка.
 */
export async function loadHeRefillReleasedCompanies(
  ctx: HeStageContext,
  projectId: string,
): Promise<Map<string, Set<string>>> {
  const out = new Map<string, Set<string>>();
  try {
    const now = new Date().toISOString();
    for (const status of ['released', 'pending'] as const) {
      const rows = await readHeRefillCarryPages(`he_refill_carryover ${status}`, (after) => {
        let q = ctx.supabase
          .from('he_refill_carryover')
          .select('id, source_base_id, company_key')
          .eq('project_id', projectId)
          .eq('status', status);
        if (status === 'pending') q = q.lte('expires_at', now);
        if (after !== null) q = q.gt('id', after);
        return q.order('id', { ascending: true }).limit(HE_REFILL_CARRYOVER_READ_PAGE);
      });
      for (const raw of rows) {
        const baseId = raw.source_base_id;
        const key = raw.company_key;
        if (typeof baseId !== 'string' || typeof key !== 'string' || !key) continue;
        const keys = out.get(baseId);
        if (keys) keys.add(key);
        else out.set(baseId, new Set([key]));
      }
    }
    return out;
  } catch (e) {
    stageLog(
      ctx,
      `[base_collect] перенос: отпущенные компании не прочитаны ` +
        `(${e instanceof Error ? e.message : String(e)}) — истёкшие остаются исключёнными`,
    );
    return new Map();
  }
}

/**
 * Срок повторного старта завершённой основной кампании после долива: одна
 * кампания (чтение, старт, проверочное чтение — по срокам engCampaignSending,
 * старт начинается, только если до срока остаётся его бюджет на кампанию).
 */
const HE_REFILL_RESTART_DEADLINE_MS = 45_000;

/**
 * Исход повторного старта ОДНОЙ основной кампании по ответу
 * startHeEngLaunchSending (via 'refill'; исходы — HeRefillMainRestartOutcome в
 * autoPipeline.ts). Клиентское решение — не провал: Pause до или во время
 * старта ('client_paused'), выключенная или не включённая отправка аккаунта
 * ('access_off'). Pause во время старта, когда компенсирующая пауза кампании,
 * которой старт уже отправил POST /activate, НЕ подтвердилась
 * (`compensationFailed` > 0), — 'pause_failed', а не 'client_paused': кампания
 * стартована и может отправлять, и фраза «не стартовали» была бы неправдой.
 * Алерт команде по нему уже ушёл из самого старта ('pause_failed',
 * engCampaignSending.ts, шаг 9) — второй отсюда не шлётся. Провал ('failed',
 * `code` — код отказа или кампании):
 * выключатель не читается, ящики пула, воркспейс, письма, запуск до self-serve
 * или идущий, кампания не прочитана, не стартовала, стоит (0/2: её
 * остановили мимо долива — 'not_completed'), остановлена рассыльщиком или
 * удалена, неясный старт, не хватило срока.
 */
export function heRefillMainRestartVerdict(
  result: HeEngStartResult,
): { outcome: Exclude<HeRefillMainRestartOutcome, 'nothing_accepted' | 'cancelled'>; code?: string } {
  if (result.kind === 'refused') {
    if (result.code === 'client_paused_meanwhile') return { outcome: 'client_paused' };
    if (result.code === 'sending_turned_off' || result.code === 'sending_not_enabled') return { outcome: 'access_off' };
    return { outcome: 'failed', code: result.code };
  }
  if (result.compensationFailed > 0) return { outcome: 'pause_failed' };
  if (result.clientPaused || result.compensated > 0) return { outcome: 'client_paused' };
  if (result.started > 0) return { outcome: 'restarted' };
  if (result.alreadySending > 0 && result.failed.length === 0) return { outcome: 'not_needed' };
  const code =
    result.failed[0]?.code ??
    (result.unconfirmed > 0
      ? 'start_unconfirmed'
      : result.notAttempted > 0
        ? 'not_attempted'
        : result.left > 0
          ? 'not_completed'
          : result.campaigns === 0
            ? 'no_campaign'
            : 'not_started');
  return { outcome: 'failed', code };
}

/**
 * Долив собранной базы в запущенную кампанию (вызывается вместо финального
 * блока «analyzing + base_analyze»). Никогда не бросает refill-ошибки наружу
 * (см. шапку); бросает только ошибку финального апдейта самой базы — как
 * обычный путь стадии.
 *
 * У market='us' вместе со строками ночи уходят компании очереди переноса —
 * ПЕРВЫМИ (блок «ПЕРЕНОС» выше). `carryOnly` — ночь сборку не покупала:
 * собственных строк нет, отправляется только очередь.
 */
export async function runHeRefillAppend(args: {
  ctx: HeStageContext;
  job: HeJob;
  base: { id: string; project_id: string; vertical_id: string };
  info: HeCollectInfo;
  stats: HeCollectInfo['stats'];
  finalRows: HeUnifiedRow[];
  finalColumns: string[];
  /**
   * Вердикты валидации по индексам finalRows. null вместо массива (валидации
   * не было вовсе) или null в элементе (у строки вердикта нет) — такая строка
   * в долив НЕ идёт и попадает в stats.unverified, см. selectRefillLeadRows.
   */
  emailStatuses: Array<string | null> | null;
  usage: HeUsage;
  /**
   * Рынок проекта (стадия читает его так же, как для плана). Перенос работает
   * только при 'us'; не передан — переноса нет, долив ровно прежний.
   */
  market?: HeMarket;
  /** Ночь не покупала сборку: отправляется только очередь переноса. */
  carryOnly?: boolean;
}): Promise<HeStageResult> {
  const { ctx, job, base, info, stats, finalRows, finalColumns, emailStatuses, usage } = args;
  /** Перенос неотправленных компаний — только ENG (блок «ПЕРЕНОС»). */
  const carryEnabled = args.market === 'us';
  /** Отбор строк, которым письмо прочиталось бы неверно (шаг 3a), — только ENG. */
  const usLetterGate = args.market === 'us';

  const done = (refill: HeRefillResult): HeStageResult => ({
    result: { base_id: base.id, rows: finalRows.length, refill },
    tokensUsed: usage.tokensUsed,
    costUsd: usage.costUsd,
  });

  const config = await loadRefillConfig(ctx, job.project_id);
  const dailyLeadsCap = config?.dailyLeadsCap ?? HE_AUTO_DEFAULT_DAILY_LEADS_CAP;
  // Кап адресов на компанию ЭТОЙ сборки: он же уехал конструктору в
  // step_config.cap_emails_per_company (collect_info.construct.contact_cap есть
  // всегда, в том числе там, где миграция 20260926_0001 не применена). Читаем
  // снапшот, а не колонку проекта: лимит мог измениться после постановки, а
  // оплачены пробы по тому, с которым сборка шла.
  const contactCap =
    normalizeHeMaxEmailsPerCompany(info.construct?.contact_cap) ?? HE_MAX_EMAILS_PER_COMPANY_DEFAULT;
  const companyTarget = heRefillCompanyTarget({ dailyLeadsCap, contactCap });
  const companyLimit =
    typeof info.limit === 'number' && Number.isFinite(info.limit) ? info.limit : null;
  // Сборка оплачена ДО этой ветки. Если её объём считали не из капа, лишние
  // краулы и SMTP-пробы уже потрачены: кап выбросит их строки, а компании
  // останутся выжженными (база уйдёт в 'analyzed'). Называем это вслух в
  // журнале сборки — иначе первый ночной счёт объяснять будет нечем. Строка
  // исчезнет сама, когда постановка начнёт считать объём в компаниях
  // (resolveHeRefillCollectCompanies).
  if (companyLimit !== null && companyLimit > companyTarget) {
    stageLog(
      ctx,
      `[base_collect] refill: сборка шла на ${companyLimit} компаний при капе ${dailyLeadsCap} ` +
        `лидов (хватило бы ${companyTarget}) — до ` +
        `${(companyLimit - companyTarget) * (contactCap + 1)} адресов проверено впустую; ` +
        'объём сборки должен считаться из капа (resolveHeRefillCollectCompanies)',
    );
  }
  /** Отдали ли строки провайдеру — решает судьбу компаний при отказе. */
  let providerTouched = false;
  /**
   * Прогон потерял право отправлять (HeRefillOwnershipLoss) — пишет
   * assertRefillOwnership перед броском, читает catch: это отмена, а не сбой
   * среза. Живёт ВНЕ try по той же причине, что и бронь.
   */
  let ownershipLoss: Exclude<HeRefillOwnershipLoss, HeRefillSendStop> | null = null;
  /**
   * Шаблон запуска, чью паузу клиентом перечитывает проверка владения: ставит
   * шаг 4c, когда кампании запуска приняты (только market='us'); до него —
   * null, и пауза не читается (её решает сам шаг 4c).
   */
  let clientPauseTemplateId: string | null = null;
  /**
   * Проверка владения увидела остановку отправки (HeRefillSendStop: Pause
   * клиента, выключенный «Daily top-up», выключенная или не включённая
   * отправка аккаунта) и бросила — это не отмена, а остановка загрузки: разбор
   * — «ПАУЗА КЛИЕНТА ВО ВРЕМЯ ЗАГРУЗКИ» в шаге 6 и пропуск этой причиной в
   * catch'е. Живёт ВНЕ try, как ownershipLoss.
   */
  let sendStop: HeRefillSendStop | null = null;
  /**
   * Завершённая основная кампания, которую ночь продолжает (шаг 4c,
   * `mainCompleted`): кого стартовать после долива («ПОВТОРНЫЙ СТАРТ» ниже).
   * null — основная отправляла, шаг 4c не пройден или рынок не 'us'. Живёт ВНЕ
   * try: старт нужен и отказу после частичной доставки (catch).
   */
  let restartTarget: { templateId: string; campaignId: string; ownerUserId: string } | null = null;
  /**
   * Сколько контактов приняла этой ночью ОСНОВНАЯ кампания: её группа пачки и
   * переотправка строк отказавшего сегмента (п. 7 «РАСКЛАДКИ»), в том числе
   * принятое до броска. Читает «ПОВТОРНЫЙ СТАРТ»: ноль — стартовать нечего.
   */
  let mainAccepted = 0;
  /**
   * Проверка владения перед провайдером: прямо перед вызовом долива и в хуке
   * перед КАЖДЫМ HTTP-запросом чанка (см. «ОТМЕНА ВЫИГРЫВАЕТ У ОТПРАВКИ» в
   * шапке). Бросает ДО отправки; обрыв сигнала бросает его же причиной.
   */
  const assertRefillOwnership = async (): Promise<void> => {
    ctx.signal?.throwIfAborted();
    const loss = await readHeRefillOwnershipLoss(ctx, {
      jobId: job.id,
      baseId: base.id,
      projectId: job.project_id,
      templateId: clientPauseTemplateId,
    });
    if (loss && isHeRefillSendStop(loss)) {
      sendStop = loss;
      throw new Error(`${REFILL_SENDING_SKIP_NOTE} (${loss}): ${REFILL_SEND_STOP_TEXT[loss]} во время загрузки`);
    }
    if (loss) {
      ownershipLoss = loss;
      throw new Error(`долив остановлен перед отправкой: прогон больше не вправе отправлять (${loss})`);
    }
  };
  /**
   * Кто именно увидел переполненный воркспейс — текст для причины паузы.
   * null = ёмкость не при чём. Живёт ВНЕ try, потому что оба исхода долива
   * (частичный приём и полный отказ) умеют упереться в ёмкость, а запись паузы
   * обязана идти ПОСЛЕ терминальных записей обоих.
   */
  let capacityPauseSource: string | null = null;
  /**
   * Бронь дневного бюджета этого прогона. Живёт ВНЕ try: закрыть её обязаны
   * оба исхода, иначе неиспользованный объём остался бы занятым до конца
   * UTC-суток и следующая вертикаль ночи не смогла бы его потратить.
   */
  let reservationId: string | null = null;
  /**
   * Состояние переноса, которое нужно ОБОИМ исходам (успех и catch): что взято
   * из очереди, какой лид чьей компании, кто пережил чёрный список, какая
   * пачка ушла провайдеру и что о ней известно. Объект лида переживает
   * blocklist и отрез без копирования (filterBlockedLeads и отрез фильтруют,
   * а не клонируют), поэтому лид служит ключом.
   */
  let carryClaim: HeRefillCarryClaim | null = null;
  const carriedLeadOwner = new Map<object, string>();
  /** null — до чёрного списка долив не дошёл. */
  let carriedInKept: Set<string> | null = null;
  /** Перенесённые компании, у которых шаг 3a этой ночи снял хоть один лид. */
  const carriedHeld = new Set<string>();
  /** Пачка, отданная провайдеру (позиции = индексы attempted/deferred). */
  let sentBatch: readonly object[] = [];
  /**
   * Хвост sentBatch — строки, которые раскладка УДЕРЖАЛА (неотправляющий
   * сегмент, п. 4 «РАСКЛАДКИ»): сколько их и позиции закреплённых за
   * неотправляющей кампанией (п. 6б) — их читают «возможно доставленными» обе
   * ветки, успешная и catch, чтобы компания не ушла ни в основную, ни в перенос.
   */
  let heldCount = 0;
  let heldReached: readonly number[] = [];
  /**
   * Собственные строки-кандидаты ночи (leadRows), какой свой лид из какой
   * строки и что пережило чёрный список — очередь собственных компаний нужна
   * и успешной ветке, и catch'у (ночь без бюджета, отказ после доставки).
   * `ownKept` null — до чёрного списка долив не дошёл, класть нечего.
   */
  let ownLeadRows: HeRefillCarryRow[] = [];
  const ownLeadRow = new Map<object, number>();
  let ownKept: readonly object[] | null = null;
  /** Индексы (в ownLeadRows) своих строк, чей лид снял шаг 3a. */
  const ownHeldRows: number[] = [];
  /** Результат долива, если appendLeads вернулся штатно. */
  let appendOutcome: { attemptedIndexes: readonly number[]; deferredIndexes?: readonly number[] } | null = null;
  const runStats: HeRefillStats = {
    collected: finalRows.length,
    with_email: 0,
    valid: 0,
    unverified: 0,
    appended: 0,
    skipped_blocklist: 0,
    skipped_instantly: 0,
    capped: 0,
    daily_cap: dailyLeadsCap,
    company_target: companyTarget,
    company_limit: companyLimit,
    ...(args.carryOnly ? { carry_only: true as const } : {}),
  };
  /**
   * Очередь собственных компаний ночи (шаг 1 блока «ПЕРЕНОС»): компании, у
   * которых после чёрного списка остался лид или лид снят отбором писем, и ни
   * один лид не дошёл до провайдера (`reached` — позиции пачки, которые дошли
   * или могли дойти). null — класть нечего (не 'us', до чёрного списка не
   * дошли, все охвачены).
   */
  const planOwnQueue = (reached: ReadonlySet<number>): HeRefillCarryQueuePlan | null => {
    if (!carryEnabled || ownKept === null) return null;
    const companies = ownUnsentRefillCompanies({
      rows: ownLeadRows,
      rowOf: ownLeadRow,
      kept: ownKept,
      held: ownHeldRows,
      batch: sentBatch,
      reached,
      columns: finalColumns,
    });
    if (companies.length === 0) return null;
    return planHeRefillCarryQueue({
      projectId: job.project_id,
      verticalId: base.vertical_id,
      baseId: base.id,
      columns: finalColumns,
      companies,
      nowMs: Date.now(),
    });
  };
  /** Счёт переноса этой ночи в воронку (HeRefillStats.carryover) — обе ветки. */
  const noteCarryStats = (settle: HeRefillCarrySettle | null, queue: HeRefillCarryQueuePlan | null): void => {
    const claim = carryClaim;
    const queued = queue?.queued ?? 0;
    const queuedHeld = queue?.queuedHeld ?? 0;
    const releasedHiring = queue?.releasedHiring ?? 0;
    const returnedHeld = settle?.returned.filter((r) => r.held === true).length ?? 0;
    const touched = (claim?.released ?? 0) + (claim?.dropped ?? 0) + queued + releasedHiring;
    if (!settle && touched === 0) return;
    runStats.carryover = {
      offered: claim?.companies.length ?? 0,
      sent: settle?.sent.length ?? 0,
      returned: settle?.returned.length ?? 0,
      ...(returnedHeld > 0 ? { returned_held: returnedHeld } : {}),
      dropped: (settle?.dropped.length ?? 0) + (claim?.dropped ?? 0),
      released: claim?.released ?? 0,
      queued,
      ...(queuedHeld > 0 ? { queued_held: queuedHeld } : {}),
      ...(releasedHiring > 0 ? { released_hiring: releasedHiring } : {}),
    };
  };
  /**
   * ПОВТОРНЫЙ СТАРТ ЗАВЕРШЁННОЙ ОСНОВНОЙ (S2; решение владельца 11.10.2026 —
   * блок «ЗАВЕРШЁННАЯ ОСНОВНАЯ» в autoPipeline.ts). Новые контакты в
   * завершённой кампании сами не уходят: ночь, принявшая в неё хоть один,
   * стартует её снова — engCampaignSending.startHeEngLaunchSending, via
   * 'refill', только эту кампанию. Проверки — все его: выключатель аккаунта,
   * желание клиента 'sending' (и прямо перед POST /activate, и после: Pause
   * посреди старта — компенсирующая пауза), ящики пула и их занятость,
   * воркспейс пресета клиента, письма шаблона, адреса кампании ⊆ ящики пула;
   * стартует только завершённую (3) — стоящую (0/2) и остановленную
   * рассыльщиком (-99/-1/-2, 404) нет; повтор видит 1/4 и ничего не делает
   * (идемпотентно). Контакты — тем, что уже принято, ни одного запроса на
   * загрузку старт не делает.
   * Без вызова: ночь не приняла в основную ни одного контакта
   * ('nothing_accepted' — отправлять нечего) или прогон отменён клиентом
   * ('cancelled'). Зовут обе ветки — успешная и отказ после частичной доставки
   * — ПОСЛЕ терминальной записи базы и закрытия брони (они не ждут
   * рассыльщика), ДО строки прогона: строка несёт исход (stats.main_restart).
   * Не удалось ('failed') — алерт команде ('main_restart_failed'), и гейт
   * держит следующие ночи вертикали, пока кампания не отправляет
   * (readHeRefillRestartHold).
   *
   * КЛИЕНТ БЕЗ СИГНАЛА (paidCheckpointDb). Старт и его компенсирующая пауза
   * читают и пишут основную БД (выключатель, желание клиента до и после POST
   * /activate, запись запуска). Клиентом стадий отмена, сторож простоя или
   * остановка воркера на деплое обрывали эти чтения посреди старта: кампания
   * уже получила POST /activate, чтение желания клиента после него падало, и
   * старт по fail-closed ставил её обратно на паузу и отвечал отказом — ночь
   * писала 'failed', команде уходил алерт, гейт держал вертикаль, хотя клиент
   * хотел отправку (обрыв до POST /activate — тот же 'failed' без старта).
   * Теперь старт доходит до конца (его срок — HE_REFILL_RESTART_DEADLINE_MS),
   * а отмена проверяется явно ДВАЖДЫ:
   *  - до старта — сигнал (отмена, уже увиденная наблюдателем) ИЛИ
   *    he_jobs.status 'cancelled' (cancel-роут записал, наблюдатель ещё нет):
   *    вызова нет, исход 'cancelled';
   *  - после — тем же чтением: отмена пришла во время старта. Исход пишется
   *    как есть (старт уже случился, «отменён» было бы неправдой) с пометкой
   *    `cancelled_during`; кампании, которые к отмене уже отправляли, отмена
   *    не останавливает (cancel-роут их не трогает), — эта ничем не отличается.
   * НЕ БРОСАЕТ.
   */
  const restartCompletedMain = async (cancelledRun: boolean): Promise<void> => {
    const target = restartTarget;
    if (!target) return;
    const record = (outcome: HeRefillMainRestartOutcome, code?: string, cancelledDuring = false): void => {
      runStats.main_restart = {
        campaign_id: target.campaignId,
        outcome,
        accepted: mainAccepted,
        ...(code ? { code } : {}),
        ...(cancelledDuring ? { cancelled_during: true as const } : {}),
      };
    };
    // Старт идёт клиентом без сигнала — отмену он сам не увидит (докблок выше).
    const restartDb = paidCheckpointDb(ctx);
    const runCancelled = async (): Promise<boolean> => {
      if (refillUserCancelled(ctx)) return true;
      try {
        const { data, error } = await restartDb.from('he_jobs').select('status').eq('id', job.id).maybeSingle();
        // Не прочиталось — решает сигнал (выше): старт сам fail-closed на
        // каждом своём чтении.
        return !error && (data as { status?: unknown } | null)?.status === 'cancelled';
      } catch {
        return false;
      }
    };
    let cancelledDuring = false;
    if (mainAccepted === 0) {
      record('nothing_accepted');
    } else if (cancelledRun || (await runCancelled())) {
      record('cancelled');
    } else {
      ctx.onActivity?.();
      let result: HeEngStartResult;
      if (!supabaseInstantly) {
        result = { kind: 'refused', status: 503, code: 'instantly_db_unconfigured', message: '' };
      } else {
        try {
          result = await startHeEngLaunchSending({
            portalDb: restartDb,
            instantlyDb: supabaseInstantly,
            clientUserId: target.ownerUserId,
            projectId: job.project_id,
            templateId: target.templateId,
            via: 'refill',
            onlyCampaignIds: [target.campaignId],
            deadlineMs: Date.now() + HE_REFILL_RESTART_DEADLINE_MS,
          });
        } catch (e) {
          // startHeEngLaunchSending не бросает; страховка — тот же провал.
          result = { kind: 'refused', status: 500, code: 'start_threw', message: e instanceof Error ? e.message : '' };
        }
      }
      cancelledDuring = await runCancelled();
      const verdict = heRefillMainRestartVerdict(result);
      record(verdict.outcome, verdict.code, cancelledDuring);
      if (verdict.outcome === 'failed') {
        void notifyHeRefillHold({
          projectId: job.project_id,
          verticalId: base.vertical_id,
          templateId: target.templateId,
          where: 'refill',
          baseId: base.id,
          alert: {
            kind: 'main_restart_failed',
            campaignId: target.campaignId,
            accepted: mainAccepted,
            code: verdict.code ?? 'unknown',
          },
        });
      }
    }
    const restart = runStats.main_restart;
    stageLog(
      ctx,
      `[base_collect] refill: основная кампания ${target.campaignId} была завершена — принято в неё ${mainAccepted}, ` +
        `повторный старт: ${restart?.outcome ?? '?'}${restart?.code ? ` (${restart.code})` : ''}` +
        (restart?.outcome === 'failed' ? ' — команде алерт, следующие ночи вертикали держатся до отправки кампании' : '') +
        (restart?.outcome === 'pause_failed'
          ? ' — клиент нажал Pause во время старта, пауза кампании не подтвердилась (алерт pause_failed ушёл из старта)'
          : '') +
        (cancelledDuring ? ' — отмена прогона пришла во время старта, старт доведён до конца, исход как есть' : ''),
    );
  };

  try {
    // 1. Кампания и маппинг — из запущенного шаблона вертикали.
    const { data: templateRows, error: tErr } = await ctx.supabase
      .from('he_templates')
      .select('id, launch_info, personalization_plan, letters, created_at')
      .eq('vertical_id', base.vertical_id)
      .not('launch_info', 'is', null);
    if (tErr) throw new Error(`he_templates read: ${tErr.message}`);
    const preferredCampaignId =
      typeof info.campaign_id === 'string' && info.campaign_id ? info.campaign_id : null;
    const pick = pickRefillTemplate((templateRows ?? []) as Array<Record<string, unknown>>, preferredCampaignId);
    if (!pick) {
      throw new Error('у вертикали нет запущенной кампании (he_templates.launch_info) — доливать некуда');
    }

    // 2. Владелец пресета — чей Instantly-аккаунт, blocklist и тариф (как у
    //    клиентского auto-pipeline: appendLeadsToClientCampaign по userId).
    if (!supabaseInstantly) {
      throw new Error('supabaseInstantly не сконфигурирован (INSTANTLY_SUPABASE_URL)');
    }
    const { data: presetRow, error: pErr } = await supabaseInstantly
      .from('client_campaign_presets')
      .select('client_user_id')
      .eq('id', pick.presetId)
      .maybeSingle();
    if (pErr) throw new Error(`client_campaign_presets read: ${pErr.message}`);
    const ownerUserId = (presetRow as { client_user_id?: unknown } | null)?.client_user_id;
    if (typeof ownerUserId !== 'string' || !ownerUserId) {
      throw new Error(`пресет ${pick.presetId} не найден — владелец кампании неизвестен`);
    }

    // 3. Лиды: email + допущенный вердикт валидации, маппинг колонок →
    //    переменные шаблона.
    const { leadRows, leadRowIndexes, withEmail, valid, unverified } =
      selectRefillLeadRows(finalRows, emailStatuses);
    runStats.with_email = withEmail;
    runStats.valid = valid;
    runStats.unverified = unverified;
    // Ни одного проверенного адреса, а непроверенные есть — валидация не
    // доработала. Уходим в общий отказ долива (catch ниже): прогон 'failed' с
    // причиной, компании возвращаются в пул по тому же правилу, что и у
    // недоставленного отказа, и завтрашняя сборка проверит их заново. Тихий
    // 'no_new' здесь означал бы «новых компаний нет» — отчёт, по которому
    // неделю неотправки не отличить от исчерпанного рынка.
    //
    // Статус фазы конструктора в тексте не для красоты: he_bases.error кабинет
    // сворачивает в машинный код причины (clientErrors.classifyHeClientError),
    // и по этой формулировке ENG-клиент получает «валидация почт не
    // доработала» вместо обобщённого технического сбоя. Переформулировать —
    // только сверившись с тем классификатором.
    if (valid === 0 && unverified > 0) {
      throw new Error(
        `валидация почт не дала вердиктов: ${unverified} стр. с адресом не проверено ` +
          `(конструктор завершился со статусом ${info.construct?.status ?? 'неизвестным'}) — ` +
          'долив остановлен',
      );
    }
    // Ни одного адреса вообще, и конструктор не доработал: джоба кончилась
    // failed/cancelled либо 'done' без данных (импорт ничего не принёс —
    // emails_found пишется только у импорта). Каталожные строки адресов не
    // несут, поэтому такая сетка — исходная выборка без единого адреса, и
    // правило выше её не ловит (непроверенных строк нет, раз нет адресов). Ноль
    // здесь — наш сбой, а не рынок: 'no_new' выжег бы оплаченный срез под
    // отчётом «отправлять нечего» и засчитал бы ночь сухой (scan_complete=true).
    // Уходим в общий отказ — компании вернутся в пул по правилу серии.
    //
    // Граница честная: ночь, где конструктор ДОРАБОТАЛ и не нашёл ни одного
    // адреса, остаётся 'no_new' (известное ограничение волны 6a), как и ночь,
    // где конструктор не запускался вовсе (гейт вычеркнул все строки — их
    // компании исключаются сознательно, см. allOffTarget в stages/baseCollect.ts).
    // Тексты — под тот же классификатор кабинета, что и выше ('enrichment').
    const construct = info.construct;
    const constructorUnfinished =
      !!construct?.bc_job_id && (construct.status !== 'done' || construct.emails_found === undefined);
    if (valid === 0 && withEmail === 0 && construct && constructorUnfinished) {
      throw new Error(
        construct.status === 'done'
          ? 'конструктор вернул пустые данные: в сетке нет ни одного адреса — долив остановлен'
          : `поиск адресов не доработал: в сетке нет ни одного адреса ` +
            `(конструктор завершился со статусом ${construct.status}) — долив остановлен`,
      );
    }
    const ownMapping = heRefillOperatorMapping(pick.operatorMapping, finalColumns, args.market);
    const ownMapped = mapBaseRowsToLeads({
      rows: leadRows,
      columns: finalColumns,
      operatorMapping: ownMapping,
      // Связь «доставленный лид → строка базы». Дальше значение подхватит
      // построчный журнал доставки (client_campaign_contact_ledger.source_row_id)
      // — второго журнала мы не заводим, а заполняем колонку, которая у ENG
      // стояла пустой.
      //
      // Ключ НЕ позиционный, и это принципиально: `persistRefillBase`
      // переписывает he_bases.data той же базы целиком, а повтор прогона
      // добирает строки от сдвинувшейся закладки каталога — под тем же
      // индексом завтра лежала бы ДРУГАЯ компания, и запись журнала,
      // сделанная умершим предшественником, показывала бы не на ту строку.
      // Нормализованное имя компании переживает переписывание: оно и есть то,
      // чем база опознаёт компанию в исключениях других баз проекта.
      // Индекс leadRowIndexes оставлен запасным ключом на случай пустого
      // имени (такие строки до отправки не доходят, но ключ обязан быть
      // определён хотя бы чем-то).
      sourceRowId: (index) => {
        const row = leadRows[index];
        const companyKey = row ? normalizeCompanyForDedup(row.company) : '';
        if (companyKey) return `${base.id}:${companyKey}`;
        const rowIndex = leadRowIndexes[index];
        return rowIndex === undefined ? null : `${base.id}:#${rowIndex}`;
      },
    });
    // 3a. Строки, которым письмо кампании прочиталось бы неверно (только
    //     market='us', heRefillUnfilledRows): в пачку не идут, в базе остаются,
    //     а их компания без иного лида ложится в очередь переноса с пометкой
    //     «ждёт писем» (ownHeldRows → planOwnQueue). Отбор — ДО чёрного списка
    //     и брони: снятая строка не просит бюджета дня и не считается попыткой
    //     отправки. Иной рынок — ровно прежние лиды в прежнем порядке.
    let heldUnfilled = 0;
    const heldUnfilledDetails = new Set<string>();
    const ownUnfilled = usLetterGate
      ? heRefillUnfilledRows({
          letters: pick.letters,
          columns: finalColumns,
          operatorMapping: ownMapping,
          rows: leadRows,
          emailColumn: ownMapped.emailColumn,
        })
      : null;
    const leads: typeof ownMapped.leads = [];
    const leadSourceRows: number[] = [];
    /**
     * Лид ночи → его строка и чем её читали: раскладке по сегментам
     * (routeHeRefillSegments, шаг 6) — классификатору и гейту писем сегмента.
     * Пишется у каждого лида, свой он или перенесённый (шаг 3b).
     */
    const leadSources = new Map<object, HeRefillLeadSource>();
    ownMapped.leads.forEach((lead, i) => {
      const rowIndex = ownMapped.leadRowIndices[i];
      if (ownUnfilled && ownUnfilled.held(leadRows[rowIndex])) {
        heldUnfilled += 1;
        heldUnfilledDetails.add(ownUnfilled.detail);
        ownHeldRows.push(rowIndex);
        return;
      }
      leads.push(lead);
      leadSourceRows.push(rowIndex);
      leadSources.set(lead, {
        row: leadRows[rowIndex],
        columns: finalColumns,
        operatorMapping: ownMapping,
        emailColumn: ownMapped.emailColumn,
        sourceKey: 'own',
      });
    });

    // 3b. ПЕРЕНОС (только market='us', блок «ПЕРЕНОС» выше): компании очереди
    //     вертикали — ПЕРВЫМИ в пачке. Берутся только после проверок своей
    //     сетки: ночь, которая всё равно уйдёт в отказ на шаге 3, очередь не
    //     трогает. Вердикт каждой перенесённой строки перепроверяется тем же
    //     selectRefillLeadRows (уходит только 'accepted', строки вне вертикали
    //     — нет), маппинг — колонками её базы-источника, а пометка доставки
    //     показывает на строку именно той базы, где компания лежит.
    //     Компании с пометкой «ждёт писем» берутся так же: отбор писем (3a) у
    //     них — по письмам кампании, в которую доливает ЭТА ночь.
    //     Без очереди (или не 'us') пачка — ровно прежняя: те же лиды в том же
    //     порядке.
    let sendLeads = leads;
    let sendLeadSourceRows = leadSourceRows;
    let sendLeadRows: HeRefillCarryRow[] = leadRows;
    // Свой лид → индекс его строки в leadRows (очередь собственных компаний).
    ownLeadRows = leadRows;
    leads.forEach((lead, i) => ownLeadRow.set(lead, leadSourceRows[i]));
    /**
     * Допущенных строк у перенесённых компаний за вычетом снятых отбором писем
     * этой ночи — для исхода 'no_new' / 'appended'. Снятые не считаются: у
     * ночи без своих строк, чья очередь — только компании, которые письма
     * держат и сегодня, отправить нечего, и это та же 'no_new', что была у неё
     * до того, как такие компании стали попадать в очередь.
     */
    let carriedValid = 0;
    if (carryEnabled) {
      carryClaim = await claimHeRefillCarryover(ctx, {
        projectId: job.project_id,
        verticalId: base.vertical_id,
        baseId: base.id,
      });
      if (carryClaim.companies.length > 0) {
        const carriedRows: HeRefillCarryRow[] = [];
        const carriedLeads: typeof leads = [];
        const carriedSourceRows: number[] = [];
        for (const company of carryClaim.companies) {
          const picked = selectRefillLeadRows(
            company.rows,
            company.rows.map((row) => (typeof row._email_status === 'string' ? row._email_status : null)),
          );
          let heldHere = 0;
          const offset = carriedRows.length;
          carriedRows.push(...picked.leadRows);
          const carriedMapping = heRefillOperatorMapping(pick.operatorMapping, company.columns, args.market);
          const mapped = mapBaseRowsToLeads({
            rows: picked.leadRows,
            columns: company.columns,
            operatorMapping: carriedMapping,
            sourceRowId: (index) => {
              const row = picked.leadRows[index];
              const companyKey = row ? normalizeCompanyForDedup(row.company) : '';
              return companyKey ? `${company.sourceBaseId}:${companyKey}` : null;
            },
          });
          // Тот же отбор, что у своих строк (3a), по колонкам базы-источника и
          // письмам кампании этой ночи. Компания, у которой не осталось ни
          // одного лида, в пачку не попадает; снят хоть один её лид письмами —
          // возвращается в очередь с пометкой «ждёт писем» (carriedHeld →
          // planHeRefillCarrySettle); лидов нет совсем и ночь дошла до чёрного
          // списка — снимается как 'no_sendable_address'; не дошла — ждёт дальше.
          const carriedUnfilled = usLetterGate
            ? heRefillUnfilledRows({
                letters: pick.letters,
                columns: company.columns,
                operatorMapping: carriedMapping,
                rows: picked.leadRows,
                emailColumn: mapped.emailColumn,
              })
            : null;
          mapped.leads.forEach((lead, i) => {
            if (carriedUnfilled && carriedUnfilled.held(picked.leadRows[mapped.leadRowIndices[i]])) {
              heldUnfilled += 1;
              heldHere += 1;
              heldUnfilledDetails.add(carriedUnfilled.detail);
              carriedHeld.add(company.id);
              return;
            }
            carriedLeads.push(lead);
            carriedSourceRows.push(offset + mapped.leadRowIndices[i]);
            carriedLeadOwner.set(lead, company.id);
            leadSources.set(lead, {
              row: picked.leadRows[mapped.leadRowIndices[i]],
              columns: company.columns,
              operatorMapping: carriedMapping,
              emailColumn: mapped.emailColumn,
              sourceKey: `carry:${company.id}`,
            });
          });
          // Снятых лидов не больше допущенных строк: лид растёт из строки.
          carriedValid += picked.valid - heldHere;
        }
        // Один адрес — один лид: свой лид с адресом, который уже несёт
        // перенесённая компания, в пачку не идёт (провайдер отсеял бы его как
        // дубль, но решать это до отправки дешевле и честнее для воронки).
        const carriedEmails = new Set(carriedLeads.map((lead) => lead.email));
        sendLeads = [...carriedLeads];
        sendLeadSourceRows = [...carriedSourceRows];
        leads.forEach((lead, i) => {
          if (carriedEmails.has(lead.email)) return;
          sendLeads.push(lead);
          sendLeadSourceRows.push(carriedRows.length + leadSourceRows[i]);
        });
        sendLeadRows = [...carriedRows, ...leadRows];
      }
    }
    if (heldUnfilled > 0) {
      runStats.held_unfilled = heldUnfilled;
      stageLog(
        ctx,
        `[base_collect] refill: не отправлено ${heldUnfilled} адр. — письмо кампании прочиталось бы у них ` +
          `неверно (${[...heldUnfilledDetails].join('; ')}); строки остаются в своих базах, компании ` +
          'без иного адреса идут в очередь переноса с пометкой «ждёт писем» по правилам итога ночи ' +
          '(строка «перенос» ниже), и следующие ночи перепроверяют их по письмам своей кампании',
      );
      // Снято ВСЁ, что ночь могла отправить (held_unfilled равен допущенным
      // строкам — своим и перенесённым — за вычетом тех, что лидом не стали бы
      // и так: пустой, кривой или повторный адрес). Ночь не отправит ничего —
      // команде нужен алерт, а не только строка лога.
      if (sendLeads.length === 0) {
        alertRefillLettersHeld(
          job,
          base,
          args.market,
          pick.campaignId,
          heldUnfilled,
          [...heldUnfilledDetails].join('; '),
          args.carryOnly === true,
          // Тот же признак, что у исхода ночи ниже ('no_new').
          valid === 0 && carriedValid === 0,
        );
      }
    }

    // 4. Blocklist владельца (сами считаем — число нужно в журнале;
    //    appendLeadsToClientCampaign продублирует фильтр внутри, это дёшево).
    const blockedSet = await getBlockedEmailSet(supabaseInstantly, ownerUserId);
    const { kept, blockedCount } = filterBlockedLeads(sendLeads, blockedSet);
    runStats.skipped_blocklist = blockedCount;
    ownKept = kept;
    if (carryClaim && carryClaim.companies.length > 0) {
      carriedInKept = new Set();
      for (const lead of kept) {
        const owner = carriedLeadOwner.get(lead);
        if (owner) carriedInKept.add(owner);
      }
    }

    // 4b. ЗАМЕР того, что прячет skipIfInCampaign (см. HeRefillSkipProbe).
    //     ВЫКЛЮЧЕН по умолчанию (HE_REFILL_SKIP_PROBE_REQUESTS): без него шаг
    //     не делает ни одного запроса и не пишет ни одного ключа.
    //     Только считает: ни одна строка отсюда не выпадает, и отказ замера
    //     ночь не роняет. Стоит до брони — это чтение, а бронь держит дневной
    //     объём проекта, и растягивать её на минуты чтения нельзя.
    const skipProbe = await measureRefillSkipExposure(ctx, {
      leads: kept,
      ownerUserId,
      campaignId: pick.campaignId,
    });
    if (skipProbe) {
      runStats.skip_probe = skipProbe;
      // Числа обязаны быть видны в логе прогона, а не только в jsonb: решение
      // по флагу принимается глазами, и «замер был, вот что он показал» должно
      // читаться без SQL.
      stageLog(
        ctx,
        `[base_collect] refill: замер skipIfInCampaign — спрошено ${skipProbe.probed} ` +
          `адресов из ${skipProbe.of}: в нашей кампании ${skipProbe.already_in_our_campaign}, ` +
          `в ЧУЖОЙ кампании воркспейса ${skipProbe.in_other_campaign}, ` +
          `в воркспейсе без кампании ${skipProbe.in_workspace_no_campaign}, ` +
          `нет в воркспейсе ${skipProbe.absent}, без вывода ${skipProbe.undecided} ` +
          `(${skipProbe.requests} запросов` +
          // «Оборвался» и «выборка» — разные вещи, и по числам их не отличить:
          // и то и другое даёт probed < of.
          `${skipProbe.stopped_early ? ', замер оборван: срок или отказ провайдера' : ''}; ` +
          'флаг НЕ менялся — это измерение)',
      );
    }

    // 4c. КАМПАНИИ ЗАПУСКА ОТПРАВЛЯЮТ? (S2; до брони и до провайдера). Между
    //     постановкой ночи (03:20) и этим местом проходят часы сборки: клиент
    //     мог нажать Pause, выключить «Daily top-up», кампания могла
    //     завершиться или встать у рассыльщика. Та же проверка, что у тика
    //     (autoPipeline.ts, блок «КАМПАНИИ ЗАПУСКА ОТПРАВЛЯЮТ?»): основная
    //     кампания отправляет по свежему статусу (живое чтение перед решением),
    //     у ENG-клиента — из ящиков пула проекта, иначе долив пропущен — отказом
    //     ниже (catch): провайдер не получил
    //     ничего, у market='us' компании ночи ждут в очереди переноса, как у
    //     ночи без бюджета, перенесённые возвращаются в очередь, бронь не
    //     бралась, серия отказов вертикали ночь не считает (stats.sending_skip).
    //     Пропуск, который чинит только команда, — ещё и алерт
    //     (notifyHeRefillHold).
    //     Сегментные кампании ночь не отменяют: гейт отдаёт вердикт каждой, и
    //     раскладка 6a решает их строки (блок «РАСКЛАДКА», п. 4): отправляющая
    //     получает свои, завершённая отдаёт их основной, остальные держат —
    //     строки не уходят никуда, компании ждут в очереди переноса. О
    //     сегментах, остановленных рассыльщиком, удалённых или стоящих, — алерт
    //     команде. С этого места Pause клиента перечитывается и перед каждым
    //     чанком загрузки (clientPauseTemplateId → readHeRefillOwnershipLoss).
    let segmentVerdicts: ReadonlyMap<string, HeRefillCampaignVerdictDetail> = new Map();
    if (kept.length > 0) {
      const sendTarget = await checkHeRefillSendTarget(ctx.supabase, job.project_id, {
        verticalId: base.vertical_id,
        templateId: pick.templateId,
        presetId: pick.presetId,
        mainCampaignId: pick.campaignId,
        segmentCampaignIds: [...new Set(pick.segmentCampaigns.values())],
      });
      if (!sendTarget.allowed) {
        runStats.sending_skip = sendTarget.reason;
        if (sendTarget.alert) {
          void notifyHeRefillHold({
            projectId: job.project_id,
            verticalId: base.vertical_id,
            templateId: pick.templateId,
            where: 'refill',
            baseId: base.id,
            alert: sendTarget.alert,
          });
        }
        throw new Error(`${REFILL_SENDING_SKIP_NOTE} (${sendTarget.reason}): ${sendTarget.detail}`);
      }
      segmentVerdicts = sendTarget.segmentVerdicts;
      if (args.market === 'us') clientPauseTemplateId = pick.templateId || null;
      // Завершённая основная, которую можно продолжить: приняв в неё контакты,
      // долив стартует её снова («ПОВТОРНЫЙ СТАРТ»).
      if (sendTarget.mainCompleted && args.market === 'us') {
        restartTarget = { templateId: pick.templateId, campaignId: pick.campaignId, ownerUserId };
        stageLog(
          ctx,
          `[base_collect] refill: основная кампания ${pick.campaignId} завершена — после долива её стартуем снова ` +
            '(если в неё примется хоть один контакт)',
        );
      }
      const notSending = [...segmentVerdicts].filter(([, v]) => v.verdict !== 'sending');
      if (notSending.length > 0) {
        stageLog(
          ctx,
          `[base_collect] refill: сегментных кампаний не отправляет ${notSending.length} из ${segmentVerdicts.size} ` +
            `(${notSending.map(([id, v]) => `${id}: ${v.detail}`).join('; ')}) — строки завершённых уходят в основную ` +
            `кампанию ${pick.campaignId}, строки остальных этой ночью держатся (очередь переноса)`,
        );
      }
      // Команде — о том, что без неё не пройдёт: остановлена рассыльщиком,
      // удалена или стоит. «Статус не подтверждён» — сбой чтения этой ночи,
      // строка лога выше; завершённая отдаёт строки основной.
      const teamFixes = notSending.filter(([, v]) => v.verdict === 'stopped' || v.verdict === 'not_sending');
      if (teamFixes.length > 0 && args.market === 'us') {
        void notifyHeRefillHold({
          projectId: job.project_id,
          verticalId: base.vertical_id,
          templateId: pick.templateId,
          where: 'refill',
          baseId: base.id,
          alert: {
            kind: 'segments_held',
            mainCampaignId: pick.campaignId,
            campaigns: teamFixes.map(([id, v]) => ({ id, detail: v.detail })),
            carryMaxDays: HE_REFILL_CARRYOVER_MAX_AGE_DAYS,
          },
        });
      }
    }

    // 5. Дневной кап проекта — БРОНЬ, взятая до первого запроса к рассыльщику.
    //    Кап заморожен за проектом на UTC-день, занятое считается под
    //    advisory-локом, поэтому два прогона одного проекта (в том числе два
    //    воркера на одной джобе после resetStuckJobs) не могут выдать друг
    //    другу один и тот же остаток. Ошибка брони — fail-closed: долив уходит
    //    в общий отказ, не отправив ни строки (см. reserveRefillDailyBudget).
    let toSend = kept;
    if (kept.length > 0) {
      const budget = await reserveRefillDailyBudget(ctx, {
        projectId: job.project_id,
        baseId: base.id,
        requested: kept.length,
      });
      reservationId = budget.id;
      if (budget.granted < kept.length && budget.granted > 0) {
        // Отрез ПО КОМПАНИЯМ, а не по порядку строк. После split_emails адреса
        // компании стоят подряд, и `kept.slice(0, granted)` отдавал весь кап
        // нескольким первым компаниям по всем их адресам, а остальные
        // оплаченные компании не получали ничего — и всё равно выжигались
        // (база 'analyzed'). Правило — то же, что у ручного запуска
        // (selectLeadsWithinLaunchCap, launchHandoff.ts): сначала по одному
        // адресу КАЖДОЙ компании, потом вторые адреса и т. д. При дефолтах
        // (кап 50, ~2 допущенных адреса на компанию из 100) письмо получают
        // ~50 компаний вместо ~25. appendLeads.ts не меняется.
        const cut = selectRefillLeadsByCompany({
          kept,
          leads: sendLeads,
          leadSourceRows: sendLeadSourceRows,
          leadRows: sendLeadRows,
          columns: finalColumns,
          granted: budget.granted,
        });
        toSend = cut.toSend;
        if (cut.companiesHeldBack > 0) runStats.capped_companies = cut.companiesHeldBack;
      } else {
        toSend = kept.slice(0, budget.granted);
      }
      runStats.reserved = budget.granted;
      runStats.budget_outcome = budget.outcome;
      if (budget.dailyCap !== null) runStats.daily_cap = budget.dailyCap;
      if (budget.spentBefore !== null && budget.dailyCap !== null) {
        runStats.daily_remaining = Math.max(0, budget.dailyCap - budget.spentBefore);
      }
      runStats.capped = kept.length - toSend.length;
      // Причина отреза — рядом с числом: воронка обязана отличать «бюджет
      // проекта на сутки» от брака адресов (unverified/отклонённые выше) и от
      // повтора прогона, у которого бюджет уже занят его первой попыткой.
      if (runStats.capped > 0) {
        runStats.capped_reason =
          budget.outcome === 'already_reserved' ? 'repeat_run' : 'daily_leads_cap';
      }
      if (budget.outcome === 'reclaimed') {
        // Перехват своей же брони: предшественник этой базы умер между
        // взятием брони и её закрытием (открыта дольше окна перехвата).
        // Молчать нельзя — это единственное место, где видно, что ночь
        // доедает чужой хвост, и что часть строк провайдер может отсеять как
        // уже принятые от предшественника.
        stageLog(
          ctx,
          `[base_collect] refill: бронь этой базы висела открытой дольше окна перехвата — ` +
            `забрали её себе (${budget.granted} стр. разрешено); строки, которые предыдущий ` +
            'прогон успел отдать, провайдер отсеет как дубли',
        );
      }
      // 5б. Бюджет не дал НИ ОДНОЙ строки — этот прогон провайдеру сегодня не
      //     отдаст ничего. Уходим в общий отказ (catch ниже). Прежнее
      //     поведение (тихий 'appended' с нулём) писало базу 'analyzed', и
      //     оплаченный срез выжигался из будущих сборок проекта навсегда.
      //     Судьба компаний в catch'е зависит от исхода брони
      //     (HeRefillBudgetOutcome): 'cap_exhausted' их не выжигает ВСЕГДА и в
      //     серию отказов не идёт — бюджет занят чужими базами, срез тут ни
      //     при чём: у market='us' компании уходят в очередь переноса, иначе
      //     в пул; 'already_reserved' их НЕ возвращает и не переносит — бронь
      //     держит прошлый прогон этой же базы, который мог уже отправить.
      //
      //     Текст причины разный у разных исходов и это не косметика: «кап
      //     проекта занят другими вертикалями» лечится капом, а «бронь этой
      //     базы моложе окна» — ничем, это ночь двойника. Общий якорь
      //     «дневной бюджет добора» — для разбора в journal/БД.
      if (toSend.length === 0) {
        throw new Error(
          budget.outcome === 'already_reserved'
            ? `дневной бюджет добора этой базы на сегодня уже забронирован её первым прогоном ` +
              `(${kept.length} стр. не отправлены) — долив остановлен`
            : `дневной бюджет добора проекта на сегодня занят целиком ` +
              `(${kept.length} стр. не отправлены, исход брони ${budget.outcome}) — долив остановлен`,
        );
      }
    } else {
      runStats.capped = 0;
    }

    // 6. Долив. valid===0 — 'no_new': сюда доходит только случай «вердикты
    //    есть, но ни один адрес не допущен» (или адресов не нашли вовсе, а
    //    конструктор доработал), то есть добор действительно нечего
    //    отправлять; непроверенные адреса и недоработавший конструктор
    //    отсеялись отказом на шаге 3. Валидные были, но всех съел blocklist —
    //    'appended' с appended=0 (воронка в stats): blocklist это решение
    //    ВЛАДЕЛЬЦА по конкретным адресам, а не отложенная ночь, и компании
    //    такой базы отработаны честно. Съел кап — уже не сюда: нулевой
    //    бюджет ушёл в отказ шагом 5б, а судьбу компаний решает исход брони.
    /** Сегментных кампаний в раскладке пачки (6a) — для итоговой строки лога. */
    let segmentGroups = 0;
    if (toSend.length > 0) {
      // Отмена, записанная к этой секунде, не отправляет ничего (и не тратит
      // ни запроса ёмкости, ни строки журнала доставки внутри долива, ни
      // вызова классификатора сегментов). Отмену посреди долива ловит та же
      // проверка в хуке ниже и перед каждой следующей кампанией.
      await assertRefillOwnership();
      // 6a. Раскладка по сегментным кампаниям запуска (только market='us' и
      //     только у запуска с сегментными кампаниями — любыми, не только
      //     отправляющими: закрепления журнала читаются по всем; блок
      //     «РАСКЛАДКА»): делится уже срезанная капом пачка, группы и
      //     удержанные — её разбиение. Иначе — одна группа, основная кампания:
      //     ровно прежний долив.
      const routing: HeRefillRouting<(typeof toSend)[number]> =
        args.market === 'us' && pick.segmentCampaigns.size > 0
          ? await routeHeRefillSegments(ctx, {
              leads: toSend,
              sourceOf: leadSources,
              mainCampaignId: pick.campaignId,
              segmentCampaigns: pick.segmentCampaigns,
              segmentVerdicts,
              letters: pick.letters,
              ownerUserId,
              usage,
            })
          : {
              groups: [{ campaignId: pick.campaignId, segment: null, leads: [...toSend], pinned: new Set<(typeof toSend)[number]>() }],
              worked: false,
              held: [],
              heldPinned: new Set<(typeof toSend)[number]>(),
            };
      // Пачка запоминается ДО вызова: позиции в attempted/deferred (и в снимке
      // частичного отказа) — индексы именно этого массива, а итог переноса
      // обязан знать, чей лид на какой позиции, и в catch'е тоже. Порядок —
      // группы подряд: основная, затем сегменты (у одной группы это toSend), а
      // В КОНЦЕ — удержанные строки неотправляющих сегментов (п. 4 раскладки):
      // в провайдер они не идут, их позиции не бывают попыткой, поэтому их
      // компании читаются недошедшими (перенос) — кроме закреплённых за
      // неотправляющей кампанией: те «возможно доставлены» (heldReached).
      sentBatch = [...routing.groups.flatMap((group) => group.leads), ...routing.held];
      const sendCount = sentBatch.length - routing.held.length;
      heldCount = routing.held.length;
      heldReached = routing.held.flatMap((lead, i) => (routing.heldPinned.has(lead) ? [sendCount + i] : []));
      segmentGroups = routing.groups.filter((group) => group.segment !== null).length;
      const appendGroup = (campaignId: string, groupLeads: typeof toSend) => appendLeadsToClientCampaign({
        userId: ownerUserId,
        campaignId,
        leads: groupLeads,
        contextLabel: `HE auto-refill · ${base.id}`,
        // Флаг ВОРКСПЕЙС-ШИРОКИЙ, а не кампания-широкий: Instantly отсеет
        // адрес, лежащий в ЛЮБОЙ кампании аккаунта, включая кампании других
        // клиентов студии. Мы за такой контакт уже заплатили сбором и не
        // отправим его никогда — при этом его компания уходит из будущих
        // сборок проекта вместе со всей базой ('analyzed').
        //
        // Почему он всё же остаётся true в этой волне. Во-первых, цена флага
        // до сих пор НЕ ИЗМЕРЕНА: ночной добор не запускался в production ни
        // разу, и «сколько адресов занято соседями» никто не считал — этим
        // занят шаг 4b выше (runStats.skip_probe), и решение принимается по
        // его числам, а не по ощущению. Во-вторых, семантику флага нельзя
        // подтвердить снаружи: единственное свидетельство — комментарий в
        // нашем же коде (clientLaunch/appendLeads.ts), API этого не описывает.
        //
        // Чего флаг НЕ держит (и почему его перевод в false не ломает
        // идемпотентность): повторный сбор тех же компаний исключён на сборке
        // (loadOtherBaseExclusionKeys), повторный прогон ТОЙ ЖЕ базы — стартовым
        // гейтом стадии ('collecting') и бронью дня ('repeat_run'), а
        // окончательность ночи даёт терминальная запись базы. Единственное, что
        // держит именно флаг, — второе письмо адресу, который уже в НАШЕЙ
        // кампании; при переводе в false этот отсев придётся делать самим,
        // чтением из lib/instantly/leadPresenceProbe, и «не знаю» тогда обязано
        // означать «не отправлять».
        //
        // ОДИН СЛУЧАЙ, ГДЕ ФЛАГ РАБОТАЕТ НЕ ЗАПАСНЫМ, А ЕДИНСТВЕННЫМ: перехват
        // своей брони ('reclaimed'). Предшественник этой базы умер, не записав
        // ни строки прогона, ни закрытия брони, но МОГ успеть отдать часть
        // пачки провайдеру; наследник шлёт её заново, и именно флаг делает так,
        // что второе письмо не уходит (эти строки вернутся как skipped, не
        // accepted). Поэтому перевод флага в false обязан идти вместе с
        // собственным отсевом — иначе перехват начнёт писать людям дважды.
        skipIfInCampaign: true,
        // Происхождение пачки в ОБЩЕМ построчном журнале доставки
        // (client_campaign_contact_ledger / client_campaign_append_batches).
        // Журнал пишется и без этого — но под дефолтным `campaign_append`,
        // в котором ночной добор ENG неотличим от ручной доливки RU-контура.
        // Своего ключа источника достаточно, чтобы строки ENG можно было найти
        // и сопоставить с he_jobs; ни одной строки RU это не меняет (журнал
        // скоупится client_user_id, а source_kind отчётность только проецирует,
        // см. lib/clientReports/exportSql.ts).
        ledgerSource: { kind: 'he_auto_refill', jobId: job.id },
        // Ночной долив — доверенный серверный оркестратор, а не браузер
        // клиента: объём уже срезан серверным `daily_leads_cap` (шаг 5 выше),
        // поэтому self-serve тарифный гейт к нему не применяется. Без этой
        // строки ENG-клиент получал 403 «Подписка не активна» ПОСЛЕ оплаченного
        // сбора (у него тариф неактивен или отсутствует), тогда как ручной
        // запуск ENG-кампании гейта не имеет вовсе. Ветка ENG-only по
        // построению: payload.refill ставит только крон autoPipeline, который
        // берёт лишь конфиги проектов he_projects.market='us'.
        //
        // Флаг снимает гейт ЦЕЛИКОМ (appendLeads.ts:245) — вместе с «подписка
        // не активна» отключаются удержание на прогреве почт, «оформлена, но
        // не оплачена» и тарифный лимит контактов. Для ENG это осознанно:
        // ящики, прогрев и расписание ведёт студия по договору, а не тариф
        // клиента; объём режет daily_leads_cap. НЕ затрагиваются (они вне
        // гейта): blocklist владельца, доменная политика, отказ Instantly по
        // лимитам воркспейса и журнал отправок. Вторая возможная опция —
        // `agency_managed` у ENG-пресета при провижининге, см. шапку
        // autoPipeline.ts.
        entitlementMode: 'managed_contract',
        // Кончилось место в воркспейсе — ПАУЗА, а не 402 поверх оплаченного
        // сбора: appendLeadsToClientCampaign грузит столько, сколько влезает,
        // и возвращает capacityBlocked вместо броска (и помечает не уехавшие
        // строки deferred, а не окончательно отсеянными). Ночной долив —
        // единственный ENG-путь, который упирается в ёмкость без человека
        // рядом, и разница «некуда грузить» против «адреса плохие» решает,
        // пересобирать базу или ждать места.
        pauseOnWorkspaceCapacity: true,
        // Признак жизни на КАЖДОЙ попытке отправки чанка (хук зовётся после
        // допуска лимитера, прямо перед HTTP). Без него ночной долив был
        // невидим для сторожа простоя стадии: blocklist, кап и загрузка идут
        // через supabaseInstantly и HTTP Instantly, то есть ни ctx.supabase, ни
        // ctx.log, ни ctx.onActivity не дёргаются, и медленная ночь провайдера
        // обрывалась аварийным выходом процесса ПОСРЕДИ загрузки: лиды уже
        // приняты, refill_result нет, строки журнала прогона нет, а повтор
        // грузит их заново — от дублей остаётся только skipIfInCampaign.
        //
        // Побочный эффект хука осознан (appendLeads.ts:380): вместе с ним
        // включаются timeoutMs=90_000 и timeoutIncludesBody=true — это нам и
        // нужно, иначе зависшее ЧТЕНИЕ ТЕЛА ответа не ограничено ничем, — и
        // выключается retryRateLimits, то есть 429 больше не пересиживается
        // внутри клиента (4+8+16 с). Обмен сознательный: отказ по 429 долив
        // ловит сам, пишет прогон 'failed' с причиной, ВОЗВРАЩАЕТ компании в пул
        // (429 доказывает, что строки не приняты — refillRateLimitRefusal) и его
        // повторит крон следующей ночью, тогда как аварийный выход посреди
        // загрузки не оставлял ни причины, ни журнала и приводил к повторной
        // отправке. Развязать три опции в appendLeads.ts было бы чище, но этот
        // файл общий с оплачиваемым RU-кабинетом — решение владельца.
        //
        // Тот же хук — ОГРАДА ВЛАДЕНИЯ (так он и задуман в appendLeads.ts:
        // «runs just before each HTTP attempt, after rate admission»): перед
        // каждым чанком прогон перечитывает, вправе ли он отправлять
        // (assertRefillOwnership). Бросок здесь случается ДО того, как индексы
        // чанка попадут в attemptedIndexes, поэтому снимок частичного отказа
        // честно говорит «этот чанк не уходил»; принятые раньше чанки в нём
        // остаются принятыми.
        beforeProviderRequest: async () => {
          ctx.onActivity?.();
          await assertRefillOwnership();
        },
      });
      // 6b. Кампании по очереди, каждая — тем же вызовом с теми же оградами
      //     (blocklist и доменная политика внутри appendLeads, managed_contract,
      //     skipIfInCampaign, пауза по ёмкости, журнал доставки, хук владения
      //     перед каждым чанком) плюс проверка владения перед каждой следующей
      //     кампанией (и перед первой, если раскладка шла: прошло время).
      //     Итоги сводятся в ОДИН итог по всей пачке (mergeRefillAppendResults),
      //     поэтому всё ниже — бронь, судьба компаний, перенос — читает их ровно
      //     как один вызов с несколькими чанками. Воркспейс переполнился —
      //     следующие кампании не трогаем: их строки — хвост, который пауза не
      //     начала отправлять (stats.deferred, перенос). Отказ кампании —
      //     отказ ночи, как отказ чанка: первая бросает как есть, следующие —
      //     снимком частичного приёма по всей пачке (refillGroupFailure).
      //     ИСКЛЮЧЕНИЕ — сегментная кампания, отказавшая явно и не принявшая ни
      //     строки (блок «РАСКЛАДКА», п. 7): её строки этим же прогоном уходят в
      //     основную кампанию, если та подтверждена, и ночь идёт дальше.
      let appended = emptyRefillAppendResult();
      let offset = 0;
      /**
       * Основная кампания ответила этой ночью: её вызов вернулся штатно и хотя
       * бы один запрос к ней получил ответ (у appendLeads штатный возврат с
       * попыткой = ответ 2xx на каждый отправленный чанк). Её группа — первая
       * в пачке, поэтому к любой сегментной кампании это уже известно.
       */
      let mainAnswered = false;
      /** Основную подтвердил журнал доставки прошлых ночей; null — не читали. */
      let mainAcceptedBefore: boolean | null = null;
      for (const [index, group] of routing.groups.entries()) {
        let part: AppendLeadsResult;
        try {
          if (index > 0 || routing.worked) await assertRefillOwnership();
          part = await appendGroup(group.campaignId, group.leads);
          if (group.segment === null && part.attemptedIndexes.length > 0) mainAnswered = true;
          if (group.segment === null) mainAccepted += part.accepted;
        } catch (e) {
          // Принятое основной до броска — тоже в ней («ПОВТОРНЫЙ СТАРТ»).
          if (group.segment === null && e instanceof AppendLeadsPartialError) mainAccepted += e.partialResult.accepted;
          // ПАУЗА КЛИЕНТА ВО ВРЕМЯ ЗАГРУЗКИ: проверка владения увидела Pause
          // (перед этой кампанией или перед её чанком) и бросила ДО запроса —
          // дальше не шлём ничего. Принятое раньше — итог ночи (разбор после
          // цикла); сводный снимок — тот же, что у отказа кампании.
          if (sendStop) {
            appended = refillGroupFailure(e, appended, offset).partialResult;
            break;
          }
          const refusedStatus = group.segment !== null ? refillSegmentCampaignRefusal(e) : null;
          if (refusedStatus === null) throw offset === 0 ? e : refillGroupFailure(e, appended, offset);
          // Сегментная кампания отказала явно, лидов в ней этой ночью не
          // создано (п. 7). Закреплённые за ней лиды (п. 7г) в основную не
          // идут и считаются возможно доставленными; остальные — в основную.
          const pinnedAt: number[] = [];
          const resendAt: number[] = [];
          group.leads.forEach((lead, i) => (group.pinned.has(lead) ? pinnedAt : resendAt).push(i));
          const pinnedReached = pinnedAt.map((i) => i + offset);
          const refusal: NonNullable<HeRefillStats['segment_refusals']>[number] = {
            campaign_id: group.campaignId,
            http_status: refusedStatus,
            leads: group.leads.length,
            pinned: pinnedAt.length,
            fate: 'not_sent',
          };
          runStats.segment_refusals = [...(runStats.segment_refusals ?? []), refusal];
          // Лог и алерт — когда итог переотправки известен (п. 7е).
          const reportRefusal = (fate: typeof refusal.fate, detail: string): void => {
            refusal.fate = fate;
            stageLog(
              ctx,
              `[base_collect] refill: ВНИМАНИЕ — кампания сегмента ${group.campaignId} ` +
                `(«${(group.segment ?? '').slice(0, 60)}») ответила HTTP ${refusedStatus}, не приняв ни строки ` +
                `(удалена или в архиве у рассыльщика?): лидов ${group.leads.length}, из них закреплено за ней ` +
                `${pinnedAt.length} (не переотправляются, считаются возможно доставленными); ${detail}`,
            );
            alertRefillSegmentRefused(job, base, args.market, {
              campaignId: group.campaignId,
              mainCampaignId: pick.campaignId,
              segment: group.segment ?? '',
              httpStatus: refusedStatus,
              leads: group.leads.length,
              pinned: pinnedAt.length,
              fate,
            });
          };
          if (resendAt.length === 0) {
            // Переотправлять нечего: вся группа закреплена за этой кампанией.
            part = refillAddReachedPositions(
              { ...emptyRefillAppendResult(), deferredIndexes: [], capacityBlocked: false },
              pinnedAt,
            );
            reportRefusal('none', 'остальных нет — в основную не переотправлено ничего');
          } else {
            if (!mainAnswered && mainAcceptedBefore === null) {
              mainAcceptedBefore = await readHeRefillCampaignAccepted(ctx, {
                ownerUserId,
                campaignId: pick.campaignId,
              });
            }
            if (!mainAnswered && mainAcceptedBefore !== true) {
              // Отказ сегмента — «не создано»: refillGroupFailure кладёт его
              // попытки в deferred (и при offset 0 — сегмент во главе пачки);
              // закреплённые возвращаются в «могли дойти».
              reportRefusal(
                'not_sent',
                `основная кампания ${pick.campaignId} этой ночью не подтверждена — ${resendAt.length} лид. ` +
                  'не отправлены и с брони не списаны',
              );
              const failure = refillGroupFailure(e, appended, offset);
              throw new AppendLeadsPartialError(
                failure.message,
                refillAddReachedPositions(failure.partialResult, pinnedReached),
              );
            }
            let resent: AppendLeadsResult;
            try {
              // Те же ограды, что у основной группы: владение — до вызова и в
              // хуке перед каждым чанком, остальное — внутри appendGroup.
              await assertRefillOwnership();
              resent = await appendGroup(pick.campaignId, resendAt.map((i) => group.leads[i]));
            } catch (resendError) {
              if (resendError instanceof AppendLeadsPartialError) mainAccepted += resendError.partialResult.accepted;
              const remapped =
                resendError instanceof AppendLeadsPartialError
                  ? new AppendLeadsPartialError(
                      resendError.message,
                      refillRemapAppendResult(resendError.partialResult, resendAt),
                    )
                  : resendError;
              const failure = refillGroupFailure(remapped, appended, offset);
              const reached = refillReachedPositions(failure.partialResult);
              const resentAccepted =
                resendError instanceof AppendLeadsPartialError && resendError.partialResult.accepted > 0;
              const fate = resentAccepted
                ? 'main'
                : resendAt.some((i) => reached.has(offset + i))
                  ? 'unknown'
                  : 'not_sent';
              reportRefusal(
                fate,
                `переотправка ${resendAt.length} лид. в основную кампанию ${pick.campaignId} не удалась ` +
                  `(${resendError instanceof Error ? resendError.message : String(resendError)}) — ` +
                  (fate === 'not_sent'
                    ? 'строки не отправлены и с брони не списаны'
                    : fate === 'main'
                      ? 'часть принята до отказа'
                      : 'ответа нет: строки считаются возможно доставленными'),
              );
              // Pause клиента во время переотправки — та же остановка, что выше.
              if (sendStop) {
                appended = refillAddReachedPositions(failure.partialResult, pinnedReached);
                break;
              }
              throw new AppendLeadsPartialError(
                failure.message,
                refillAddReachedPositions(failure.partialResult, pinnedReached),
              );
            }
            if (resent.attemptedIndexes.length > 0) mainAnswered = true;
            mainAccepted += resent.accepted;
            part = refillAddReachedPositions(refillRemapAppendResult(resent, resendAt), pinnedAt);
            reportRefusal(
              'main',
              `${resendAt.length} лид. переотправлены в основную кампанию ${pick.campaignId} с основным текстом ` +
                `(принято ${resent.accepted})`,
            );
          }
        }
        appended = mergeRefillAppendResults(appended, part, offset);
        offset += group.leads.length;
        if (appended.capacityBlocked === true) break;
      }
      // ПАУЗА КЛИЕНТА ВО ВРЕМЯ ЗАГРУЗКИ — итог. Провайдер не получил ничего
      // (ни принятого, ни попытки без ответа) — это пропуск шага 4c
      // этой причиной (catch: очередь переноса, лента «daily top-up skipped —
      // you had paused this market» и т. п.). Получил — обычная ночь с тем, что ушло
      // до паузы: 'appended' с принятым, компании без единого письма — в
      // очередь переноса (успешная ветка ниже). Строки, ушедшие до паузы,
      // лежат в кампании, которую клиент поставил на паузу, и уйдут после
      // Resume — не раньше.
      if (sendStop) {
        if (appended.accepted === 0 && refillAttemptsNotProvenRefused(appended) === 0) {
          runStats.sending_skip = sendStop;
          throw new Error(
            `${REFILL_SENDING_SKIP_NOTE} (${sendStop}): ${REFILL_SEND_STOP_TEXT[sendStop]} до того, как провайдер ` +
              'получил хоть одну строку',
          );
        }
        stageLog(
          ctx,
          `[base_collect] refill: ${REFILL_SEND_STOP_TEXT[sendStop]} во время загрузки — следующие чанки не ` +
            `отправлены; принято до остановки ${appended.accepted}, компании без единого письма уходят в очередь переноса`,
        );
      }
      // Удержанные раскладкой строки (хвост sentBatch) провайдеру не шли;
      // закреплённые за неотправляющей кампанией — «возможно доставлены».
      appendOutcome = refillAddReachedPositions(appended, heldReached);
      runStats.appended = appended.accepted;
      runStats.skipped_instantly = appended.skipped;
      // Провайдер уже видел строки. Если дальше упадёт запись базы, компании
      // обратно в сборку отдавать нельзя (см. refillLeadsReachedProvider).
      // Попытки, которые провайдер сам отклонил по ёмкости (deferredIndexes),
      // доставкой не считаются — то же правило, что у отказа в catch'е: 200 с
      // нулём принятого и нулём места в воркспейсе раньше записывал ночь
      // 'appended' с нулём и выжигал её компании.
      providerTouched = appended.accepted > 0 || refillAttemptsNotProvenRefused(appended) > 0;
      if (appended.capacityBlocked === true) {
        // Воркспейс полон — это доказано ответом самого провайдера, а не
        // угадано. Причину запоминаем здесь, а пишем паузу после терминальных
        // записей (см. recordRefillCapacityPause). Команде сообщаем СРАЗУ, до
        // терминальных записей (alertRefillCapacityStop): кабинет напишет
        // клиенту «команда уже работает» по этой же ночи.
        capacityPauseSource = `долив базы ${base.id} (провайдер перестал принимать строки)`;
        alertRefillCapacityStop(ctx, job, base.id, capacityPauseSource);
        // Остаток пачки: принято + окончательно отсеяно ≤ отдано, разница —
        // строки, которым не хватило места (явный отказ на чанке + хвост,
        // который пауза не начала отправлять).
        const deferred = Math.max(0, toSend.length - heldCount - appended.accepted - appended.skipped);
        if (deferred > 0) {
          runStats.deferred = deferred;
          runStats.deferred_reason = 'instantly_capacity';
        }
        if (!providerTouched) {
          // Провайдер не принял НИ ОДНОЙ строки — до запроса не дошло (ноль
          // места по предполёту appendLeads) либо он сам отказал по ёмкости
          // на каждой отданной строке. Это отказ, а не долив: уходим в общий
          // catch, чтобы база стала 'failed' и её компании вернулись в пул
          // (по тому же правилу серии отказов), а бронь закрылась нулём. Иначе ночь
          // записалась бы как 'appended' с нулём, а оплаченные компании
          // остались бы выжженными — при том что доливать было НЕКУДА и
          // завтрашняя ночь отправила бы их же, если место освободится.
          throw new Error(
            `${REFILL_CAPACITY_NOTE} — провайдер не принял ни одной строки из ${toSend.length}`,
          );
        }
        // Часть строк уехала: база остаётся 'analyzed' (компании отработаны),
        // остаток виден в stats.deferred. Durable-пауза ниже останавливает
        // ПРОЕКТ, а не хранит остаток; остаток хранит ПЕРЕНОС (только 'us'):
        // компании, ни один адрес которых не дошёл до провайдера, уходят в
        // очередь ниже и после снятия паузы идут первыми. Вторые адреса
        // компаний, получивших письмо, не досылаются — компания охвачена.
        stageLog(
          ctx,
          `[base_collect] refill: место в воркспейсе кончилось на доливе — ` +
            `принято ${appended.accepted}, не уехало ${deferred} стр. ` +
            (carryEnabled
              ? '(компании без единого письма уходят в очередь переноса и пойдут первыми после снятия паузы)'
              : '(эти строки не досылаются: пауза останавливает ночной добор проекта, а не хранит остаток)'),
        );
      }
    }
    // 'no_new' — только когда отправлять было нечего НИ из своей сетки, НИ из
    // очереди переноса: ночь, отправившая перенесённые компании, добавила
    // контакты, и правило сухой вертикали обязано это видеть. Ночь, у которой
    // шаг 3a снял ВСЕ допущенные СВОИ строки, — тоже 'appended' (с нулём):
    // рынок строки дал, не годятся письма, и сухой её не считаем; о ней уже
    // сообщил алерт команде (alertRefillLettersHeld). Перенесённые компании,
    // которые письма держат и этой ночью, в carriedValid не входят: ночь без
    // своих строк с такой очередью — 'no_new', как и до их переноса.
    const outcome: HeRefillResult['status'] =
      valid === 0 && carriedValid === 0 ? 'no_new' : 'appended';

    // ПЕРЕНОС — решения считаются ДО терминальных записей (их числа уезжают в
    // refill_result и строку прогона), а пишутся ПОСЛЕ них (см. ниже).
    let carrySettle: HeRefillCarrySettle | null = null;
    let ownQueue: HeRefillCarryQueuePlan | null = null;
    if (carryEnabled && carryClaim) {
      const reached = refillReachedPositions(appendOutcome);
      if (carryClaim.companies.length > 0) {
        carrySettle = planHeRefillCarrySettle({
          companies: carryClaim.companies,
          ownerOf: carriedLeadOwner,
          inKept: carriedInKept,
          held: carriedHeld,
          batch: sentBatch,
          reached,
          // Успешная ветка: бронь выдана этому прогону, неизвестных нет.
          unknown: null,
        });
      }
      ownQueue = planOwnQueue(reached);
      noteCarryStats(carrySettle, ownQueue);
    }

    const refillResult: HeRefillResult = {
      status: outcome,
      campaign_id: pick.campaignId,
      stats: runStats,
      // Тот же признак, что и у пустого harvest'а: 'no_new' здесь означает
      // «строки собрались, но допущенных адресов нет», и судить по такой ночи
      // о сухости можно только когда каталог дочитан. Пишется и при
      // 'appended' — форма строки прогона не должна зависеть от исхода.
      scan_complete: refillScanComplete(info),
      completed_at: new Date().toISOString(),
    };
    await persistRefillBase(ctx, base.id, {
      columns: finalColumns, rows: finalRows, info, stats, refillResult, status: 'analyzed',
    });
    // Бронь закрывается ПОСЛЕ терминальной записи базы: пока она открыта,
    // занятым считается весь выданный объём, и падение этой записи оставляет
    // бюджет занятым (недоотправка), а не свободным (отправка поверх капа).
    await finalizeRefillDailyBudget(ctx, {
      reservationId,
      baseId: base.id,
      consumed: runStats.appended,
    });
    // Завершённая основная приняла контакты — стартуем её снова (исход — в
    // строку прогона ниже).
    await restartCompletedMain(false);
    await writeRefillRun(ctx, {
      configId: config?.id ?? null,
      projectId: job.project_id,
      verticalId: base.vertical_id,
      baseId: base.id,
      result: refillResult,
    });
    stageLog(
      ctx,
      `[base_collect] refill ${outcome}: кампания ${pick.campaignId}` +
        // Ночь разложена по сегментам — пачка делилась и на сегментные
        // кампании запуска (разбивка по кампаниям — строкой раскладки выше).
        (segmentGroups > 0 ? ` (+ сегментных в раскладке: ${segmentGroups})` : '') +
        // Строки неотправляющих сегментов — не ушли никуда (п. 4 раскладки).
        (heldCount > 0 ? ` [удержано неотправляющими сегментами: ${heldCount} лид.]` : '') +
        // Сегментная кампания отказала, и её строки ушли в основную (п. 7).
        refillSegmentRefusalsNote(runStats) +
        `, лидов ${runStats.appended} ` +
        `(valid ${runStats.valid}, без вердикта ${runStats.unverified}, ` +
        (runStats.held_unfilled ? `письмо прочиталось бы неверно ${runStats.held_unfilled}, ` : '') +
        `blocklist ${runStats.skipped_blocklist}, кап-отрез ${runStats.capped}` +
        // Причина отреза и сколько КОМПАНИЙ остались без письма — рядом с
        // числом строк: «отрезано 150» без них не отличает дневной кап от
        // повтора прогона и не говорит, сколько оплаченных компаний сгорело.
        (runStats.capped_reason ? ` (${runStats.capped_reason})` : '') +
        (runStats.capped_companies !== undefined
          ? `, компаний без письма ${runStats.capped_companies}`
          : '') +
        ' ' +
        // Остаток капа при нулевом отрезе — признак НЕДОбора: компаний собрали
        // меньше, чем нужно капу (см. HE_REFILL_ACCEPTED_PER_COMPANY). '?' —
        // остаток не измерен (брони не было либо она ничего не считала):
        // писать здесь ноль значило бы объявить бюджет исчерпанным.
        `при остатке ${runStats.daily_remaining ?? '?'} из ${runStats.daily_cap}` +
        // Исход брони и выданный объём — ЗДЕСЬ, а не только в jsonb прогона:
        // без них строка лога не отвечает, почему отправлено меньше, чем
        // допущено, и чем 'reclaimed'-ночь (доедаем хвост умершего прогона)
        // отличается от обычной. Ключей нет — бронь не бралась (отправлять
        // было нечего), и писать про неё нечего.
        `${runStats.budget_outcome === undefined
          ? ''
          : `, бронь ${runStats.budget_outcome} на ${runStats.reserved ?? 0} стр.`})`,
    );
    // ПЕРЕНОС — после терминальных записей: компании ночи ложатся в очередь,
    // только когда их база уже 'analyzed' (то есть держит их исключёнными), а
    // итог перенесённых — когда отправка этой ночи записана.
    if (carrySettle) await settleHeRefillCarryover(ctx, base.id, carrySettle);
    const ownQueued = ownQueue ? await writeHeRefillCarryQueue(ctx, ownQueue) : true;
    if (runStats.carryover) {
      const c = runStats.carryover;
      stageLog(
        ctx,
        `[base_collect] refill: перенос — из очереди предложено ${c.offered} компаний ` +
          `(ушли ${c.sent}, вернулись в очередь ${c.returned}, сняты ${c.dropped}, срок вышел ${c.released}); ` +
          `в очередь от этой ночи ${c.queued}` +
          (c.released_hiring ? `, сразу в пул (крючок найма не доживёт свежим) ${c.released_hiring}` : '') +
          (ownQueued ? '' : ' — ЗАПИСЬ НЕ ЛЕГЛА, эти компании остаются исключёнными') +
          refillCarryHeldNote(c) +
          (runStats.carry_only ? '; сборка этой ночью не покупалась' : ''),
      );
    }
    // Переполнение воркспейса переживает эту ночь: завтрашний тик проекту
    // сборку не купит, пока сотрудник не возобновит добор. Последним шагом —
    // все записи, фиксирующие потраченное, уже сделаны.
    if (capacityPauseSource) {
      await recordRefillCapacityPause(ctx, job.project_id, capacityPauseSource);
    }
    return done(refillResult);
  } catch (e) {
    // Ошибка долива НЕ валит джобу (см. шапку): база сохраняется с
    // refill_result.error, прогон журналируется 'failed'.
    //
    // Причина классифицируется рядом с текстом: отказ по ёмкости воркспейса —
    // не брак данных, а нехватка места у рассыльщика; он ставит durable-паузу
    // добора проекта (последний шаг этой ветки), и снимает её сотрудник —
    // сам по таймеру добор не возобновится. Маркер
    // REFILL_CAPACITY_NOTE дописывается в начало текста, чтобы причина читалась
    // и в he_bases.error (кабинет сворачивает его в машинный код), а не только
    // в машинном error_kind.
    //
    // ЧАСТИЧНЫЙ ПРИЁМ — отдельная ветка, и это деньги, а не отчётность.
    // AppendLeadsPartialError несёт СНИМОК результата: провайдер мог принять
    // часть пачки и упасть на следующем чанке или на записи журнала. Пока эту
    // ветку не разбирали, runStats.appended оставался нулём — то есть ночь,
    // отправившая настоящие письма, записывалась как не отправившая ничего:
    // дневной расход исчезал (refillAppendedToday его не видел), воронка
    // врала, а следующая вертикаль получала тот же объём второй раз.
    // Числа берём из снимка как есть; судьбу компаний решает не он, а
    // delivered ниже.
    const partial = e instanceof AppendLeadsPartialError ? e.partialResult : null;
    /**
     * Строк, ушедших в транспорт и НЕ отклонённых провайдером явно: их приём не
     * подтверждён и не опровергнут (refillAttemptsNotProvenRefused). Строки,
     * которые провайдер сам отказался взять по ёмкости, сюда не входят — они
     * точно не созданы. Как и отказанный запрос кампании, которую
     * refillGroupFailure разбирает отдельно: кампания НЕ первой в пачке ответила
     * 4xx (в том числе 429), не приняв ни строки; сегментная кампания во главе
     * пачки отказала явно, и строки не ушли в основную (блок «РАСКЛАДКА»,
     * п. 7б); повторная отправка строк сегмента в основную отказала явно.
     * Остальной отказ ПЕРВОЙ кампании пачки бросается как есть (одним вызовом,
     * как до раскладки), и 429 на ней сюда входит: снимок без deferred.
     */
    let attempted = 0;
    if (partial) {
      runStats.appended = partial.accepted;
      runStats.skipped_instantly = partial.skipped;
      attempted = refillAttemptsNotProvenRefused(partial);
    }
    const capacityRefusal = refillCapacityRefusal(e);
    if (capacityRefusal) {
      runStats.error_kind = 'instantly_capacity';
      // Тот же доказанный факт, что и в успешной ветке: провайдер сам отказал
      // по ёмкости. Источник причины перезаписываем только если его ещё нет —
      // первым увидел тот, кто увидел раньше. Алерт команде — там же, где
      // источник впервые присвоен (успешная ветка уже отправила свой), и до
      // терминальных записей ниже.
      if (capacityPauseSource === null) {
        capacityPauseSource = `долив базы ${base.id} (провайдер отказал по ёмкости)`;
        alertRefillCapacityStop(ctx, job, base.id, capacityPauseSource);
      }
      // Строки, которые провайдер ОТКАЗАЛСЯ взять по ёмкости, он перечисляет
      // сам (deferredIndexes непустой только при pauseOnWorkspaceCapacity).
      // Хвост, до которого отправка не дошла, в это число не входит — считать
      // его тут нечем, а завышать воронку нельзя.
      const deferred = partial?.deferredIndexes?.length ?? 0;
      if (deferred > 0) {
        runStats.deferred = deferred;
        runStats.deferred_reason = 'instantly_capacity';
      }
    }
    // Отмена клиентом — не сбой среза (см. шапку файла, refillUserCancelled).
    // Потеря владения перед провайдером — та же отмена, замеченная раньше
    // наблюдателя воркера (HeRefillOwnershipLoss): тот же разбор ниже —
    // компании в пул без серии отказов, без очереди собственных компаний.
    const cancelled = refillUserCancelled(ctx) || ownershipLoss !== null;
    if (cancelled) runStats.cancelled = true;
    // Отмена выигрывает у пропуска шага 4c: чтения проверки после обрыва
    // сигнала отказывают, и её «не читается» — следствие отмены, а не причина.
    if (cancelled) delete runStats.sending_skip;
    const rawMessage = e instanceof Error ? e.message : String(e);
    const message = (
      capacityRefusal && !rawMessage.includes(REFILL_CAPACITY_NOTE)
        ? `${REFILL_CAPACITY_NOTE} — ${rawMessage}`
        : rawMessage
    ).slice(0, 500);
    // Провайдер ничего не получил → база терминально 'failed', и её компании
    // остаются доступны следующей сборке проекта. Успел получить (или мы не
    // знаем наверняка) → прежнее 'analyzed': компании считаются отработанными,
    // второе письмо тому же лиду дороже потерянного лида.
    const delivered = providerTouched || refillLeadsReachedProvider(e);
    // Pause клиента, увиденная проверкой владения до того, как провайдер
    // получил хоть строку (перед раскладкой, перед первой кампанией), — тот же
    // пропуск 'client_paused', что у шага 4c (п. 3б ниже). Отмена выигрывает.
    if (sendStop && !delivered && !cancelled && runStats.sending_skip === undefined) {
      runStats.sending_skip = sendStop;
    }
    // РЕШЕНИЕ О КОМПАНИЯХ — по ВСЕМУ набору исходов отказа:
    //  1. доставлено (или не знаем) → 'analyzed'. У market='us' компании, до
    //     которых отправка не дошла (их срезал кап, отказ провайдера случился
    //     раньше их чанка), ложатся в очередь переноса — как у успешной ночи,
    //     ПОСЛЕ терминальной записи базы; кроме отмены клиентом;
    //  2. бронь держит прошлый прогон ЭТОЙ базы ('already_reserved': двойник
    //     при перекрытии деплоя либо умерший предшественник моложе окна
    //     перехвата) → 'analyzed', без очереди. Тот прогон мог уже отдать
    //     строки, а его приём нам не виден — это тот же случай «не знаем», что
    //     и п. 1, и любая повторная отправка могла бы стать вторым письмом;
    //  3. бюджет проекта не дал базе ни строки ('cap_exhausted'): провайдер от
    //     этой базы сегодня не получил ничего, причина — чужой расход капа.
    //     У market='us' (решение владельца 04.10.2026) — 'analyzed', а все её
    //     компании с лидом — в очередь переноса, ДО терминальной записи и одним
    //     запросом; очередь не легла (или класть нечего) — 'failed', прежний
    //     возврат в пул. Вне market='us' — 'failed' всегда. Серия отказов тут
    //     не спрашивается и сама ночь в неё не попадёт (refillStreakVerdict) —
    //     иначе вторая такая ночь подряд выжигала бы оплаченный срез без
    //     единого письма;
    //  3б. кампании запуска не брали контакты (stats.sending_skip: шаг 4c до
    //     брони или Pause клиента до первого чанка загрузки) — провайдер не
    //     получил ничего, и решил не срез: тот же исход, что у п. 3
    //     (market='us' — очередь переноса, иначе возврат в пул), и в серию
    //     отказов ночь не идёт;
    //  4. отмена клиентом без доставки → 'failed' всегда: решение человека, а
    //     не свойство среза, в серию тоже не идёт;
    //  5. остальное (не дошло до провайдера по нашей или его причине) → серия
    //     отказов: возврат только первому подряд (REFILL_RELEASE_FAIL_STREAK_LIMIT),
    //     иначе ночной крон собирал бы тот же срез снова и снова.
    const predecessorHoldsBudget = !delivered && runStats.budget_outcome === 'already_reserved';
    const budgetSpentElsewhere = !delivered && runStats.budget_outcome === 'cap_exhausted';
    const sendingSkipped = !delivered && runStats.sending_skip !== undefined;
    // Что дошло (или могло дойти) до провайдера — одно правило для своих и
    // перенесённых компаний (refillLeadsReachedProvider): явный 429 при
    // нулевом приёме доказывает, что не создано ничего.
    const reached = appendOutcome
      ? refillReachedPositions(appendOutcome)
      : partial && partial.accepted === 0 && refillRateLimitRefusal(e)
        ? new Set<number>()
        : refillReachedPositions(partial);
    // Удержанные раскладкой строки, закреплённые за неотправляющей кампанией,
    // — «возможно доставлены» и здесь (у appendOutcome они уже внутри).
    for (const position of heldReached) reached.add(position);
    // Очередь собственных компаний — только у п. 1 и п. 3 (market='us') и
    // только без отмены клиентом: отменённый прогон — решение человека, его
    // компании решает прежнее правило (п. 1 — исключены, п. 4 — в пул), и
    // следующие ночи не досылают за него то, что он не успел.
    const ownQueue =
      (delivered || budgetSpentElsewhere || sendingSkipped) && !cancelled ? planOwnQueue(reached) : null;
    /** null — серия решению не понадобилась и не читалась. */
    let failStreak: number | null = null;
    let released: boolean;
    /** П. 3 и 3б у market='us': очередь записана, база 'analyzed'. */
    let budgetStopCarried = false;
    if (delivered || predecessorHoldsBudget) {
      released = false;
    } else if ((budgetSpentElsewhere || sendingSkipped) && ownQueue && (await writeHeRefillCarryQueue(ctx, ownQueue))) {
      released = false;
      budgetStopCarried = true;
    } else if (budgetSpentElsewhere || sendingSkipped || cancelled) {
      released = true;
    } else {
      failStreak = await refillFailStreak(ctx, base.vertical_id, base.id);
      released = failStreak < REFILL_RELEASE_FAIL_STREAK_LIMIT;
    }
    // Перенесённые компании, которые провайдер не получил, возвращаются в
    // очередь со старым сроком, получившие — 'sent'. Исход 'already_reserved' —
    // единственный, где про перенесённую компанию НЕ известно, дошла ли она:
    // прошлый прогон ЭТОЙ базы, державший её захват, мог её отправить. Такие
    // (heldBefore) снимаются в 'dropped'; взятые из очереди только сейчас
    // прошлому прогону не доставались и возвращаются.
    let carrySettle: HeRefillCarrySettle | null = null;
    if (carryEnabled && carryClaim && carryClaim.companies.length > 0) {
      carrySettle = planHeRefillCarrySettle({
        companies: carryClaim.companies,
        ownerOf: carriedLeadOwner,
        inKept: carriedInKept,
        held: carriedHeld,
        batch: sentBatch,
        reached,
        unknown: predecessorHoldsBudget ? carryClaim.heldBefore : null,
      });
    }
    // В воронку — только очередь, которая записана (п. 3) или будет записана
    // после терминальной записи (п. 1); у п. 3 с упавшей записью её нет.
    if (carryEnabled) noteCarryStats(carrySettle, delivered || budgetStopCarried ? ownQueue : null);
    // Текст базы у отмены — ровно тот, что пишет ENG-роут отмены: кабинет
    // сверяет его полным совпадением и показывает отмену, а не «шаг не успел»
    // (текст AbortError прочитанного после отмены запроса классифицировался
    // как 'timeout'). Строка прогона и журнал сохраняют настоящий текст.
    // Пропуск шага 4c, чьи компании не легли в очередь (база 'failed'), — тем
    // же текстом: карточка прогона в кабинете говорит «этот прогон остановлен,
    // не закончив; пойдёт ли добор дальше — на Command Center» (engStageErrorText,
    // 'refill'), и это правда, а свой русский текст свёлся бы в «техническую
    // проблему». Причину клиент видит в ленте и строке «next» дашборда.
    const baseError = cancelled || sendingSkipped ? REFILL_CANCELLED_ERROR : message;
    const refillResult: HeRefillResult = {
      status: 'failed',
      stats: runStats,
      error: message,
      ...(capacityRefusal ? { error_kind: 'instantly_capacity' as const } : {}),
      delivery_attempted: delivered,
      companies_released: released,
      ...(budgetStopCarried ? { companies_carried: true as const } : {}),
      // Серию пишем только когда от неё зависело решение: в остальных исходах
      // записанный здесь ноль был бы неизмеренным.
      ...(failStreak === null ? {} : { fail_streak: failStreak }),
      completed_at: new Date().toISOString(),
    };
    // Причина видна в карточке базы, а не только в журнале прогонов — только
    // вместе со статусом 'failed' (у 'analyzed'-базы error пустой, см.
    // persistRefillBase).
    await persistRefillBase(ctx, base.id, {
      columns: finalColumns,
      rows: finalRows,
      info,
      stats,
      refillResult,
      ...(released ? { status: 'failed' as const, error: baseError } : { status: 'analyzed' as const }),
    });
    // Расходом отказа считается ПОПЫТКА, а не подтверждённый приём: строки,
    // ушедшие в транспорт, могли быть созданы и при потерянном ответе, и
    // освобождать под них бюджет значило бы разрешить отправку сверх капа тем
    // же адресам. Исключение — строки, которые провайдер явно отклонил по
    // ёмкости, и явный отказ (4xx, в том числе 429) кампании, не принявшей ни
    // строки, — но только кампании НЕ первой в пачке, сегментной во главе
    // пачки, чьи строки не ушли в основную, и повторной отправки строк
    // сегмента в основную (refillGroupFailure, см. attempted выше): они не
    // созданы, и держать под них бюджет значило бы списать с дня отправку,
    // которой не было. Явный отказ ПЕРВОЙ кампании пачки — основной или
    // сегментной, отказавшей 429, — бросается как есть, и его отказанные
    // строки списываются с брони, как у одного вызова до раскладки: это
    // недоотправка в пределах дня, а не отправка сверх капа. Отказ до первого
    // запроса освобождает бронь целиком (0) — и это важно: иначе одна
    // неудачная вертикаль съедала бы ночь всего проекта.
    await finalizeRefillDailyBudget(ctx, {
      reservationId,
      baseId: base.id,
      consumed: Math.max(runStats.appended, attempted),
    });
    // Отказ после частичной доставки: принятое завершённой основной — тоже
    // стартуем (без приёма вызова нет; отмена — без старта).
    await restartCompletedMain(cancelled);
    await writeRefillRun(ctx, {
      configId: config?.id ?? null,
      projectId: job.project_id,
      verticalId: base.vertical_id,
      baseId: base.id,
      result: refillResult,
    });
    stageLog(
      ctx,
      `[base_collect] refill failed: ${message}` +
        refillSegmentRefusalsNote(runStats) +
        // Тот же читатель полей брони, что и в успешной ветке: отказ после
        // выданной брони обязан показывать, сколько объёма было разрешено и
        // сколько оставалось от капа, — иначе по строке прогона не отличить
        // «бюджет не дал» от «дал, но упало». Ключа нет — бронь не бралась.
        (runStats.budget_outcome === undefined
          ? ''
          : ` [бронь ${runStats.budget_outcome} на ${runStats.reserved ?? 0} стр., ` +
            `остаток ${runStats.daily_remaining ?? '?'} из ${runStats.daily_cap}` +
            (runStats.capped > 0
              ? `, кап-отрез ${runStats.capped}${runStats.capped_reason ? ` (${runStats.capped_reason})` : ''}`
              : '') +
            ']') +
        (runStats.held_unfilled
          ? ` [не отправлено из-за писем ${runStats.held_unfilled} адр., строки в базе]`
          : '') +
        (ownershipLoss
          ? ` — остановлено перед отправкой (${ownershipLoss}): отмена выигрывает у долива`
          : cancelled
            ? ' — отменено клиентом'
            : '') +
        (delivered
          ? ` — строки уже у провайдера (принято ${runStats.appended}, в транспорте ${attempted}), ` +
            'база остаётся analyzed'
          : predecessorHoldsBudget
            ? ' — бронь держит прошлый прогон этой базы, который мог уже отправить строки: ' +
              'база остаётся analyzed, компании не возвращаем'
            : budgetStopCarried
              ? (sendingSkipped
                ? ' — провайдер строк не получил, кампании запуска не брали контакты: компании ночи '
                : ' — провайдер строк не получил, бюджет дня занят другими базами: компании ночи ') +
                'в очереди переноса (база analyzed), ночь в серию отказов не идёт'
            : released
              ? ' — провайдер строк не получил, база failed (компании не выжигаем)'
                + (budgetSpentElsewhere
                  ? ': бюджет дня занят другими базами, ночь в серию отказов не идёт'
                  : sendingSkipped
                    ? ': кампании запуска не брали контакты, ночь в серию отказов не идёт'
                    : '')
                + (refillRateLimitRefusal(e) ? ': отказ по частоте запросов, приёма не было' : '')
              : ` — отказ ${(failStreak ?? 0) + 1}-й подряд, компании остаются исключёнными ` +
                '(база analyzed): иначе ночной прогон собрал бы тот же срез заново'),
    );
    // Итог перенесённых — после записей о потраченном, клиентом без сигнала.
    if (carrySettle) await settleHeRefillCarryover(ctx, base.id, carrySettle);
    // Отказ после доставки: база уже 'analyzed' и держит свои компании
    // исключёнными — теперь те, до кого отправка не дошла, ложатся в очередь
    // (как у успешной ночи). Очередь ночи без бюджета записана выше, до базы.
    const ownQueued = delivered && ownQueue ? await writeHeRefillCarryQueue(ctx, ownQueue) : true;
    if (runStats.carryover) {
      const c = runStats.carryover;
      stageLog(
        ctx,
        `[base_collect] refill: перенос в отказе — из очереди предложено ${c.offered} компаний ` +
          `(ушли ${c.sent}, вернулись в очередь ${c.returned}, сняты ${c.dropped}, срок вышел ${c.released}); ` +
          `в очередь от этой ночи ${c.queued}` +
          (c.released_hiring ? `, сразу в пул (крючок найма не доживёт свежим) ${c.released_hiring}` : '') +
          (ownQueued ? '' : ' — ЗАПИСЬ НЕ ЛЕГЛА, эти компании остаются исключёнными') +
          refillCarryHeldNote(c),
      );
    }
    // Последним шагом, после всех записей о потраченном: отказ по ЁМКОСТИ
    // (и только он — 429, 402, сбой конструктора сюда не попадают, см.
    // refillCapacityRefusal) останавливает ночной добор проекта до явного
    // возобновления сотрудником.
    if (capacityPauseSource) {
      await recordRefillCapacityPause(ctx, job.project_id, capacityPauseSource);
    }
    return done(refillResult);
  }
}
